insert into public.mushroom_register_i18n (slug,lang,identifying_features,symptoms_if_toxic,emergency_action,cooking_preparation,cultural_notes,verified) values 
('amanita_battarrae','en','Ringless grisette with a distinctly striate cap margin and a characteristically two-toned, zoned cap, umber- to ochre-brown (darker marginal zone, lighter centre, or vice versa). Stem ringless, with a membranous, whitish grey-brown volva (sheath) at the base. No bulb.','Toxic raw: heat-labile haemolysins cause gastrointestinal symptoms when eaten raw or insufficiently cooked and can damage red blood cells. Destroyed by sufficient heating (at least 15–20 min) and then edible.',NULL,'Like all sheathed grisettes, eat only well cooked (heat for at least 15–20 min), never raw. Because of the risk of confusion with deadly Amanita species, collect only with reliable expertise; always dig up and check the volva.',NULL,false),
('amanita_battarrae','es','Amanita sin anillo (galamperna) con margen del sombrero claramente estriado y sombrero característicamente zonado en dos tonos, de pardo umbra a pardo ocre (zona marginal más oscura, centro más claro, o viceversa). Pie sin anillo, con volva membranosa blanquecino-gris-parda en la base. Sin bulbo.','Tóxico en crudo: hemolisinas termolábiles provocan, si se consume crudo o poco cocinado, trastornos gastrointestinales y pueden dañar los glóbulos rojos. Se destruyen con un calentamiento suficiente (al menos 15–20 min) y entonces es comestible.',NULL,'Como todas las amanitas con volva (galampernas), consumir solo bien cocinado (calentar al menos 15–20 min), nunca crudo. Por el riesgo de confusión con las amanitas mortales, recolectar solo por conocedores seguros; desenterrar siempre y examinar la volva.',NULL,false),
('amanita_battarrae','fr','Amanite sans anneau (golmotte) à marge du chapeau nettement striée et chapeau caractéristiquement zoné en deux teintes, brun ombre à brun ocre (zone marginale plus foncée, centre plus clair, ou inversement). Pied sans anneau, à volve membraneuse blanchâtre-gris-brun à la base. Pas de bulbe.','Toxique cru : des hémolysines thermolabiles provoquent, en cas de consommation crue ou insuffisamment cuite, des troubles gastro-intestinaux et peuvent endommager les globules rouges. Détruites par une cuisson suffisante (au moins 15–20 min) et alors comestible.',NULL,'Comme toutes les amanites à volve (golmottes), à consommer uniquement bien cuit (chauffer au moins 15–20 min), jamais cru. En raison du risque de confusion avec les amanites mortelles, à ne récolter que par des connaisseurs sûrs ; toujours déterrer et examiner la volve.',NULL,false),
('amanita_battarrae','it','Amanita senza anello (bubbola) con margine del cappello nettamente striato e cappello caratteristicamente zonato in due tonalità, da bruno ombra a bruno ocra (zona marginale più scura, centro più chiaro, o viceversa). Gambo senza anello, con volva membranosa biancastra-grigio-bruna alla base. Senza bulbo.','Tossico da crudo: emolisine termolabili provocano, in caso di consumo crudo o insufficientemente cotto, disturbi gastrointestinali e possono danneggiare i globuli rossi. Distrutte da una cottura sufficiente (almeno 15–20 min) e allora commestibile.',NULL,'Come tutte le amanite con volva (bubbole), da consumare solo ben cotto (riscaldare almeno 15–20 min), mai crudo. A causa del rischio di confusione con le amanite mortali, da raccogliere solo da conoscitori sicuri; dissotterrare sempre e controllare la volva.',NULL,false),
('amanita_echinocephala','en','Robust, whitish Amanita with conspicuously pyramidal, pointed, projecting whitish-grey veil warts on the cap (hedgehog-like). Stem with a rooting, deeply embedded, marginate bulb and an ephemeral ring. Gills and flesh often with a greenish tinge. Thermophilic, on calcareous soil.','Gastrointestinal symptoms (nausea) within 0–12 h; at higher doses, impaired liver and kidney function after 24–36 h. Consumption is discouraged. High risk of confusion with deadly white Amanita species (A. virosa, A. phalloides var. alba).','If ingested, call Tox Info Suisse 145 immediately, as confusion with deadly white Amanita species is possible. Keep mushroom remains; in case of organ involvement, call emergency services 144.',NULL,NULL,false),
('amanita_echinocephala','es','Amanita robusta, blanquecina, con verrugas del velo notablemente piramidales, puntiagudas y sobresalientes, de blanquecinas a grises sobre el sombrero (aspecto erizado). Pie con bulbo radicante, hundido profundamente en el suelo, marginado, y anillo fugaz. Láminas y carne a menudo con reflejo verdoso. Termófila, sobre suelo calcáreo.','Trastornos gastrointestinales (náuseas) en 0–12 h; a dosis elevadas, trastornos de la función hepática y renal tras 24–36 h. Se desaconseja su consumo. Alto riesgo de confusión con las amanitas blancas mortales (A. virosa, A. phalloides var. alba).','En caso de ingestión, llamar inmediatamente a Tox Info Suisse 145, ya que es posible la confusión con amanitas blancas mortales. Conservar los restos de hongos; en caso de afectación de órganos, llamar a emergencias 144.',NULL,NULL,false),
('amanita_echinocephala','fr','Amanite robuste, blanchâtre, avec des verrues du voile remarquablement pyramidales, pointues et dressées, blanchâtres à grises sur le chapeau (aspect hérissé). Pied à bulbe radicant, enfoncé profondément dans le sol, marginé, et à anneau fugace. Lames et chair souvent à reflet verdâtre. Thermophile, sur sol calcaire.','Troubles gastro-intestinaux (nausées) dans les 0–12 h ; à doses élevées, troubles de la fonction hépatique et rénale après 24–36 h. La consommation est déconseillée. Risque élevé de confusion avec les amanites blanches mortelles (A. virosa, A. phalloides var. alba).','En cas d''ingestion, appeler immédiatement Tox Info Suisse 145, car une confusion avec des amanites blanches mortelles est possible. Conserver les restes de champignons ; en cas d''atteinte d''organe, appeler les urgences 144.',NULL,NULL,false),
('amanita_echinocephala','it','Amanita robusta, biancastra, con verruche del velo notevolmente piramidali, appuntite e sporgenti, da biancastre a grigie sul cappello (aspetto irto). Gambo con bulbo radicante, profondamente infisso nel terreno, marginato, e anello fugace. Lamelle e carne spesso con riflesso verdastro. Termofila, su terreno calcareo.','Disturbi gastrointestinali (nausea) entro 0–12 h; a dosi elevate, disturbi della funzione epatica e renale dopo 24–36 h. Il consumo è sconsigliato. Elevato rischio di confusione con le amanite bianche mortali (A. virosa, A. phalloides var. alba).','In caso di ingestione, chiamare immediatamente Tox Info Suisse 145, poiché è possibile la confusione con amanite bianche mortali. Conservare i resti dei funghi; in caso di coinvolgimento d''organo, chiamare il numero d''emergenza 144.',NULL,NULL,false),
('amanita_franchetii','en','Grey-brown to olive-brown cap with conspicuous yellowish to sulphur-yellow, granular veil flecks. Stem with a yellowish, flocculose, ephemeral ring and a yellowish-girdled, marginate bulb. Gill edges and underside of the ring often yellowish. Thermophilic, on calcareous soil.','Gastrointestinal symptoms with nausea, vomiting and diarrhoea after ingestion. Listed in the literature as toxic/inedible; consumption is strongly discouraged.','If ingested and symptoms occur, contact Tox Info Suisse 145. Keep mushroom remains.',NULL,NULL,false),
('amanita_franchetii','es','Sombrero de gris-pardo a pardo-oliváceo con escamas del velo granulosas, de amarillentas a amarillo azufre, bien visibles. Pie con anillo flocoso amarillento y fugaz y bulbo marginado ceñido de amarillento. Filo de las láminas y cara inferior del anillo a menudo amarillentos. Termófilo, sobre suelo calcáreo.','Trastornos gastrointestinales con náuseas, vómitos y diarrea tras la ingestión. En la literatura se considera tóxico/no comestible; se desaconseja firmemente su consumo.','En caso de ingestión y molestias, contactar con Tox Info Suisse 145. Conservar los restos de hongos.',NULL,NULL,false),
('amanita_franchetii','fr','Chapeau gris-brun à brun olivâtre avec des flocons de voile granuleux, jaunâtres à jaune soufre, bien visibles. Pied à anneau floconneux jaunâtre et fugace, et bulbe marginé ceinturé de jaunâtre. Arête des lames et face inférieure de l''anneau souvent jaunâtres. Thermophile, sur sol calcaire.','Troubles gastro-intestinaux avec nausées, vomissements et diarrhée après ingestion. Considéré dans la littérature comme toxique/non comestible ; la consommation est fortement déconseillée.','En cas d''ingestion et de troubles, contacter Tox Info Suisse 145. Conserver les restes de champignons.',NULL,NULL,false),
('amanita_franchetii','it','Cappello da grigio-bruno a bruno-olivastro con fioccosità del velo granulosa, da giallastra a giallo zolfo, ben evidente. Gambo con anello fioccoso giallastro e fugace e bulbo marginato cinto di giallastro. Filo delle lamelle e faccia inferiore dell''anello spesso giallastri. Termofilo, su terreno calcareo.','Disturbi gastrointestinali con nausea, vomito e diarrea dopo l''ingestione. In letteratura è considerato tossico/non commestibile; il consumo è fortemente sconsigliato.','In caso di ingestione e disturbi, contattare Tox Info Suisse 145. Conservare i resti dei funghi.',NULL,NULL,false),
('amanita_ovoidea','en','Large, fleshy, pure-white to cream Amanita with a mealy, wipeable veil coating on the cap. Thick, soft, sac-like white volva and an ephemeral, mealy-flocculose, often dropping ring. CRITICAL: in the Mediterranean region barely distinguishable from the nephrotoxic Amanita proxima (orange-brownish volva, persistent ring) — confusion is frequent and dangerous.','Documented cases of acute kidney failure after ingestion (latency ~12 h: nausea, vomiting, anuria, later dialysis-dependent renal insufficiency). Edibility is doubtful/contested; expert mycologists strongly advise against consumption, additionally because of the barely separable confusion with the toxic A. proxima. Therefore classified as toxic, NOT as an edible mushroom.','If ingested, call Tox Info Suisse 145 IMMEDIATELY (suspected nephrotoxic Amanita syndrome). Secure mushroom remains/vomit. In case of kidney symptoms (reduced/absent urination), go to the emergency department/144 at once — haemodialysis may be necessary. Monitor kidney values.',NULL,NULL,false),
('amanita_ovoidea','es','Gran amanita carnosa, de blanco puro a crema, con un recubrimiento del velo harinoso y eliminable sobre el sombrero. Volva blanca gruesa, blanda, en forma de saco, y anillo fugaz, harinoso-flocoso, a menudo caedizo. CRÍTICO: en la región mediterránea, apenas distinguible de la Amanita proxima nefrotóxica (volva anaranjado-parduzca, anillo persistente) — la confusión es frecuente y peligrosa.','Casos documentados de insuficiencia renal aguda tras la ingestión (latencia ~12 h: náuseas, vómitos, anuria, después insuficiencia renal que requiere diálisis). La comestibilidad es dudosa/controvertida; los micólogos expertos desaconsejan firmemente el consumo, además por la confusión apenas evitable con la A. proxima tóxica. Por ello se clasifica como tóxica, NO como comestible.','En caso de ingestión, llamar INMEDIATAMENTE a Tox Info Suisse 145 (sospecha de síndrome amanítico nefrotóxico). Asegurar los restos de hongos/vómito. En caso de síntomas renales (micción reducida/ausente), acudir de inmediato a urgencias/144 — puede ser necesaria la hemodiálisis. Vigilar los valores renales.',NULL,NULL,false),
('amanita_ovoidea','fr','Grande amanite charnue, d''un blanc pur à crème, avec un revêtement du voile farineux et essuyable sur le chapeau. Volve blanche épaisse, molle, en forme de sac, et anneau fugace, farineux-floconneux, souvent retombant. CRITIQUE : dans la région méditerranéenne, à peine distinguable de l''Amanita proxima néphrotoxique (volve orange-brunâtre, anneau persistant) — la confusion est fréquente et dangereuse.','Cas documentés d''insuffisance rénale aiguë après ingestion (latence ~12 h : nausées, vomissements, anurie, puis insuffisance rénale nécessitant une dialyse). La comestibilité est douteuse/controversée ; les mycologues experts déconseillent vivement la consommation, d''autant plus à cause de la confusion à peine évitable avec l''A. proxima toxique. Classé donc comme toxique, PAS comme comestible.','En cas d''ingestion, appeler IMMÉDIATEMENT Tox Info Suisse 145 (suspicion de syndrome amanitique néphrotoxique). Conserver les restes de champignons/vomissures. En cas de symptômes rénaux (miction réduite/absente), se rendre immédiatement aux urgences/144 — une hémodialyse peut être nécessaire. Surveiller la fonction rénale.',NULL,NULL,false),
('amanita_ovoidea','it','Grande amanita carnosa, da bianco puro a crema, con un rivestimento del velo farinoso e asportabile sul cappello. Volva bianca spessa, molle, a forma di sacco, e anello fugace, farinoso-fioccoso, spesso cadente. CRITICO: nell''area mediterranea, a malapena distinguibile dall''Amanita proxima nefrotossica (volva arancio-brunastra, anello persistente) — la confusione è frequente e pericolosa.','Casi documentati di insufficienza renale acuta dopo l''ingestione (latenza ~12 h: nausea, vomito, anuria, poi insufficienza renale che richiede dialisi). La commestibilità è dubbia/controversa; i micologi esperti sconsigliano vivamente il consumo, anche a causa della confusione a malapena evitabile con l''A. proxima tossica. Pertanto classificata come tossica, NON come commestibile.','In caso di ingestione, chiamare SUBITO Tox Info Suisse 145 (sospetto di sindrome amanitica nefrotossica). Conservare i resti dei funghi/del vomito. In caso di sintomi renali (minzione ridotta/assente), recarsi immediatamente al pronto soccorso/144 — può essere necessaria l''emodialisi. Monitorare la funzione renale.',NULL,NULL,false),
('amanita_porphyria','en','Grey-brown to purple-brown cap with grey, appressed veil flecks. Characteristic is the distinctly marginate, bulbous stem base (margo) and the grey-brown washed, often snake-patterned ring. Strong potato/radish odour. Spore print white, gills free.','Gastrointestinal symptoms (nausea, vomiting, diarrhoea); bufotenine can affect heart rate and blood pressure. The gastrointestinal toxins are heat-stable and are not destroyed by cooking.','If ingested and symptoms occur, call Tox Info Suisse 145 immediately. Keep mushroom remains/vomit for identification. In case of circulatory problems, call emergency services 144.',NULL,NULL,false),
('amanita_porphyria','es','Sombrero de gris-pardo a pardo-purpúreo con escamas del velo grises y aplicadas. Característica es la base del pie bulbosa y claramente marginada (margo) y el anillo a menudo jaspeado (aserpentado), lavado de gris-pardo. Olor fuerte a patata/rábano. Esporada blanca, láminas libres.','Trastornos gastrointestinales (náuseas, vómitos, diarrea); la bufotenina puede afectar la frecuencia cardíaca y la presión arterial. Las toxinas gastrointestinales son termoestables y no se destruyen con la cocción.','En caso de ingestión y síntomas, llamar inmediatamente a Tox Info Suisse 145. Conservar los restos de hongos/vómito para la identificación. En caso de trastornos circulatorios, llamar a emergencias 144.',NULL,NULL,false),
('amanita_porphyria','fr','Chapeau gris-brun à brun pourpré avec des flocons de voile gris appliqués. Caractéristique : la base du pied bulbeuse nettement marginée (margo) et l''anneau souvent moucheté (chiné), lavé de gris-brun. Odeur forte de pomme de terre/radis. Sporée blanche, lames libres.','Troubles gastro-intestinaux (nausées, vomissements, diarrhée) ; la bufoténine peut influencer la fréquence cardiaque et la tension artérielle. Les toxines gastro-intestinales sont thermostables et ne sont pas détruites par la cuisson.','En cas d''ingestion et de symptômes, appeler immédiatement Tox Info Suisse 145. Conserver les restes de champignons/vomissures pour l''identification. En cas de troubles circulatoires, appeler les urgences 144.',NULL,NULL,false),
('amanita_porphyria','it','Cappello da grigio-bruno a bruno-purpureo con fioccosità del velo grigia e appressata. Caratteristica è la base del gambo bulbosa nettamente marginata (margo) e l''anello spesso screziato (a serpe), velato di grigio-bruno. Odore intenso di patata/rapanello. Sporata bianca, lamelle libere.','Disturbi gastrointestinali (nausea, vomito, diarrea); la bufotenina può influenzare la frequenza cardiaca e la pressione arteriosa. Le tossine gastrointestinali sono termostabili e non vengono distrutte dalla cottura.','In caso di ingestione e sintomi, chiamare immediatamente Tox Info Suisse 145. Conservare i resti dei funghi/del vomito per l''identificazione. In caso di disturbi circolatori, chiamare il numero d''emergenza 144.',NULL,NULL,false),
('amanita_proxima','en','Very similar to the European white egg amanita (A. ovoidea): large white Amanita. Distinguishing features: a thickened volva (sheath) distinctly coloured orange to ochre-brown, and a persistent, membranous ring on the stem. These features separate it from the A. ovoidea once thought edible — utmost caution with any white Mediterranean Amanita.','Nephrotoxic syndrome: after ~12 h a gastrointestinal phase (nausea, vomiting, diarrhoea), 1–4 days later acute (tubulointerstitial) renal failure, often temporarily dialysis-dependent, accompanied by a mild rise in transaminases (liver involvement). Toxin heat-stable — cooking does NOT protect.','If ingested, call Tox Info Suisse 145 IMMEDIATELY. Secure mushroom remains/vomit for identification. If urine output declines, go to the emergency department/144 at once — transient haemodialysis may be required; monitor kidney values over several days.',NULL,NULL,false),
('amanita_proxima','es','Muy similar a la amanita ovoidea (A. ovoidea): gran amanita blanca. Caracteres distintivos: volva (vaina) engrosada, claramente coloreada de naranja a pardo-ocre, y un anillo persistente y membranoso en el pie. Estos caracteres la separan de la A. ovoidea tenida por comestible — máxima precaución con cualquier amanita blanca mediterránea.','Síndrome nefrotóxico: tras ~12 h fase gastrointestinal (náuseas, vómitos, diarrea), 1–4 días después insuficiencia renal aguda (tubulointersticial), que a menudo requiere diálisis temporal, acompañada de una ligera elevación de las transaminasas (afectación hepática). Toxina termoestable — la cocción NO protege.','En caso de ingestión, llamar INMEDIATAMENTE a Tox Info Suisse 145. Conservar los restos de hongos/vómito para la identificación. Si disminuye la diuresis, acudir de inmediato a urgencias/144 — puede ser necesaria una hemodiálisis transitoria; controlar la función renal durante varios días.',NULL,NULL,false),
('amanita_proxima','fr','Très semblable à l''amanite ovoïde (A. ovoidea) : grande amanite blanche. Caractères distinctifs : volve (gaine) épaissie, nettement colorée d''orange à brun-ocre, ainsi qu''un anneau persistant et membraneux au pied. Ces caractères la séparent de l''A. ovoidea réputée comestible — la plus grande prudence s''impose pour toute amanite blanche méditerranéenne.','Syndrome néphrotoxique : après ~12 h, phase gastro-intestinale (nausées, vomissements, diarrhée), 1–4 jours plus tard insuffisance rénale aiguë (tubulo-interstitielle), nécessitant souvent une dialyse temporaire, accompagnée d''une légère élévation des transaminases (atteinte hépatique). Toxine thermostable — la cuisson ne protège PAS.','En cas d''ingestion, appeler IMMÉDIATEMENT Tox Info Suisse 145. Conserver les restes de champignons/vomissures pour l''identification. En cas de diminution de la diurèse, se rendre immédiatement aux urgences/144 — une hémodialyse transitoire peut être nécessaire ; contrôler la fonction rénale pendant plusieurs jours.',NULL,NULL,false),
('amanita_proxima','it','Molto simile all''amanita ovoidea (A. ovoidea): grande amanita bianca. Caratteri distintivi: volva (guaina) ispessita, nettamente colorata da arancio a bruno-ocra, e un anello persistente e membranoso sul gambo. Questi caratteri la separano dall''A. ovoidea ritenuta commestibile — massima prudenza con ogni amanita bianca mediterranea.','Sindrome nefrotossica: dopo ~12 h fase gastrointestinale (nausea, vomito, diarrea), 1–4 giorni dopo insufficienza renale acuta (tubulo-interstiziale), spesso che richiede dialisi temporanea, accompagnata da lieve aumento delle transaminasi (coinvolgimento epatico). Tossina termostabile — la cottura NON protegge.','In caso di ingestione, chiamare SUBITO Tox Info Suisse 145. Conservare i resti dei funghi/del vomito per l''identificazione. In caso di diminuzione della diuresi, recarsi immediatamente al pronto soccorso/144 — può essere necessaria un''emodialisi transitoria; controllare la funzione renale per diversi giorni.',NULL,NULL,false),
('amanita_submembranacea','en','Ringless grisette with an olive-grey to grey-brown cap, distinctly striate at the margin, often with grey veil remnants. Notable is the large, membranous, grey-coloured (grey-spotted) volva at the stem base. Stem grey, snake-patterned, ringless. Acidic soils in the mountains.','Toxic raw: heat-labile haemolysins lead to gastrointestinal symptoms and haemolysis when eaten raw/insufficiently cooked. Destroyed by sufficient heating, then edible.',NULL,'Eat only well cooked (at least 15–20 min), never raw. Because of the risk of confusion with deadly Amanita species (death caps), only by experienced collectors; dig up the volva completely and check it.',NULL,false),
('amanita_submembranacea','es','Amanita sin anillo (galamperna) con sombrero de gris-oliva a gris-pardo, claramente estriado en el margen, a menudo con restos de velo grises. Destaca la gran volva membranosa, de color gris (manchada de gris) en la base del pie. Pie gris jaspeado, sin anillo. Suelos ácidos en la montaña.','Tóxico en crudo: hemolisinas termolábiles provocan, si se consume crudo/poco cocinado, trastornos gastrointestinales y hemólisis. Se destruyen con un calentamiento suficiente, entonces es comestible.',NULL,'Consumir solo bien cocinado (al menos 15–20 min), nunca crudo. Por el riesgo de confusión con amanitas mortales (amanitas bulbosas), solo por recolectores experimentados; desenterrar completamente la volva y controlarla.',NULL,false),
('amanita_submembranacea','fr','Amanite sans anneau (golmotte) à chapeau gris-olive à gris-brun, nettement strié au bord, souvent avec des restes de voile gris. Remarquable est la grande volve membraneuse, de couleur grise (tachetée de gris) à la base du pied. Pied gris chiné, sans anneau. Sols acides en montagne.','Toxique cru : des hémolysines thermolabiles entraînent, en cas de consommation crue/insuffisamment cuite, des troubles gastro-intestinaux et une hémolyse. Détruites par une cuisson suffisante, alors comestible.',NULL,'À consommer uniquement bien cuit (au moins 15–20 min), jamais cru. En raison du risque de confusion avec des amanites mortelles (amanites bulbeuses), uniquement par des cueilleurs expérimentés ; déterrer entièrement la volve et la contrôler.',NULL,false),
('amanita_submembranacea','it','Amanita senza anello (bubbola) con cappello da grigio-oliva a grigio-bruno, nettamente striato al margine, spesso con resti di velo grigi. Notevole è la grande volva membranosa, di colore grigio (macchiata di grigio) alla base del gambo. Gambo grigio screziato, senza anello. Terreni acidi in montagna.','Tossico da crudo: emolisine termolabili causano, in caso di consumo crudo/insufficientemente cotto, disturbi gastrointestinali ed emolisi. Distrutte da una cottura sufficiente, allora commestibile.',NULL,'Da consumare solo ben cotto (almeno 15–20 min), mai crudo. A causa del rischio di confusione con amanite mortali (amanite bulbose), solo da raccoglitori esperti; dissotterrare completamente la volva e controllarla.',NULL,false),
('ampulloclitocybe_clavipes','en','Grey-brown to olivaceous, flatly funnel-shaped cap. Conspicuously club-thickened stem base (giving the name). Gills whitish to cream-yellow, far decurrent. TOXIC in combination with alcohol: triggers a coprine/acetaldehyde syndrome (alcohol intolerance). Eat only without alcohol — and even then not recommended.','In combination with alcohol (up to ~3-4 days after eating): sensation of heat, facial flushing, nausea, weakness, palpitations, blood pressure fluctuations. Onset 15 min to 2 h after alcohol consumption, lasting several hours.','Do not consume any alcohol. If symptoms occur, call Tox Info Suisse 145, rest, no further alcohol for several days. Keep mushroom remains.',NULL,NULL,false),
('ampulloclitocybe_clavipes','es','Sombrero de gris-pardo a oliváceo, plano-infundibuliforme. Base del pie notablemente engrosada en maza (de ahí el nombre). Láminas de blanquecinas a amarillo-crema, largamente decurrentes. TÓXICO en combinación con alcohol: desencadena un síndrome coprínico/acetaldehídico (intolerancia al alcohol). Consumir solo sin alcohol — y aun así no recomendado.','En combinación con alcohol (hasta ~3-4 días después del consumo): sensación de calor, enrojecimiento facial (flush), náuseas, debilidad, palpitaciones, oscilaciones de la presión arterial. Inicio de 15 min a 2 h tras el consumo de alcohol, duración de varias horas.','No consumir alcohol. En caso de síntomas, llamar a Tox Info Suisse 145, reposo, nada más de alcohol durante varios días. Conservar los restos de hongos.',NULL,NULL,false),
('ampulloclitocybe_clavipes','fr','Chapeau gris-brun à olivâtre, plan-infundibuliforme. Base du pied remarquablement épaissie en massue (d''où le nom). Lames blanchâtres à crème-jaune, longuement décurrentes. TOXIQUE en association avec l''alcool : provoque un syndrome coprinien/acétaldéhyde (intolérance à l''alcool). À consommer uniquement sans alcool — et même alors non recommandé.','En association avec l''alcool (jusqu''à ~3-4 jours après la consommation) : sensation de chaleur, rougeur du visage (flush), nausées, faiblesse, palpitations, variations de la tension artérielle. Début 15 min à 2 h après la consommation d''alcool, durée de plusieurs heures.','Ne consommer aucun alcool. En cas de symptômes, appeler Tox Info Suisse 145, se reposer, pas d''autre alcool pendant plusieurs jours. Conserver les restes de champignons.',NULL,NULL,false),
('ampulloclitocybe_clavipes','it','Cappello da grigio-bruno a olivastro, piano-infundibuliforme. Base del gambo notevolmente ingrossata a clava (da cui il nome). Lamelle da biancastre a giallo-crema, lungamente decorrenti. TOSSICO in associazione con l''alcol: provoca una sindrome coprinica/acetaldeidica (intolleranza all''alcol). Da consumare solo senza alcol — e anche allora non raccomandato.','In associazione con l''alcol (fino a ~3-4 giorni dopo il consumo): sensazione di calore, arrossamento del viso (flush), nausea, debolezza, palpitazioni, oscillazioni della pressione arteriosa. Inizio da 15 min a 2 h dopo il consumo di alcol, durata di diverse ore.','Non consumare alcol. In caso di sintomi, chiamare Tox Info Suisse 145, riposo, nessun ulteriore alcol per diversi giorni. Conservare i resti dei funghi.',NULL,NULL,false),
('apioperdon_pyriforme','en','The only puffball that grows in clusters on wood (stumps, buried wood) — the most important distinguishing feature from the common stump puffball''''s relative, the pear-shaped puffball. Pear-shaped fruiting body with a globular upper part and a narrow base, attached to the substrate by white rhizomorph strands. Edible only as long as the gleba is, in cross-section, PURE WHITE and firm; if it discolours yellow/brown, inedible. Cut EVERY globular find lengthwise — an Amanita bulb (death-cap egg) shows embryonic gills/cap primordium in section and is deadly.',NULL,NULL,'Only young specimens, pure white inside. Cut lengthwise to check (white = ok). Fried in slices; little flavour of its own. Discard mature (yellow/brown) specimens.',NULL,false),
('apioperdon_pyriforme','es','El único bejín que crece en grupos sobre madera (tocones, madera enterrada) — principal carácter distintivo respecto al bejín en forma de pera común. Cuerpo fructífero piriforme con parte superior globosa y base estrecha, fijado al sustrato por cordones de rizomorfos blancos. Comestible solo mientras la gleba esté, en corte, de un BLANCO PURO y firme; en caso de coloración amarilla/parda, no comestible. Cortar LONGITUDINALMENTE todo hallazgo globoso — un bulbo de amanita (huevo de amanita mortal) muestra en corte láminas/esbozo de sombrero embrionarios y es mortal.',NULL,NULL,'Solo ejemplares jóvenes, de un blanco puro en su interior. Cortar longitudinalmente para el control (blanco = ok). Frito en rodajas; sabor propio escaso. Desechar los ejemplares maduros (amarillos/pardos).',NULL,false),
('apioperdon_pyriforme','fr','Seule vesse-de-loup poussant en touffes sur le bois (souches, bois enterré) — principal caractère distinctif d''avec la vesse-de-loup en forme de poire commune. Fructification piriforme à partie supérieure globuleuse et base étroite, fixée au substrat par des cordons de rhizomorphes blancs. Comestible uniquement tant que la gléba est, en coupe, d''un BLANC PUR et ferme ; en cas de coloration jaune/brune, non comestible. Couper LONGITUDINALEMENT toute trouvaille globuleuse — un bulbe d''amanite (œuf d''amanite mortelle) montre en coupe des lames/ébauche de chapeau embryonnaires et est mortel.',NULL,NULL,'Uniquement les jeunes exemplaires d''un blanc pur à l''intérieur. Couper longitudinalement pour contrôler (blanc = ok). Frit en tranches ; saveur propre faible. Jeter les exemplaires mûrs (jaunes/bruns).',NULL,false),
('apioperdon_pyriforme','it','Unica vescia che cresce a ciuffi sul legno (ceppi, legno interrato) — principale carattere distintivo dalla vescia a forma di pera comune. Corpo fruttifero piriforme con parte superiore globosa e base stretta, fissato al substrato da cordoni di rizomorfe bianche. Commestibile solo finché la gleba è, in sezione, di un BIANCO PURO e soda; in caso di colorazione gialla/bruna, non commestibile. Tagliare LONGITUDINALMENTE ogni ritrovamento globoso — un bulbo di amanita (uovo di amanita mortale) mostra in sezione lamelle/abbozzo di cappello embrionali ed è mortale.',NULL,NULL,'Solo esemplari giovani, internamente di un bianco puro. Tagliare longitudinalmente per il controllo (bianco = ok). Fritto a fette; sapore proprio modesto. Scartare gli esemplari maturi (gialli/bruni).',NULL,false),
('artomyces_pyxidatus','en','Coral-like, branched fruiting body with branch tips characteristically ending in cup- or crown-shaped (pyxidate) form, from whose rim new branches arise again. Always grows on rotting hardwood (never on soil). Cream-white, ochraceous/browning with age. This substrate attachment and the cup shape rule out confusion with soil-dwelling toxic Ramaria.',NULL,NULL,NULL,NULL,false),
('artomyces_pyxidatus','es','Cuerpo fructífero ramificado en forma de coral con ápices de las ramas que terminan característicamente en forma de copa o corona (pixidados), de cuyo borde surgen de nuevo nuevas ramas. Crece siempre sobre madera de frondosa en descomposición (nunca sobre la tierra). Blanco crema, ocráceo/pardeante con la edad. Esta vinculación al sustrato y la forma de copa excluyen la confusión con las Ramaria tóxicas terrícolas.',NULL,NULL,NULL,NULL,false),
('artomyces_pyxidatus','fr','Fructification ramifiée en forme de corail avec des pointes de rameaux caractéristiquement terminées en coupe ou en couronne (pyxidées), du bord desquelles naissent à nouveau de nouveaux rameaux. Pousse toujours sur bois feuillu pourri (jamais sur la terre). Blanc crème, ocracé/brunissant avec l''âge. Cette liaison au substrat et la forme en coupe excluent toute confusion avec les Ramaria toxiques terricoles.',NULL,NULL,NULL,NULL,false),
('artomyces_pyxidatus','it','Corpo fruttifero ramificato a forma di corallo con apici dei rami caratteristicamente terminanti a coppa o a corona (pissidati), dal cui bordo si originano nuovamente nuovi rami. Cresce sempre su legno di latifoglia marcescente (mai sulla terra). Bianco crema, ocraceo/imbrunente con l''età. Questo legame al substrato e la forma a coppa escludono la confusione con le Ramaria tossiche terricole.',NULL,NULL,NULL,NULL,false),
('auriscalpium_vulgare','en','Very small (cap 1-2 cm), kidney-shaped, hairy, dark-brown cap on a long dark stem attached laterally/eccentrically — the shape resembles an ear-pick. Typically grows directly on buried or fallen pine/spruce cones (saprobic, no mycorrhiza). Underside with small spines. Unmistakable by its cone substrate and shape. Inedible due to its tiny size and tough, leathery texture; not poisonous.',NULL,NULL,NULL,NULL,false),
('auriscalpium_vulgare','es','Muy pequeño (sombrero 1-2 cm), sombrero reniforme, peludo, pardo oscuro, sobre un pie largo y oscuro insertado lateral/excéntricamente — la forma recuerda a un limpiaoídos. Crece típicamente directamente sobre piñas de pino/abeto enterradas o caídas (saprobio, sin micorriza). Cara inferior con pequeñas espinas. Inconfundible por su sustrato (piña) y su forma. No comestible por su tamaño minúsculo y su consistencia coriácea; no tóxico.',NULL,NULL,NULL,NULL,false),
('auriscalpium_vulgare','fr','Très petit (chapeau 1-2 cm), chapeau réniforme, velu, brun foncé, sur un long pied sombre inséré latéralement/excentriquement — la forme rappelle un cure-oreille. Pousse typiquement directement sur des cônes de pin/épicéa enterrés ou couchés (saprobe, pas de mycorhize). Face inférieure garnie de petits aiguillons. Inconfondable par son substrat (cône) et sa forme. Immangeable en raison de sa taille minuscule et de sa consistance coriace; non toxique.',NULL,NULL,NULL,NULL,false),
('auriscalpium_vulgare','it','Molto piccolo (cappello 1-2 cm), cappello reniforme, peloso, bruno scuro, su un lungo gambo scuro inserito lateralmente/eccentricamente — la forma ricorda un cucchiaino da orecchie. Cresce tipicamente direttamente su pigne di pino/abete rosso interrate o cadute (saprofita, niente micorriza). Faccia inferiore con piccoli aculei. Inconfondibile per il substrato (pigna) e la forma. Immangiabile per le dimensioni minuscole e la consistenza coriacea; non tossico.',NULL,NULL,NULL,NULL,false),
('bjerkandera_adusta','en','Thin, resupinate to semi-bracket-shaped fruitbody on dead hardwood. Diagnostic: the smoke-grey to blackish-grey pore layer (''as if scorched''), often with a dark line between the whitish flesh and the grey tube layer. Tough-leathery, inedible.',NULL,NULL,NULL,NULL,false),
('bjerkandera_adusta','es','Cuerpo fructífero delgado, de resupinado a semiconsolar sobre madera muerta de frondosa. Diagnóstico: la capa de poros de gris humo a gris negruzco («como chamuscada»), a menudo con una línea oscura entre la carne blanquecina y la capa gris de los tubos. Coriáceo, no comestible.',NULL,NULL,NULL,NULL,false),
('bjerkandera_adusta','fr','Carpophore mince, résupiné à semi-consolé sur bois feuillu mort. Diagnostique: la couche de pores gris fumée à gris noirâtre («comme roussie»), souvent avec une ligne sombre entre la trame blanchâtre et la couche grise des tubes. Coriace, immangeable.',NULL,NULL,NULL,NULL,false),
('bjerkandera_adusta','it','Corpo fruttifero sottile, da resupinato a semi-mensoliforme su legno di latifoglia morto. Diagnostico: lo strato dei pori da grigio fumo a grigio nerastro («come bruciacchiato»), spesso con una linea scura tra la trama biancastra e lo strato grigio dei tubuli. Coriaceo, immangiabile.',NULL,NULL,NULL,NULL,false),
('bovista_plumbea','en','Small (1–3 cm) globular meadow puffball, pure white when young, in age with a lead-grey, paper-smooth outer skin that peels off as a whole and is blown away by the wind. Anchored by only a single mycelial cord. Edible only while the gleba is PURE WHITE inside. Caution: young Amanita ''eggs'', including the deadly death cap, also grow at meadow edges and look globular and white — cut EVERY globular find LENGTHWISE; if an inner gill/cap outline is present = deadly Amanita, discard immediately.',NULL,NULL,'Only young mushrooms that are pure white inside. Cut lengthwise (to rule out an Amanita egg). Marshmallow-like texture, low culinary value; fried. Discard specimens that have turned lead-grey (mature).',NULL,false),
('bovista_plumbea','es','Pequeño bejín de pradera, globoso (1–3 cm), blanco puro de joven, en la madurez con una piel externa gris plomo, lisa como papel, que se desprende entera y se la lleva el viento. Se ancla con un único cordón micelial. Comestible solo mientras la gleba sea BLANCO PURO por dentro. Atención: los huevos jóvenes de Amanita, incluida la mortal oronja verde, también crecen en los bordes de praderas y parecen globosos y blancos — cortar A LO LARGO todo ejemplar globoso; si hay un esbozo interno de láminas/sombrero = Amanita mortal, desechar de inmediato.',NULL,NULL,'Solo los ejemplares jóvenes, blancos puros por dentro. Cortar a lo largo (descarte del huevo de Amanita). Consistencia tipo malvavisco, escaso interés culinario; salteado. Desechar los ejemplares virados a gris plomo (maduros).',NULL,false),
('bovista_plumbea','fr','Petit champignon des prairies, globuleux (1–3 cm), jeune d''un blanc pur, à maturité avec une enveloppe externe gris plomb, lisse comme du papier, qui se détache d''un seul tenant et est emportée par le vent. S''enracine par un seul cordon mycélien. Comestible uniquement tant que la gléba est BLANC PUR à l''intérieur. Attention: les jeunes œufs d''amanite (Amanita), dont l''amanite phalloïde mortelle, poussent aussi en bordure de prairies et paraissent globuleux et blancs — couper EN LONG tout exemplaire globuleux; si présence d''une ébauche de lames/chapeau à l''intérieur = Amanita mortelle, à jeter immédiatement.',NULL,NULL,'Uniquement les jeunes champignons, blancs purs à l''intérieur. Couper en long (exclusion de l''œuf d''amanite). Consistance type guimauve, intérêt culinaire faible; poêlé. Jeter les exemplaires virés au gris plomb (mûrs).',NULL,false),
('bovista_plumbea','it','Piccolo fungo dei prati, globoso (1–3 cm), da giovane bianco puro, a maturità con cuticola esterna grigio piombo, liscia come carta, che si stacca tutta intera e viene portata via dal vento. Si àncora con un solo cordone miceliare. Commestibile solo finché la gleba è BIANCO PURO all''interno. Attenzione: le giovani uova di Amanita, inclusa la mortale Amanita falloide, crescono anch''esse ai bordi dei prati e appaiono globose e bianche — tagliare PER IL LUNGO ogni esemplare globoso; se all''interno c''è un abbozzo di lamelle/cappello = Amanita mortale, scartare subito.',NULL,NULL,'Solo i funghi giovani, bianchi puri all''interno. Tagliare per il lungo (esclusione dell''uovo di Amanita). Consistenza tipo marshmallow, scarso interesse culinario; in padella. Scartare gli esemplari virati al grigio piombo (maturi).',NULL,false),
('calocera_viscosa','en','Bright golden- to orange-yellow, forked-branched, gelatinous-tough and sticky fruitbody up to ~10 cm, rooting in the substrate (conifer wood). Tough, rubbery texture, drying horn-like. Never grows on soil, always on rotten conifer wood. Confusion with Ramaria corals is ruled out by the substrate attachment and gelatinous texture.',NULL,NULL,NULL,NULL,false),
('calocera_viscosa','es','Cuerpo fructífero de un amarillo dorado a anaranjado brillante, ramificado en horquilla, gelatinoso-coriáceo y pegajoso, hasta ~10 cm, enraizado en el sustrato (madera de conífera). Consistencia coriácea, gomosa, se seca córnea. Nunca crece sobre el suelo, siempre sobre madera de conífera podrida. Confusión con las clavarias Ramaria descartada por la unión al sustrato y la consistencia gelatinosa.',NULL,NULL,NULL,NULL,false),
('calocera_viscosa','fr','Carpophore d''un jaune doré à orangé éclatant, ramifié en fourche, gélatineux-coriace et collant, jusqu''à ~10 cm, s''enracinant dans le substrat (bois de conifère). Consistance coriace, caoutchouteuse, sèche en corne. Ne pousse jamais sur la terre, toujours sur bois de conifère pourri. Confusion avec les clavaires Ramaria exclue par le lien au substrat et la consistance gélatineuse.',NULL,NULL,NULL,NULL,false),
('calocera_viscosa','it','Corpo fruttifero di un giallo dorato-arancio brillante, ramificato a forca, gelatinoso-coriaceo e appiccicoso, fino a ~10 cm, radicante nel substrato (legno di conifera). Consistenza coriacea, gommosa, secca cornea. Non cresce mai sul terreno, sempre su legno di conifera marcescente. Confusione con i coralli Ramaria esclusa dal legame col substrato e dalla consistenza gelatinosa.',NULL,NULL,NULL,NULL,false),
('calvatia_utriformis','en','Large (up to ~15 cm) sac- to top-shaped meadow puffball; outer skin white when young, soon grey, cracking into areolate patches with age (hence areolata). At maturity it opens by irregular tearing of the apex (no single ostiole). Edible only while the gleba is PURE WHITE and firm in cross-section; a carbolic/phenolic smell or yellow/brown discolouration = discard. Due to its size barely confusable with young Amanita eggs, but still cut every find open (white check).',NULL,NULL,'Only young specimens that are pure white inside; for large pieces peel off the outer skin, cut into thick slices and fry (schnitzel-style). Discard pieces that smell carbolic/phenolic or are discoloured.',NULL,false),
('calvatia_utriformis','es','Gran bejín de pradera (hasta ~15 cm), en forma de saco/peonza; piel externa blanca de joven, pronto gris, que se agrieta en placas areoladas con la edad (de ahí areolata). En la madurez se abre por desgarro irregular del ápice (sin ostiolo único). Comestible solo mientras la gleba sea BLANCO PURO y firme al corte; olor fenólico (a carbol) o viraje amarillo/pardo = desechar. Por su tamaño difícilmente confundible con huevos jóvenes de Amanita, pero aun así cortar cada ejemplar (control del blanco).',NULL,NULL,'Solo los ejemplares jóvenes, blancos puros por dentro; en piezas grandes pelar la piel externa, cortar en rodajas gruesas y freír (al estilo escalope). Desechar las piezas con olor fenólico o descoloridas.',NULL,false),
('calvatia_utriformis','fr','Grand champignon des prairies (jusqu''à ~15 cm), en forme de sac/toupie; enveloppe externe blanche jeune, bientôt grise, se déchirant en plaques aréolées avec l''âge (d''où areolata). À maturité, s''ouvre par déchirure irrégulière du sommet (pas d''ostiole unique). Comestible uniquement tant que la gléba est BLANC PUR et ferme à la coupe; odeur phénolée (carbol) ou virage jaune/brun = à jeter. Du fait de sa taille, peu confondable avec de jeunes œufs d''amanite, mais couper tout de même chaque exemplaire (contrôle du blanc).',NULL,NULL,'Uniquement les jeunes exemplaires, blancs purs à l''intérieur; pour les gros morceaux, peler l''enveloppe externe, couper en tranches épaisses et poêler (façon escalope). Jeter les morceaux à odeur phénolée ou décolorés.',NULL,false),
('calvatia_utriformis','it','Grande fungo dei prati (fino a ~15 cm), a forma di sacco/trottola; cuticola esterna bianca da giovane, presto grigia, che si lacera a placche areolate con l''età (da cui areolata). A maturità si apre per lacerazione irregolare dell''apice (nessun ostiolo singolo). Commestibile solo finché la gleba è BIANCO PURO e soda al taglio; odore fenolico (carbolico) o viraggio giallo/bruno = scartare. Per le dimensioni difficilmente confondibile con giovani uova di Amanita, tagliare comunque ogni esemplare (controllo del bianco).',NULL,NULL,'Solo gli esemplari giovani, bianchi puri all''interno; per i pezzi grandi sbucciare la cuticola esterna, tagliare a fette spesse e cuocere in padella (tipo cotoletta). Scartare i pezzi con odore fenolico o scoloriti.',NULL,false),
('cerioporus_squamosus','en','Large fan- to kidney-shaped cap (10–60 cm) with concentric, dark-brown, appressed scales on a pale background. Underside with large, whitish, angular pores up to 2.5 mm. Stem attached laterally or eccentrically, black at the base. Grows in clusters on hardwood wounds. Edible only when very young and soft; older fruitbodies become woody and tough-inedible.',NULL,NULL,'Use only very young, still-soft fruitbodies. Cut into thin strips, fry vigorously or braise; cook through well. Sort out older, tough material. Cucumber-mealy own flavour — season sparingly.',NULL,false),
('cerioporus_squamosus','es','Gran sombrero de flabeliforme a reniforme (10–60 cm) con escamas concéntricas, pardo oscuro, aplicadas, sobre fondo claro. Cara inferior con grandes poros blanquecinos, angulosos, hasta 2,5 mm. Pie insertado lateral o excéntricamente, negro en la base. Crece en grupos sobre heridas de madera de frondosa. Comestible solo muy joven y tierno; los cuerpos fructíferos viejos se lignifican y se vuelven coriáceos-no comestibles.',NULL,NULL,'Usar solo los cuerpos fructíferos muy jóvenes, aún tiernos. Cortar en tiras finas, dorar bien o estofar; cocer a fondo. Descartar el material viejo y coriáceo. Sabor propio a pepino y harina — sazonar con moderación.',NULL,false),
('cerioporus_squamosus','fr','Grand chapeau en éventail à réniforme (10–60 cm) à squames concentriques brun foncé, appliquées, sur fond clair. Face inférieure à grands pores blanchâtres, anguleux, jusqu''à 2,5 mm. Pied inséré latéralement ou excentriquement, noir à la base. Pousse en touffes sur les blessures de bois feuillu. Comestible seulement très jeune et tendre; les carpophores âgés se lignifient et deviennent coriaces-immangeables.',NULL,NULL,'Utiliser uniquement les carpophores tout jeunes, encore tendres. Couper en fines lanières, bien faire revenir ou braiser; bien cuire. Écarter le matériel âgé et coriace. Saveur propre rappelant le concombre et la farine — assaisonner avec parcimonie.',NULL,false),
('cerioporus_squamosus','it','Grande cappello da flabelliforme a reniforme (10–60 cm) con squame concentriche bruno scuro, appressate, su fondo chiaro. Faccia inferiore con grandi pori biancastri, angolosi, fino a 2,5 mm. Gambo inserito lateralmente o eccentricamente, nero alla base. Cresce in gruppi sulle ferite di legno di latifoglia. Commestibile solo molto giovane e tenero; i corpi fruttiferi maturi lignificano e diventano coriacei-immangiabili.',NULL,NULL,'Usare solo i corpi fruttiferi giovanissimi, ancora teneri. Tagliare a striscioline sottili, rosolare bene o brasare; cuocere a fondo. Scartare il materiale vecchio e coriaceo. Sapore proprio di cetriolo e farina — condire con parsimonia.',NULL,false),
('chalciporus_piperatus','en','Small bolete with a cinnamon- to copper-brown cap, strikingly rust-red to cinnamon-brown tubes and pores that run down the stem. Stem base chrome-yellow. Flesh yellowish, with a sharp peppery taste when cut (a reliable identification feature, spit out the taste test). Often in the company of the fly agaric.','Raw or in larger amounts, gastrointestinal upset is possible; effectively inedible due to its burning-sharp taste. Not actually poisonous.',NULL,'Inedible as a standalone edible mushroom (too sharp). At most dried and ground in very small amounts as a peppery seasoning-mushroom powder; avoid larger amounts due to gastrointestinal intolerance.',NULL,false),
('chalciporus_piperatus','es','Pequeño boleto con sombrero pardo canela a cobrizo, con tubos y poros de un rojo herrumbre a pardo canela llamativos, decurrentes sobre el pie. Base del pie amarillo cromo. Carne amarillenta, de sabor picante-ardiente al corte (rasgo de identificación seguro, escupir la cata). A menudo en compañía de la amanita matamoscas.','Crudo o en grandes cantidades, posibles molestias gastrointestinales; de hecho no comestible por su sabor ardiente y picante. No propiamente tóxico.',NULL,'No comestible como seta comestible por sí sola (demasiado picante). A lo sumo, seco y molido en cantidades muy pequeñas como polvo-condimento picante; evitar grandes cantidades por la intolerancia gastrointestinal.',NULL,false),
('chalciporus_piperatus','fr','Petit bolet à chapeau brun cannelle à cuivré, à tubes et pores d''un roux rouille à brun cannelle remarquables, décurrents sur le pied. Base du pied jaune chrome. Chair jaunâtre, à saveur poivrée brûlante à la coupe (caractère d''identification sûr, recracher la dégustation). Souvent en compagnie de l''amanite tue-mouches.','Cru ou en grande quantité, troubles gastro-intestinaux possibles; de fait immangeable du fait de sa saveur brûlante et piquante. Pas réellement toxique.',NULL,'Immangeable comme champignon comestible à part entière (trop piquant). Éventuellement séché et moulu en très petite quantité comme poudre-condiment poivrée; éviter les grandes quantités en raison de l''intolérance gastro-intestinale.',NULL,false),
('chalciporus_piperatus','it','Piccolo boleto con cappello bruno cannella-ramato, con tubuli e pori di un rosso ruggine-bruno cannella appariscenti, decorrenti sul gambo. Base del gambo giallo cromo. Carne giallastra, di sapore pepato-bruciante al taglio (carattere identificativo sicuro, sputare l''assaggio). Spesso in compagnia dell''ovolo malefico (Amanita muscaria).','Crudo o in grandi quantità, possibili disturbi gastrointestinali; di fatto immangiabile per il sapore bruciante e piccante. Non propriamente tossico.',NULL,'Immangiabile come fungo commestibile a sé (troppo piccante). Eventualmente essiccato e macinato in quantità minime come polvere-condimento pepata; evitare grandi quantità per l''intolleranza gastrointestinale.',NULL,false),
('clavariadelphus_truncatus','en','Unbranched, club-shaped fruitbodies up to ~15 cm tall and 2–8 cm wide with a characteristically flat, truncate top, often knobbly-wrinkled; outer surface yellow to orange-ochre, longitudinally wrinkled. Flesh white, firm-elastic, tough, sweetish. No poisonous lookalikes in this typical truncate club form.',NULL,NULL,'Young specimens edible, medium food value, the sweetish taste is unusual. CAUTION: in Switzerland rare to very rare and a Red List species – it should be spared and left in its habitat, not collected.',NULL,false),
('clavariadelphus_truncatus','es','Cuerpos fructíferos no ramificados, claviformes, hasta ~15 cm de altura y 2–8 cm de anchura, con la cara superior característicamente aplanada-truncada, a menudo abollada-rugosa; exterior de amarillo a ocre anaranjado, rugoso a lo largo. Carne blanca, firme-elástica, coriácea, dulzona. Sin sosias tóxicos en esta forma típica de maza truncada.',NULL,NULL,'Ejemplares jóvenes comestibles, valor culinario medio, el sabor dulzón es inusual. ATENCIÓN: en Suiza raro a muy raro y especie de la Lista Roja – debe protegerse y dejarse en su hábitat, no recolectarse.',NULL,false),
('clavariadelphus_truncatus','fr','Carpophores non ramifiés, en forme de massue, jusqu''à ~15 cm de hauteur et 2–8 cm de largeur, à face supérieure caractéristiquement aplatie-tronquée, souvent bosselée-ridée; extérieur jaune à ocre orangé, ridé en long. Chair blanche, ferme-élastique, coriace, douceâtre. Pas de sosie toxique dans cette forme typique de massue tronquée.',NULL,NULL,'Jeunes exemplaires comestibles, valeur culinaire moyenne, le goût douceâtre est inhabituel. ATTENTION: en Suisse, rare à très rare et espèce de la Liste rouge – à épargner et laisser dans son habitat, ne pas récolter.',NULL,false),
('clavariadelphus_truncatus','it','Corpi fruttiferi non ramificati, clavati, fino a ~15 cm di altezza e 2–8 cm di larghezza, con faccia superiore caratteristicamente appiattita-troncata, spesso bitorzoluta-rugosa; esterno da giallo a ocra arancio, rugoso per il lungo. Carne bianca, soda-elastica, coriacea, dolciastra. Nessun sosia tossico in questa tipica forma di clava troncata.',NULL,NULL,'Esemplari giovani commestibili, valore culinario medio, il gusto dolciastro è insolito. ATTENZIONE: in Svizzera raro o molto raro e specie della Lista Rossa – da risparmiare e lasciare nel suo habitat, non raccogliere.',NULL,false),
('clavulina_cinerea','en','Grey to ash-grey, bushy coral-like branched fruitbody up to ~10 cm, branch tips blunt to finely toothed. Spore print white (the key feature to distinguish it from poisonous, ochre-spored Ramaria). Microscopically barely separable from C. rugosa. Black spots indicate parasite infestation – then do not eat any more.','Itself non-toxic. BUT: risk of confusion with poisonous Ramaria species (especially R. formosa, R. flavescens) – if confused, gastrointestinal upset with stomach ache, vomiting, diarrhoea 0.5–3 h after eating.',NULL,'Use only young and only with reliable distinction (white spore print!) from poisonous Ramaria. Low food value, can turn bitter; cook through well.',NULL,false),
('clavulina_cinerea','es','Cuerpo fructífero de gris a gris ceniza, ramificado en forma de coral arbustivo, hasta ~10 cm, puntas de las ramas obtusas a finamente dentadas. Esporada blanca (rasgo clave para distinguirlo de las Ramaria tóxicas de esporas ocres). Microscópicamente apenas separable de C. rugosa. Las manchas negras indican infestación parasitaria – entonces no consumir más.','En sí no tóxico. PERO: riesgo de confusión con especies tóxicas de Ramaria (sobre todo R. formosa, R. flavescens) – en caso de confusión, molestias gastrointestinales con dolor de barriga, vómitos, diarrea 0,5–3 h tras la ingesta.',NULL,'Usar solo joven y solo con una distinción segura (¡esporada blanca!) de las Ramaria tóxicas. Escaso valor culinario, puede amargar; cocer a fondo.',NULL,false),
('clavulina_cinerea','fr','Carpophore gris à gris cendré, ramifié en buisson-corail, jusqu''à ~10 cm, pointes des rameaux obtuses à finement denticulées. Sporée blanche (caractère clé pour le distinguer des Ramaria toxiques à spores ocre). Microscopiquement quasi inséparable de C. rugosa. Des taches noires indiquent une attaque parasitaire – ne plus consommer alors.','Lui-même non toxique. MAIS: risque de confusion avec des Ramaria toxiques (surtout R. formosa, R. flavescens) – en cas de confusion, troubles gastro-intestinaux avec maux de ventre, vomissements, diarrhée 0,5–3 h après l''ingestion.',NULL,'N''utiliser que jeune et seulement si la distinction (sporée blanche!) d''avec les Ramaria toxiques est sûre. Faible valeur culinaire, peut devenir amer; bien cuire.',NULL,false),
('clavulina_cinerea','it','Corpo fruttifero da grigio a grigio cenere, ramificato a cespuglio-corallo, fino a ~10 cm, apici dei rami da ottusi a finemente dentellati. Sporata bianca (carattere chiave per distinguerlo dalle Ramaria tossiche a spore ocra). Microscopicamente quasi inseparabile da C. rugosa. Macchie nere indicano attacco parassitario – in tal caso non consumare più.','Di per sé non tossico. MA: rischio di confusione con Ramaria tossiche (soprattutto R. formosa, R. flavescens) – in caso di confusione, disturbi gastrointestinali con mal di pancia, vomito, diarrea 0,5–3 h dopo l''ingestione.',NULL,'Usare solo da giovane e solo con sicura distinzione (sporata bianca!) dalle Ramaria tossiche. Scarso valore culinario, può diventare amaro; cuocere a fondo.',NULL,false),
('clavulina_coralloides','en','Pure-white to cream-white, densely branched coral fruitbody with characteristically finely toothed, comb-/antler-like split branch tips. Up to ~8 cm tall. Spore print white (the most important distinguishing feature from poisonous Ramaria species, which have ochre-yellow spore print). When attacked by the parasite Helminthosphaeria, the fruitbody greys.','Itself non-toxic. BUT: risk of confusion with poisonous Ramaria species (R. formosa, R. flavescens, R. pallida) – if confused, gastrointestinal upset with stomach ache, vomiting, diarrhoea 0.5–3 h after eating.',NULL,'Edible only if the spore-print colour (white!) and branch tips are reliably distinguished from poisonous Ramaria. Cook young fruitbodies through well; low food value, at most as a mixed mushroom.',NULL,false),
('clavulina_coralloides','es','Cuerpo fructífero coralino de un blanco puro a blanco crema, densamente ramificado, con puntas de las ramas característicamente finamente dentadas, hendidas en peine/cuerna de ciervo. Hasta ~8 cm de altura. Esporada blanca (el rasgo de separación más importante respecto a las especies tóxicas de Ramaria, de esporada amarillo ocre). Cuando lo ataca el parásito Helminthosphaeria, el cuerpo fructífero agrisa.','En sí no tóxico. PERO: riesgo de confusión con especies tóxicas de Ramaria (R. formosa, R. flavescens, R. pallida) – en caso de confusión, molestias gastrointestinales con dolor de barriga, vómitos, diarrea 0,5–3 h tras la ingesta.',NULL,'Comestible solo si el color de la esporada (¡blanco!) y las puntas de las ramas se distinguen con seguridad de las Ramaria tóxicas. Cocer bien los cuerpos fructíferos jóvenes; escaso valor culinario, a lo sumo como seta de mezcla.',NULL,false),
('clavulina_coralloides','fr','Carpophore corallien d''un blanc pur à blanc crème, densément ramifié, à pointes des rameaux caractéristiquement finement denticulées, fendues en peigne/bois de cerf. Jusqu''à ~8 cm de haut. Sporée blanche (caractère de séparation le plus important d''avec les Ramaria toxiques, à sporée jaune ocre). En cas d''attaque par le parasite Helminthosphaeria, le carpophore grisonne.','Lui-même non toxique. MAIS: risque de confusion avec des Ramaria toxiques (R. formosa, R. flavescens, R. pallida) – en cas de confusion, troubles gastro-intestinaux avec maux de ventre, vomissements, diarrhée 0,5–3 h après l''ingestion.',NULL,'Comestible uniquement si la couleur de la sporée (blanche!) et les pointes des rameaux sont sûrement distinguées des Ramaria toxiques. Bien cuire les jeunes carpophores; faible valeur culinaire, tout au plus en mélange.',NULL,false),
('clavulina_coralloides','it','Corpo fruttifero corallino di un bianco puro-crema, densamente ramificato, con apici dei rami caratteristicamente finemente dentellati, fessi a pettine/corna di cervo. Fino a ~8 cm di altezza. Sporata bianca (il più importante carattere di separazione dalle Ramaria tossiche, a sporata giallo ocra). In caso di attacco del parassita Helminthosphaeria, il corpo fruttifero ingrigisce.','Di per sé non tossico. MA: rischio di confusione con Ramaria tossiche (R. formosa, R. flavescens, R. pallida) – in caso di confusione, disturbi gastrointestinali con mal di pancia, vomito, diarrea 0,5–3 h dopo l''ingestione.',NULL,'Commestibile solo se il colore della sporata (bianco!) e gli apici dei rami sono distinti con sicurezza dalle Ramaria tossiche. Cuocere bene i corpi fruttiferi giovani; scarso valore culinario, al massimo come fungo da misto.',NULL,false),
('clavulina_rugosa','en','Whitish to pale grey clavate fruiting body, often little or not at all branched, longitudinally wrinkled-furrowed, with blunt tips (not sharply toothed like C. coralloides). Spore print white. Microscopically not reliably distinguishable from C. cinerea.','Edible and itself harmless. BUT: risk of confusion with toxic Ramaria species – if confused, gastrointestinal complaints with abdominal pain, vomiting, diarrhoea 0.5-3 h after ingestion.',NULL,'Use only with reliable identification (white spore print, clavate-wrinkled) and distinction from Ramaria. Very low culinary value, mostly only as a mixed mushroom.',NULL,false),
('clavulina_rugosa','es','Carpóforo claviforme blanquecino a gris pálido, a menudo poco o nada ramificado, longitudinalmente rugoso-surcado, con extremos obtusos (no finamente dentados como C. coralloides). Esporada blanca. Microscópicamente no distinguible con certeza de C. cinerea.','Comestible y en sí inofensivo. PERO: riesgo de confusión con especies tóxicas de Ramaria – en caso de confusión, trastornos gastrointestinales con dolores abdominales, vómitos, diarrea 0,5-3 h tras la ingestión.',NULL,'Usar solo con determinación segura (esporada blanca, claviforme-rugoso) y distinción de Ramaria. Valor culinario muy escaso, casi siempre solo como seta de mezcla.',NULL,false),
('clavulina_rugosa','fr','Carpophore claviforme blanchâtre à gris pâle, souvent peu ou pas ramifié, longitudinalement ridé-sillonné, à extrémités obtuses (non finement dentées comme C. coralloides). Sporée blanche. Microscopiquement non distinguable avec certitude de C. cinerea.','Comestible en soi inoffensif. MAIS : risque de confusion avec des espèces toxiques de Ramaria – en cas de confusion, troubles gastro-intestinaux avec douleurs abdominales, vomissements, diarrhée 0,5-3 h après l''ingestion.',NULL,'N''utiliser qu''en cas de détermination sûre (sporée blanche, claviforme-ridé) et de distinction d''avec Ramaria. Très faible valeur culinaire, le plus souvent seulement comme champignon d''accompagnement.',NULL,false),
('clavulina_rugosa','it','Carpoforo claviforme biancastro a grigio pallido, spesso poco o per nulla ramificato, longitudinalmente rugoso-solcato, con estremità ottuse (non finemente dentate come C. coralloides). Sporata bianca. Microscopicamente non distinguibile con certezza da C. cinerea.','Commestibile di per sé innocuo. MA: rischio di confusione con specie tossiche di Ramaria – in caso di confusione, disturbi gastrointestinali con dolori addominali, vomito, diarrea 0,5-3 h dopo l''ingestione.',NULL,'Utilizzare solo in caso di determinazione sicura (sporata bianca, claviforme-rugoso) e distinzione da Ramaria. Valore alimentare molto scarso, per lo più solo come fungo da misto.',NULL,false),
('clitocybe_fragrans','en','Small thin-fleshed clitocybe, whitish-pale grey, with a distinct anise smell and a relatively long, slender stem. TOXIC: it belongs to the small white muscarine-containing Clitocybe species and is barely distinguishable with certainty from the deadly white funnel caps (C. dealbata, C. rivulosa). Because of the extreme risk of confusion, generally to be treated as a poisonous mushroom — never collect.','Muscarine (SLUDGE) syndrome 15-30 min after ingestion: heavy sweating, salivation and lacrimation, miosis (constricted pupils), abdominal cramps, nausea, vomiting, diarrhoea, bradycardia, drop in blood pressure; in severe cases circulatory collapse.','Call Tox Info Suisse 145 immediately. In severe muscarine syndrome atropine is the antidote — medical/emergency treatment. Keep mushroom remains/vomit for identification.',NULL,NULL,false),
('clitocybe_fragrans','es','Pequeño clitocybe de carne fina, blanquecino-gris pálido, con claro olor a anís y un pie relativamente largo y esbelto. TÓXICO: pertenece a los pequeños Clitocybe blancos con muscarina y apenas se distingue con certeza de los clitocybes blancos mortalmente tóxicos (C. dealbata, C. rivulosa). Debido al extremo riesgo de confusión, debe tratarse en general como seta venenosa — no recolectar nunca.','Síndrome muscarínico (SLUDGE) 15-30 min tras la ingestión: sudoración intensa, salivación y lagrimeo, miosis (pupilas contraídas), calambres abdominales, náuseas, vómitos, diarrea, bradicardia, caída de la tensión; en casos graves, colapso circulatorio.','Llamar de inmediato a Tox Info Suisse 145. En caso de síndrome muscarínico grave la atropina es el antídoto — tratamiento médico/de urgencia. Conservar los restos de seta/vómito para la determinación.',NULL,NULL,false),
('clitocybe_fragrans','fr','Petit clitocybe à chair mince, blanchâtre-gris pâle, avec une nette odeur d''anis et un pied relativement long et élancé. TOXIQUE : il appartient aux petits Clitocybe blancs muscariniens et est à peine distinguable avec certitude des clitocybes blancs mortellement toxiques (C. dealbata, C. rivulosa). En raison de l''extrême risque de confusion, à traiter généralement comme un champignon vénéneux — ne jamais récolter.','Syndrome muscarinien (SLUDGE) 15-30 min après l''ingestion : sudation intense, hypersalivation et larmoiement, myosis (pupilles rétrécies), crampes abdominales, nausées, vomissements, diarrhée, bradycardie, chute de tension ; dans les cas graves, collapsus circulatoire.','Appeler immédiatement Tox Info Suisse 145. En cas de syndrome muscarinien grave, l''atropine est l''antidote — traitement médical/d''urgence. Conserver les restes de champignon/vomissures pour la détermination.',NULL,NULL,false),
('clitocybe_fragrans','it','Piccolo clitocybe a carne sottile, biancastro-grigio pallido, con netto odore di anice e gambo relativamente lungo e snello. TOSSICO: appartiene ai piccoli Clitocybe bianchi muscarinici ed è a malapena distinguibile con certezza dai clitocybi bianchi mortalmente tossici (C. dealbata, C. rivulosa). A causa dell''estremo rischio di confusione, da trattare in generale come fungo velenoso — non raccogliere mai.','Sindrome muscarinica (SLUDGE) 15-30 min dopo l''ingestione: sudorazione intensa, scialorrea e lacrimazione, miosi (pupille ristrette), crampi addominali, nausea, vomito, diarrea, bradicardia, calo pressorio; nei casi gravi collasso circolatorio.','Chiamare immediatamente Tox Info Suisse 145. In caso di sindrome muscarinica grave l''atropina è l''antidoto — trattamento medico/d''urgenza. Conservare i resti del fungo/vomito per la determinazione.',NULL,NULL,false),
('coprinellus_disseminatus','en','Very small inkcap that grows in dense masses (often hundreds of fruiting bodies) in tufts on and around rotting hardwood stumps. Cap furrowed/grooved, when young pruinose-whitish, later grey. Unlike many inkcaps, it deliquesces only weakly.',NULL,NULL,NULL,NULL,false),
('coprinellus_disseminatus','es','Coprino muy pequeño que crece en masas densas (a menudo cientos de carpóforos) en grupos sobre y alrededor de tocones de frondosas en descomposición. Sombrero surcado/estriado, de joven pruinoso-blanquecino, luego gris. A diferencia de muchos coprinos, se licúa solo débilmente.',NULL,NULL,NULL,NULL,false),
('coprinellus_disseminatus','fr','Très petit coprin qui pousse en masses denses (souvent des centaines de carpophores) en touffes sur et autour des souches de feuillus pourrissantes. Chapeau sillonné/strié, jeune pruineux-blanchâtre, puis gris. Contrairement à beaucoup de coprins, il ne se liquéfie que faiblement.',NULL,NULL,NULL,NULL,false),
('coprinellus_disseminatus','it','Coprino molto piccolo che cresce in masse dense (spesso centinaia di carpofori) a ciuffi su e attorno a ceppi di latifoglie in decomposizione. Cappello solcato/striato, da giovane pruinoso-biancastro, poi grigio. A differenza di molti coprini, si liquefa solo debolmente.',NULL,NULL,NULL,NULL,false),
('coprinopsis_picacea','en','Large inkcap with a magpie pattern: dark cap with white, flaky veil remnants ("woodpecker pattern"). Gills deliquesce like ink (autolysis). Unpleasant tar/naphthalene-like smell. In beech woodland on limestone.','Coprine syndrome (antabuse effect) ONLY in combination with alcohol up to 72 h before/after consumption: facial flushing, racing heart, nausea, headache, circulatory collapse. Has the highest coprine content of all inkcaps. Additionally, gastrointestinal complaints possible.','If alcohol is consumed with the meal: strictly avoid any further alcohol. With circulatory symptoms, call Tox Info Suisse 145.',NULL,NULL,false),
('coprinopsis_picacea','es','Gran coprino con patrón de urraca: sombrero oscuro con restos de velo blancos y flocosos («patrón de pájaro carpintero»). Láminas que se licúan como tinta (autólisis). Olor desagradable a alquitrán/naftalina. En hayedo sobre caliza.','Síndrome coprínico (efecto antabús) SOLO en combinación con alcohol hasta 72 h antes/después de la ingestión: rubor facial, taquicardia, náuseas, dolor de cabeza, colapso circulatorio. Tiene el mayor contenido de coprina de todos los coprinos. Además, posibles trastornos gastrointestinales.','En caso de consumo de alcohol con la ingestión: evitar estrictamente cualquier otro alcohol. Con síntomas circulatorios, llamar a Tox Info Suisse 145.',NULL,NULL,false),
('coprinopsis_picacea','fr','Grand coprin au motif de pie : chapeau sombre avec des restes de voile blancs et floconneux (« motif de pic »). Lamelles se liquéfiant comme de l''encre (autolyse). Odeur désagréable de goudron/naphtaline. En hêtraie sur calcaire.','Syndrome coprinien (effet antabuse) UNIQUEMENT en association avec l''alcool jusqu''à 72 h avant/après l''ingestion : rougeur du visage, tachycardie, nausées, maux de tête, collapsus circulatoire. Possède la plus haute teneur en coprine de tous les coprins. En outre, troubles gastro-intestinaux possibles.','En cas de consommation d''alcool avec l''ingestion : éviter strictement tout autre alcool. En cas de symptômes circulatoires, appeler Tox Info Suisse 145.',NULL,NULL,false),
('coprinopsis_picacea','it','Grande coprino dal disegno a gazza: cappello scuro con resti di velo bianchi e flocculosi («disegno a picchio»). Lamelle che si liquefanno come inchiostro (autolisi). Odore sgradevole di catrame/naftalina. In faggeta su calcare.','Sindrome coprinica (effetto antabuse) SOLO in associazione con l''alcol fino a 72 h prima/dopo l''ingestione: rossore del viso, tachicardia, nausea, mal di testa, collasso circolatorio. Ha il più alto contenuto di coprina di tutti i coprini. Inoltre possibili disturbi gastrointestinali.','In caso di consumo di alcol con l''ingestione: evitare rigorosamente qualsiasi ulteriore alcol. In caso di sintomi circolatori chiamare Tox Info Suisse 145.',NULL,NULL,false),
('cortinarius_praestans','en','The largest webcap in Europe: cap up to 18 cm, when young globose and inrolled with whitish-violet radial veil fibres (wrinkled-veined cap margin). Bulbous-clavate stem with whitish, often guttate veil girdles. Spore print rust-brown (genus character Cortinarius). CAUTION: the entire genus contains deadly orellanine-containing species (C. orellanus, C. rubellus) — reliable identification only by certified experts. Never collect young or small webcaps.',NULL,'WARNING despite edibility: at any suspicion of confusion with deadly webcaps (orellanus syndrome: kidney failure only after 2-20 days, often recognised too late) call Tox Info Suisse 145 immediately. When in doubt do NOT eat — only consume if 100% confirmed by VAPKO experts.','Cook thoroughly (at least 15-20 min). Young, firm specimens; the veil can be removed. Only consume if unequivocally confirmed as C. praestans by mushroom control/VAPKO — the only marketable edible of the genus in Switzerland.',NULL,false),
('cortinarius_praestans','es','El cortinario más grande de Europa: sombrero de hasta 18 cm, de joven globoso y enrollado con fibras radiales de velo blanquecino-violáceo (margen del sombrero rugoso-venoso). Pie bulboso-claviforme con cinturones de velo blanquecinos, a menudo gutulados. Esporada pardo-herrumbre (carácter del género Cortinarius). ATENCIÓN: todo el género contiene especies mortales con orellanina (C. orellanus, C. rubellus) — la determinación segura solo es posible por expertos acreditados. Nunca recolectar cortinarios jóvenes o pequeños.',NULL,'ADVERTENCIA pese a la comestibilidad: ante cualquier sospecha de confusión con cortinarios mortales (síndrome orellánico: insuficiencia renal solo tras 2-20 días, a menudo reconocida demasiado tarde) llamar de inmediato a Tox Info Suisse 145. En caso de duda NO consumir — comer solo si está confirmado al 100% por expertos VAPKO.','Cocinar bien a fondo (al menos 15-20 min). Ejemplares jóvenes y firmes; el velo puede retirarse. Consumir solo si está identificado inequívocamente como C. praestans por el control de setas/VAPKO — único comestible comercializable del género en Suiza.',NULL,false),
('cortinarius_praestans','fr','Le plus grand cortinaire d''Europe : chapeau jusqu''à 18 cm, jeune globuleux et enroulé avec des fibres radiales de voile blanchâtre-violacé (marge du chapeau ridée-veinée). Pied bulbeux-claviforme avec des ceintures de voile blanchâtres, souvent guttulées. Sporée brun-rouille (caractère du genre Cortinarius). ATTENTION : le genre tout entier contient des espèces mortelles riches en orellanine (C. orellanus, C. rubellus) — la détermination sûre n''est possible que par des experts agréés. Ne jamais récolter de cortinaires jeunes ou petits.',NULL,'AVERTISSEMENT malgré la comestibilité : au moindre soupçon de confusion avec des cortinaires mortels (syndrome orellanien : insuffisance rénale seulement après 2-20 jours, souvent reconnue trop tard), appeler immédiatement Tox Info Suisse 145. En cas de doute, NE PAS consommer — ne manger que si confirmé à 100% par des experts VAPKO.','Bien cuire à cœur (au moins 15-20 min). Exemplaires jeunes et fermes ; le voile peut être retiré. À ne consommer que si identifié sans équivoque comme C. praestans par le contrôle des champignons/VAPKO — seul comestible commercialisable du genre en Suisse.',NULL,false),
('cortinarius_praestans','it','Il più grande cortinario d''Europa: cappello fino a 18 cm, da giovane globoso e arrotolato con fibre radiali di velo biancastro-violaceo (margine del cappello rugoso-venato). Gambo bulboso-claviforme con cinture di velo biancastre, spesso guttulate. Sporata bruno-ruggine (carattere del genere Cortinarius). ATTENZIONE: l''intero genere contiene specie mortali ricche di orellanina (C. orellanus, C. rubellus) — la determinazione sicura è possibile solo da parte di esperti riconosciuti. Non raccogliere mai cortinari giovani o piccoli.',NULL,'AVVERTENZA nonostante la commestibilità: a ogni sospetto di confusione con cortinari mortali (sindrome orellanica: insufficienza renale solo dopo 2-20 giorni, spesso riconosciuta troppo tardi) chiamare immediatamente Tox Info Suisse 145. In caso di dubbio NON consumare — mangiare solo se confermato al 100% da esperti VAPKO.','Cuocere bene a fondo (almeno 15-20 min). Esemplari giovani e sodi; il velo può essere rimosso. Consumare solo se identificato inequivocabilmente come C. praestans dal controllo dei funghi/VAPKO — unico commestibile commercializzabile del genere in Svizzera.',NULL,false),
('cortinarius_sanguineus','en','Small dermocybe coloured blood-red throughout: cap 1-4 cm, matt-finely felted, dark blood-red. Gills and stem also blood-red. Subgenus Dermocybe (dermocybes) — flesh and gills with red anthraquinone pigments (historically used for dyeing). Spore print rust-brown. Grows under spruce on acidic mossy ground.','Gastrointestinal complaints (nausea, vomiting, diarrhoea). The genus contains orellanine-related nephrotoxins — kidney damage not reliably excluded; strictly avoid.','If eaten, call Tox Info Suisse 145 immediately. Keep mushroom remains/vomit for identification. Because of possible delayed kidney damage (dermocybe/webcap kinship), seek medical evaluation even with initially mild symptoms.',NULL,NULL,false),
('cortinarius_sanguineus','es','Pequeña dermocybe coloreada por completo de rojo sangre: sombrero 1-4 cm, mate-finamente afieltrado, rojo sangre oscuro. Láminas y pie también rojo sangre. Subgénero Dermocybe (dermocybes) — carne y láminas con pigmentos antraquinónicos rojos (históricamente usados para teñir). Esporada pardo-herrumbre. Crece bajo abeto rojo en suelo musgoso ácido.','Trastornos gastrointestinales (náuseas, vómitos, diarrea). El género contiene nefrotoxinas emparentadas con la orellanina — daño renal no excluido con certeza; evitar estrictamente.','En caso de ingestión llamar de inmediato a Tox Info Suisse 145. Conservar los restos de seta/vómito para la determinación. Por un posible daño renal tardío (parentesco dermocybe/cortinario), evaluación médica incluso con síntomas inicialmente leves.',NULL,NULL,false),
('cortinarius_sanguineus','fr','Petit dermocybe entièrement coloré rouge sang : chapeau 1-4 cm, mat-finement feutré, rouge sang foncé. Lamelles et pied également rouge sang. Sous-genre Dermocybe (dermocybes) — chair et lamelles avec des pigments anthraquinoniques rouges (historiquement utilisés pour la teinture). Sporée brun-rouille. Pousse sous épicéa sur sol moussu acide.','Troubles gastro-intestinaux (nausées, vomissements, diarrhée). Le genre contient des néphrotoxines apparentées à l''orellanine — atteinte rénale non exclue avec certitude ; à éviter strictement.','En cas d''ingestion, appeler immédiatement Tox Info Suisse 145. Conserver les restes de champignon/vomissures pour la détermination. En raison d''une possible atteinte rénale retardée (parenté dermocybe/cortinaire), examen médical même en cas de symptômes initialement légers.',NULL,NULL,false),
('cortinarius_sanguineus','it','Piccola dermocybe interamente colorata di rosso sangue: cappello 1-4 cm, opaco-finemente feltrato, rosso sangue scuro. Lamelle e gambo anch''essi rosso sangue. Sottogenere Dermocybe (dermocybi) — carne e lamelle con pigmenti antrachinonici rossi (storicamente usati per tingere). Sporata bruno-ruggine. Cresce sotto abete rosso su suolo muscoso acido.','Disturbi gastrointestinali (nausea, vomito, diarrea). Il genere contiene nefrotossine imparentate con l''orellanina — danno renale non escluso con certezza; da evitare rigorosamente.','In caso di ingestione chiamare immediatamente Tox Info Suisse 145. Conservare i resti del fungo/vomito per la determinazione. A causa di un possibile danno renale ritardato (parentela dermocybe/cortinario) accertamento medico anche in caso di sintomi inizialmente lievi.',NULL,NULL,false),
('cortinarius_semisanguineus','en','Characteristic contrast: olive-/yellow-brown, matt-finely felted cap (2-5 cm) over BRIGHT BLOOD-RED gills — hence the name "blood-gilled". Stem yellowish to olivaceous, base often reddish-fibrillose. Subgenus Dermocybe (dermocybes). Spore print rust-brown. Under spruce/birch on acidic soil, often at bog margins.','Gastrointestinal irritation (vomiting, diarrhoea, dizziness, circulatory/visual disturbances) after 0.5-6 h. CRITICAL: orellanine detected → possible orellanus syndrome with delayed kidney failure only after 2-20 days (mushroom equally toxic raw, dried AND cooked).','If eaten, call Tox Info Suisse 145 IMMEDIATELY — even without early symptoms, as kidney damage (orellanus syndrome) only appears days later and is barely detectable early. Keep mushroom remains. Inpatient monitoring of kidney values indicated.',NULL,NULL,false),
('cortinarius_semisanguineus','es','Contraste característico: sombrero pardo-oliva/pardo-amarillento, mate-finamente afieltrado (2-5 cm) sobre láminas ROJO SANGRE BRILLANTE — de ahí el nombre «de láminas sanguíneas». Pie amarillento a oliváceo, base a menudo con fibrillas rojizas. Subgénero Dermocybe (dermocybes). Esporada pardo-herrumbre. Bajo abeto rojo/abedul en suelo ácido, a menudo en bordes de turberas.','Irritación gastrointestinal (vómitos, diarrea, mareos, trastornos circulatorios/visuales) tras 0,5-6 h. CRÍTICO: orellanina detectada → posible síndrome orellánico con insuficiencia renal tardía solo tras 2-20 días (seta igualmente tóxica cruda, seca Y cocida).','En caso de ingestión llamar de INMEDIATO a Tox Info Suisse 145 — incluso sin síntomas tempranos, ya que el daño renal (síndrome orellánico) solo aparece días después y apenas es detectable al inicio. Conservar los restos de seta. Indicada la monitorización hospitalaria de los valores renales.',NULL,NULL,false),
('cortinarius_semisanguineus','fr','Contraste caractéristique : chapeau brun-olive/jaune-brun, mat-finement feutré (2-5 cm) au-dessus de lamelles ROUGE SANG ÉCLATANT — d''où le nom « à lamelles sanguines ». Pied jaunâtre à olivâtre, base souvent fibrillée de rougeâtre. Sous-genre Dermocybe (dermocybes). Sporée brun-rouille. Sous épicéa/bouleau sur sol acide, souvent en bordure de tourbières.','Irritation gastro-intestinale (vomissements, diarrhée, vertiges, troubles circulatoires/visuels) après 0,5-6 h. CRITIQUE : orellanine mise en évidence → syndrome orellanien possible avec insuffisance rénale retardée seulement après 2-20 jours (champignon cru, séché ET cuit également toxique).','En cas d''ingestion, appeler IMMÉDIATEMENT Tox Info Suisse 145 — même sans symptômes précoces, car les atteintes rénales (syndrome orellanien) n''apparaissent que des jours plus tard et sont à peine décelables tôt. Conserver les restes de champignon. Surveillance hospitalière des valeurs rénales indiquée.',NULL,NULL,false),
('cortinarius_semisanguineus','it','Contrasto caratteristico: cappello bruno-oliva/giallo-bruno, opaco-finemente feltrato (2-5 cm) sopra lamelle ROSSO SANGUE BRILLANTE — da cui il nome «a lamelle sanguigne». Gambo giallastro o olivastro, base spesso fibrillata di rossastro. Sottogenere Dermocybe (dermocybi). Sporata bruno-ruggine. Sotto abete rosso/betulla su suolo acido, spesso ai margini delle torbiere.','Irritazione gastrointestinale (vomito, diarrea, vertigini, disturbi circolatori/visivi) dopo 0,5-6 h. CRITICO: orellanina rilevata → possibile sindrome orellanica con insufficienza renale ritardata solo dopo 2-20 giorni (fungo crudo, essiccato E cotto ugualmente tossico).','In caso di ingestione chiamare IMMEDIATAMENTE Tox Info Suisse 145 — anche senza sintomi precoci, poiché i danni renali (sindrome orellanica) compaiono solo giorni dopo e sono a malapena riconoscibili all''inizio. Conservare i resti del fungo. Indicato il monitoraggio ospedaliero dei valori renali.',NULL,NULL,false),
('cortinarius_traganus','en','Cap and stem externally pale blue-violet/lilac, MATT and dry. Decisive distinction from the edible/inedible C. violaceus: gills when young ochre-yellowish/clay-coloured (NOT violet), stem flesh saffron-yellow to brownish when cut, and a typical unpleasant gas/goat smell. Stem bulbous-clavate and thick ("clubfoot"). Spore print rust-brown.','Gastrointestinal complaints (abdominal pain, nausea, vomiting, persistent diarrhoea) about 0.5-3 h after ingestion. Classified as "mildly toxic"; additionally a risk of confusion with more dangerous webcaps.','If eaten, call Tox Info Suisse 145, especially with persistent vomiting/diarrhoea. Keep mushroom remains for identification, to rule out confusion with more dangerous webcaps.',NULL,NULL,false),
('cortinarius_traganus','es','Sombrero y pie externamente azul-violeta/lila pálido, MATES y secos. Distinción decisiva del C. violaceus comestible/no comestible: láminas de joven ocre-amarillentas/arcillosas (NO violetas), carne del pie amarillo azafrán-parduzca al corte, y típico olor desagradable a gas/macho cabrío. Pie bulboso-claviforme grueso («pie grueso»). Esporada pardo-herrumbre.','Trastornos gastrointestinales (dolores abdominales, náuseas, vómitos, diarrea persistente) aprox. 0,5-3 h tras la ingestión. Clasificado como «levemente tóxico»; además riesgo de confusión con cortinarios más peligrosos.','En caso de ingestión llamar a Tox Info Suisse 145, sobre todo con vómitos/diarrea persistentes. Conservar los restos de seta para la determinación, a fin de excluir una confusión con cortinarios más peligrosos.',NULL,NULL,false),
('cortinarius_traganus','fr','Chapeau et pied extérieurement bleu-violet/lilas pâle, MATS et secs. Distinction décisive d''avec C. violaceus comestible/non comestible : lamelles jeunes jaune-ocre/argileuses (NON violettes), chair du pied jaune safran-brunâtre à la coupe, et odeur désagréable typique de gaz/bouc. Pied bulbeux-claviforme épais (« pied épais »). Sporée brun-rouille.','Troubles gastro-intestinaux (douleurs abdominales, nausées, vomissements, diarrhée persistante) env. 0,5-3 h après l''ingestion. Classé « faiblement toxique » ; en outre risque de confusion avec des cortinaires plus dangereux.','En cas d''ingestion, appeler Tox Info Suisse 145, surtout en cas de vomissements/diarrhée persistants. Conserver les restes de champignon pour la détermination, afin d''exclure une confusion avec des cortinaires plus dangereux.',NULL,NULL,false),
('cortinarius_traganus','it','Cappello e gambo esternamente blu-violetto/lilla pallido, OPACHI e asciutti. Distinzione decisiva dal C. violaceus commestibile/non commestibile: lamelle da giovani ocra-giallastre/argillose (NON violette), carne del gambo giallo zafferano-brunastra al taglio, e tipico odore sgradevole di gas/becco. Gambo bulboso-claviforme spesso («piede grosso»). Sporata bruno-ruggine.','Disturbi gastrointestinali (dolori addominali, nausea, vomito, diarrea persistente) circa 0,5-3 h dopo l''ingestione. Classificato come «debolmente tossico»; inoltre rischio di confusione con cortinari più pericolosi.','In caso di ingestione chiamare Tox Info Suisse 145, soprattutto in caso di vomito/diarrea persistenti. Conservare i resti del fungo per la determinazione, per escludere una confusione con cortinari più pericolosi.',NULL,NULL,false),
('cortinarius_violaceus','en','Fruiting body coloured throughout a deep dark/blackish violet. Cap up to 15 cm, finely scaly-felty and matt (not slimy). Stem clavately thickened, fibrous-violet. Flesh violet when cut, smell of cedar wood. Spore print rust-brown (genus character). Can be confused with the toxic lilac clubfoot (C. traganus), which however smells of gas/carbide and has saffron-yellowish stem flesh.',NULL,NULL,NULL,NULL,false),
('cortinarius_violaceus','es','Carpóforo coloreado por completo de un violeta oscuro/negruzco intenso. Sombrero de hasta 15 cm, finamente escamoso-afieltrado y mate (no viscoso). Pie engrosado en maza, fibrilloso-violeta. Carne violácea al corte, olor a madera de cedro. Esporada pardo-herrumbre (carácter del género). Confundible con el cortinario tóxico de pie grueso lila (C. traganus), que sin embargo huele a gas/carburo y tiene la carne del pie amarillo azafrán.',NULL,NULL,NULL,NULL,false),
('cortinarius_violaceus','fr','Carpophore entièrement coloré d''un violet sombre/noirâtre profond. Chapeau jusqu''à 15 cm, finement squameux-feutré et mat (non visqueux). Pied épaissi en massue, fibrilleux-violet. Chair violacée à la coupe, odeur de bois de cèdre. Sporée brun-rouille (caractère du genre). Confusion possible avec le cortinaire à pied épais lilas toxique (C. traganus), qui sent toutefois le gaz/carbure et dont la chair du pied est jaune safrané.',NULL,NULL,NULL,NULL,false),
('cortinarius_violaceus','it','Carpoforo interamente colorato di un viola scuro/nerastro profondo. Cappello fino a 15 cm, finemente squamoso-feltrato e opaco (non viscido). Gambo ingrossato a clava, fibrilloso-violaceo. Carne violacea al taglio, odore di legno di cedro. Sporata bruno-ruggine (carattere del genere). Confondibile con il cortinario tossico dal piede grosso lilla (C. traganus), che però odora di gas/carburo e ha la carne del gambo giallo zafferano.',NULL,NULL,NULL,NULL,false),
('cuphophyllus_pratensis','en','Fleshy convex to umbonate orange-salmon cap (2-7 cm), thick, widely spaced and deeply decurrent pale gills, firm smooth stem without slime. Grows in nutrient-poor meadows. The dry cap surface distinguishes it from slimy waxcaps.',NULL,NULL,'Raw it is toxic/indigestible – must be thoroughly heated. Cook well through (at least 15 min frying/braising), a good edible.',NULL,false),
('cuphophyllus_pratensis','es','Sombrero carnoso, de convexo a mamelonado, de color naranja-salmón (2-7 cm), láminas gruesas, separadas y largamente decurrentes, pálidas, pie firme y liso sin mucílago. Crece en prados pobres en nutrientes. La superficie seca del sombrero lo distingue de las higróforas viscosas.',NULL,NULL,'Crudo es tóxico/indigesto – debe cocinarse bien. Cocinar bien por completo (al menos 15 min salteado/estofado), buen comestible.',NULL,false),
('cuphophyllus_pratensis','fr','Chapeau charnu, convexe à mamelonné, de couleur orange-saumon (2-7 cm), lamelles épaisses, espacées et longuement décurrentes, pâles, pied ferme et lisse sans mucus. Pousse dans les prairies pauvres en nutriments. La surface sèche du chapeau le distingue des hygrophores visqueux.',NULL,NULL,'Cru, toxique/indigeste – doit être bien cuit. Bien cuire à cœur (au moins 15 min à la poêle ou à l''étuvée), bon comestible.',NULL,false),
('cuphophyllus_pratensis','it','Cappello carnoso, da convesso a umbonato, di colore arancio-salmone (2-7 cm), lamelle spesse, distanziate e lungamente decorrenti, pallide, gambo sodo e liscio privo di mucillagine. Cresce in prati poveri di nutrienti. La superficie asciutta del cappello lo distingue dalle igrofore vischiose.',NULL,NULL,'Crudo è tossico/indigesto – deve essere ben cotto. Cuocere bene a fondo (almeno 15 min in padella o in umido), buon commestibile.',NULL,false),
('cuphophyllus_virgineus','en','Small snow-white to glassy-translucent cap (1-4 cm), white widely decurrent gills, white stem. Grows on poor (nutrient-low) grasslands. CAUTION: deadly white funnel caps grow in the same habitat niche – consume only with certain gill/spore identification.',NULL,NULL,'Edible, but because of deadly white look-alikes only for sure experts; cook thoroughly. When in doubt, leave it standing.',NULL,false),
('cuphophyllus_virgineus','es','Sombrero pequeño blanco nieve a translúcido vítreo (1-4 cm), láminas blancas ampliamente decurrentes, pie blanco. Crece en prados pobres. ATENCIÓN: en el mismo nicho de hábitat crecen clitocibes blancos mortales – consumir solo con identificación segura de láminas y esporas.',NULL,NULL,'Comestible, pero debido a los sosias blancos mortales solo para conocedores seguros; cocinar bien. En caso de duda, dejarlo en su sitio.',NULL,false),
('cuphophyllus_virgineus','fr','Petit chapeau blanc neige à translucide vitreux (1-4 cm), lames blanches longuement décurrentes, pied blanc. Pousse dans les prairies maigres. ATTENTION : des clitocybes blancs mortels poussent dans le même habitat – ne consommer qu''avec une détermination sûre des lames et des spores.',NULL,NULL,'Comestible, mais en raison des sosies blancs mortels, réservé aux seuls connaisseurs sûrs ; bien cuire. En cas de doute, laisser sur place.',NULL,false),
('cuphophyllus_virgineus','it','Piccolo cappello bianco neve fino a traslucido vitreo (1-4 cm), lamelle bianche ampiamente decorrenti, gambo bianco. Cresce su prati magri. ATTENZIONE: nella stessa nicchia di habitat crescono clitocibi bianchi mortali – consumare solo con sicura determinazione di lamelle e spore.',NULL,NULL,'Commestibile, ma a causa dei sosia bianchi mortali solo per esperti sicuri; cuocere bene. In caso di dubbio lasciare sul posto.',NULL,false),
('daedaleopsis_confragosa','en','Bracket-shaped, flat, zonate grey-brown fruiting body on broadleaf wood (often willow, birch, alder). Characteristic is the highly variable underside that reddens to brownish-red on pressure/injury (from rounded pores through labyrinthine to almost gill-like). Corky-tough, perennial. Inedible. Confusion possible with Trametes hirsuta and the three-coloured polypore (D. tricolor).',NULL,NULL,NULL,NULL,false),
('daedaleopsis_confragosa','es','Cuerpo fructífero en forma de ménsula, plano, zonado gris-pardo sobre madera de frondosas (a menudo sauce, abedul, aliso). Característica es la cara inferior muy variable que enrojece hasta pardo-rojizo a la presión/lesión (desde poros redondeados pasando por laberínticos hasta casi laminares). Suberoso-tenaz, plurianual. Incomestible. Posible confusión con Trametes hirsuta y la tramete tricolor (D. tricolor).',NULL,NULL,NULL,NULL,false),
('daedaleopsis_confragosa','fr','Carpophore en console, plat, zoné gris-brun sur bois de feuillus (souvent saule, bouleau, aulne). Caractéristique : la face inférieure très variable rougissant à brunissant à la pression/blessure (de pores arrondis à labyrinthiques jusqu''à presque lamellés). Subéreux-coriace, pluriannuel. Immangeable. Confusion possible avec Trametes hirsuta et le tramète tricolore (D. tricolor).',NULL,NULL,NULL,NULL,false),
('daedaleopsis_confragosa','it','Corpo fruttifero a mensola, piatto, zonato grigio-bruno su legno di latifoglie (spesso salice, betulla, ontano). Caratteristica la faccia inferiore molto variabile che arrossa fino a imbrunire alla pressione/lesione (da pori arrotondati a labirintici fino a quasi lamellati). Suberoso-tenace, pluriennale. Immangiabile. Possibile confusione con Trametes hirsuta e con il tramete tricolore (D. tricolor).',NULL,NULL,NULL,NULL,false),
('disciotis_venosa','en','Large fruiting body, at first cup-shaped, later flat bowl-shaped with a wavy margin. Inner surface brown and characteristically veined to wrinkled-furrowed, outer surface pale and finely granular. Practically stalkless, sitting on the ground. Striking chlorine smell in fresh specimens.','Raw or insufficiently cooked, morel-like complaints possible (gastrointestinal, morel-syndrome-like).','In case of complaints after consumption, call Tox Info Suisse 145. Never eat raw.','As a morel relative, eat only when well-cooked (at least 15 minutes). The chlorine smell disappears on cooking. Discard the cooking water.',NULL,false),
('disciotis_venosa','es','Cuerpo fructífero grande, al principio en forma de copa, luego de cuenco aplanado con borde ondulado. Cara interna parda y característicamente venada hasta rugoso-surcada, cara externa clara y finamente granulosa. Prácticamente sin pie, asentado sobre el suelo. Olor a cloro llamativo en los ejemplares frescos.','Crudo o insuficientemente cocido, posibles molestias de tipo colmenilla (gastrointestinales, similares al síndrome de la colmenilla).','En caso de molestias tras el consumo, llamar a Tox Info Suisse 145. Nunca comer crudo.','Como pariente de la colmenilla, consumir solo bien cocido (al menos 15 minutos). El olor a cloro desaparece al cocer. Desechar el agua de cocción.',NULL,false),
('disciotis_venosa','fr','Grand carpophore d''abord en coupe, puis en cuvette aplatie à bord ondulé. Face interne brune et caractéristiquement veinée à ridée-sillonnée, face externe claire et finement granuleuse. Pratiquement sessile, posé sur le sol. Odeur de chlore marquée des exemplaires frais.','Cru ou insuffisamment cuit, troubles de type morille possibles (gastro-intestinaux, semblables au syndrome de la morille).','En cas de troubles après consommation, appeler Tox Info Suisse 145. Ne jamais manger cru.','Comme apparenté à la morille, ne consommer que bien cuit (au moins 15 minutes). L''odeur de chlore disparaît à la cuisson. Jeter l''eau de cuisson.',NULL,false),
('disciotis_venosa','it','Grande corpo fruttifero dapprima a coppa, poi a scodella appiattita con margine ondulato. Faccia interna bruna e caratteristicamente venata fino a rugoso-solcata, faccia esterna chiara e finemente granulosa. Praticamente sessile, adagiato sul terreno. Odore di cloro marcato negli esemplari freschi.','Crudo o cotto insufficientemente, possibili disturbi simili a quelli delle spugnole (gastrointestinali, simili alla sindrome della spugnola).','In caso di disturbi dopo il consumo chiamare Tox Info Suisse 145. Non mangiare mai crudo.','Come parente delle spugnole consumare solo ben cotto (almeno 15 minuti). L''odore di cloro scompare con la cottura. Gettare l''acqua di cottura.',NULL,false),
('geastrum_triplex','en','Star-shaped: the thick outer layer (exoperidium) splits into 4–8 (usually 5) lobes; characteristically the fleshy inner layer breaks in a ring around the central spore sac and forms a bowl-/collar-like ''ruff'' — a reliable identifying feature. Spore sac with a fringed, sharply delimited peristome. The largest native earthstar. Inedible (tough, corky-leathery consistency); no known culinary value.',NULL,NULL,NULL,NULL,false),
('geastrum_triplex','es','En forma de estrella: la envoltura externa gruesa (exoperidio) se rasga en 4–8 (por lo general 5) lóbulos; característicamente la capa interna carnosa se quiebra en anillo alrededor de la esfera esporífera central y forma una ''gorguera'' en forma de cuenco/collar — criterio de identificación seguro. Esfera esporífera con un peristoma fimbriado y netamente delimitado. La mayor estrella de tierra autóctona. Incomestible (consistencia tenaz, suberoso-coriácea); sin valor culinario conocido.',NULL,NULL,NULL,NULL,false),
('geastrum_triplex','fr','En forme d''étoile : l''enveloppe externe épaisse (exopéridie) se déchire en 4–8 (le plus souvent 5) lobes ; caractéristique, la couche interne charnue se brise en anneau autour de la sphère sporifère centrale et forme une ''collerette'' en cuvette/collet — critère de détermination sûr. Sphère sporifère à péristome frangé et nettement délimité. Plus grande géastre indigène. Immangeable (consistance coriace, subéreuse-cuirée) ; aucune valeur culinaire connue.',NULL,NULL,NULL,NULL,false),
('geastrum_triplex','it','A forma di stella: l''involucro esterno spesso (esoperidio) si lacera in 4–8 (per lo più 5) lobi; caratteristicamente lo strato interno carnoso si spezza ad anello attorno alla sfera sporifera centrale e forma un ''collare'' a scodella/colletto — criterio di determinazione sicuro. Sfera sporifera con peristoma frangiato e nettamente delimitato. La più grande geastro indigena. Immangiabile (consistenza tenace, suberoso-coriacea); nessun valore culinario noto.',NULL,NULL,NULL,NULL,false),
('gomphidius_roseus','en','Small, slimy mushroom with a glutinous, bright pink to coral-red cap. Gills (not a bolete!) thick, widely spaced, decurrent, whitish when young, turning sooty-black with age from the spore powder. Stem base yellow. Almost always grows in the immediate vicinity of the bovine bolete (Suillus bovinus), whose mycelium it parasitises. Spore print black.',NULL,NULL,'Theoretically edible (after peeling off the slimy skin), but thin-fleshed and of no culinary value, hence practically inedible. Protected as an endangered red-list species in parts of Central Europe — do not pick, leave standing.',NULL,false),
('gomphidius_roseus','es','Hongo pequeño y viscoso con sombrero glutinoso, de rosa intenso a rojo coral. Láminas (¡no es un boleto!) gruesas, separadas, decurrentes, blanquecinas de joven, que con la edad se vuelven negro hollín por el polvo de esporas. Base del pie amarilla. Crece prácticamente siempre en las inmediaciones del boleto de las vacas (Suillus bovinus), cuyo micelio parasita. Esporada negra.',NULL,NULL,'Teóricamente comestible (tras retirar la cutícula viscosa), pero de carne escasa y sin valor culinario, por lo que es prácticamente incomestible. Protegido como especie amenazada de la lista roja en algunas partes de Europa central — no recolectar, dejar en su sitio.',NULL,false),
('gomphidius_roseus','fr','Petit champignon visqueux à chapeau gluant, rose vif à rouge corail. Lames (ce n''est pas un bolet !) épaisses, espacées, décurrentes, blanchâtres jeunes, devenant noir suie avec l''âge sous l''effet de la sporée. Base du pied jaune. Pousse pratiquement toujours à proximité immédiate du bolet des bouviers (Suillus bovinus), dont il parasite le mycélium. Sporée noire.',NULL,NULL,'Théoriquement comestible (après retrait de la cuticule visqueuse), mais à chair maigre et sans valeur culinaire, donc pratiquement immangeable. Protégé comme espèce menacée de la liste rouge dans certaines parties de l''Europe centrale — ne pas cueillir, laisser sur place.',NULL,false),
('gomphidius_roseus','it','Piccolo fungo viscido con cappello vischioso, rosa vivo fino a rosso corallo. Lamelle (non è un boleto!) spesse, rade, decorrenti, da giovani biancastre, con l''età annerite a fuliggine dalla polvere sporale. Base del gambo gialla. Cresce praticamente sempre nelle immediate vicinanze del boleto dei bovini (Suillus bovinus), di cui parassita il micelio. Polvere sporale nera.',NULL,NULL,'Teoricamente commestibile (dopo aver rimosso la cuticola mucillaginosa), ma con carne esigua e privo di valore culinario, quindi praticamente immangiabile. Protetto come specie minacciata della lista rossa in alcune parti dell''Europa centrale — non raccogliere, lasciare sul posto.',NULL,false),
('gymnopilus_junonius','en','Large, robust rustgill (cap up to 15 cm), in tufts at the base of broadleaf-tree stumps. Cap golden to rusty orange, scaly when young. Gills yellow when young, rust-brown when mature. Stem clavate, with a distinct membranous RING (distinguishing it from the small, ringless G. penetrans). Very bitter. Toxic — neurotoxic gymnopilines; some populations (mainly outside Europe) contain psilocybin.','Neurotoxic/hallucinogenic effect (gymnopilines), intoxication states in psilocybin-containing populations; generally gastrointestinal complaints. Classified as toxic.','In case of consumption and symptoms (neurological/hallucinogenic or gastrointestinal), call Tox Info Suisse 145. Keep the mushroom remains, reassure and observe the affected person; in case of circulatory/consciousness disturbances, call emergency 144.',NULL,NULL,false),
('gymnopilus_junonius','es','Gimnopilo grande y robusto (sombrero hasta 15 cm), en grupos cespitosos en la base de tocones de frondosas. Sombrero de naranja dorado a herrumbre, escamoso de joven. Láminas amarillas de joven, pardo herrumbre al madurar. Pie claviforme, con un ANILLO membranoso bien marcado (distinción del pequeño G. penetrans sin anillo). Muy amargo. Tóxico — gimnopilinas neurotóxicas; algunas poblaciones (sobre todo fuera de Europa) contienen psilocibina.','Efecto neurotóxico/alucinógeno (gimnopilinas), estados de embriaguez en poblaciones con psilocibina; en general trastornos gastrointestinales. Clasificado como tóxico.','En caso de consumo y molestias (neurológicas/alucinógenas o gastrointestinales), llamar a Tox Info Suisse 145. Conservar los restos de los hongos, tranquilizar y vigilar a la persona afectada; en caso de trastornos circulatorios/de la consciencia, llamar a emergencias 144.',NULL,NULL,false),
('gymnopilus_junonius','fr','Grand gymnopile robuste (chapeau jusqu''à 15 cm), en touffes à la base de souches de feuillus. Chapeau orange doré à rouille, squameux jeune. Lames jaunes jeunes, brun rouille à maturité. Pied claviforme, avec un ANNEAU membraneux net (distinction d''avec le petit G. penetrans sans anneau). Très amer. Toxique — gymnopilines neurotoxiques ; certaines populations (surtout hors d''Europe) contiennent de la psilocybine.','Effet neurotoxique/hallucinogène (gymnopilines), états d''ivresse chez les populations à psilocybine ; en général troubles gastro-intestinaux. Classé comme toxique.','En cas de consommation et de troubles (neurologiques/hallucinogènes ou gastro-intestinaux), appeler Tox Info Suisse 145. Conserver les restes de champignons, rassurer et surveiller la personne concernée ; en cas de troubles circulatoires/de la conscience, appeler les urgences 144.',NULL,NULL,false),
('gymnopilus_junonius','it','Grande gimnopilo robusto (cappello fino a 15 cm), cespitoso alla base di ceppi di latifoglie. Cappello da arancio dorato a ruggine, da giovane squamoso. Lamelle da giovani gialle, a maturità bruno ruggine. Gambo claviforme, con netto ANELLO membranoso (distinzione dal piccolo G. penetrans privo di anello). Molto amaro. Tossico — gimnopiline neurotossiche; alcune popolazioni (soprattutto fuori dall''Europa) contengono psilocibina.','Effetto neurotossico/allucinogeno (gimnopiline), stati di ebbrezza nelle popolazioni con psilocibina; in generale disturbi gastrointestinali. Classificato come tossico.','In caso di consumo e disturbi (neurologici/allucinogeni o gastrointestinali) chiamare Tox Info Suisse 145. Conservare i resti dei funghi, tranquillizzare e tenere sotto osservazione la persona interessata; in caso di disturbi circolatori/della coscienza chiamare il numero d''emergenza 144.',NULL,NULL,false),
('gymnopilus_penetrans','en','Small to medium, solitary to gregarious on dead conifer wood (stumps, branches). Cap cinnamon to rusty yellow. Gills yellowish when young, cinnamon to rust-brown when mature, typically RUST-SPOTTED with age (the source of the name). Stem pale yellow, fibrous, with a fleeting veil zone (no firm ring — distinguishing it from the large, ringed G. junonius). Very bitter — inedible.','Contains substances that can trigger haemolysis and agglutination of red blood cells; due to its bitterness and these substances, unsuitable for consumption.',NULL,NULL,NULL,false),
('gymnopilus_penetrans','es','De pequeño a mediano, de solitario a gregario sobre madera muerta de conífera (tocones, ramas). Sombrero de canela a amarillo herrumbre. Láminas amarillentas de joven, de canela a pardo herrumbre al madurar, típicamente MANCHADAS DE HERRUMBRE con la edad (de ahí el nombre). Pie amarillo pálido, fibroso, con una zona velar fugaz (sin anillo firme — distinción del grande G. junonius anillado). Muy amargo — incomestible.','Contiene sustancias que pueden provocar hemólisis y aglutinación de los glóbulos rojos; debido al amargor y a estas sustancias, no apto para el consumo.',NULL,NULL,NULL,false),
('gymnopilus_penetrans','fr','Petit à moyen, isolé à grégaire sur bois de conifère mort (souches, branches). Chapeau cannelle à jaune rouille. Lames jaunâtres jeunes, cannelle à brun rouille à maturité, typiquement TACHETÉES DE ROUILLE avec l''âge (d''où le nom). Pied jaune pâle, fibreux, avec une zone vélaire fugace (pas d''anneau ferme — distinction d''avec le grand G. junonius annelé). Très amer — immangeable.','Contient des substances pouvant provoquer hémolyse et agglutination des globules rouges ; en raison de l''amertume et de ces substances, impropre à la consommation.',NULL,NULL,NULL,false),
('gymnopilus_penetrans','it','Da piccolo a medio, da solitario a gregario su legno di conifera morto (ceppi, rami). Cappello da cannella a giallo ruggine. Lamelle da giovani giallastre, a maturità da cannella a bruno ruggine, con l''età tipicamente MACCHIATE DI RUGGINE (da cui il nome). Gambo giallo pallido, fibroso, con zona velare fugace (nessun anello consistente — distinzione dal grande G. junonius anellato). Molto amaro — immangiabile.','Contiene sostanze che possono provocare emolisi e agglutinazione dei globuli rossi; a causa dell''amarezza e di queste sostanze non idoneo al consumo.',NULL,NULL,NULL,false),
('gymnopus_dryophilus','en','Cap 2-5 cm, smooth, bald, red-brown when young, fading to ochre/honey-yellow, often hygrophanous. Gills whitish to pale yellow, very crowded. Stem smooth, cartilaginous-tough, concolorous or paler than the cap, hollow, base often with white mycelial felt. Spore print whitish (oak collybia). Grows gregariously in litter and on fallen leaves.','Raw inedible/intolerable. The collybias of this group are considered an intolerable group: in sensitive people gastrointestinal complaints (nausea, diarrhoea) possible even after cooking; only when young, well-cooked and as a mixed mushroom in small amounts. In case of repeated intolerance, avoid the species.',NULL,'Only young, firm specimens, well-cooked as a mixed mushroom; stems tough; low food value; because of intolerance reports, only a small amount at the first meal.',NULL,false),
('gymnopus_dryophilus','es','Sombrero 2-5 cm, liso, glabro, pardo rojizo de joven, palideciendo a ocre/amarillo miel, a menudo higrófano. Láminas blanquecinas a amarillo pálido, muy apretadas. Pie liso, cartilaginoso-tenaz, concoloro o más claro que el sombrero, hueco, base a menudo con fieltro miceliar blanco. Esporada blanquecina (colibia de los robles). Crece gregario en la hojarasca y sobre hojas caídas.','Crudo incomestible/mal tolerado. Las colibias de este grupo se consideran un grupo mal tolerado: en personas sensibles son posibles trastornos gastrointestinales (náuseas, diarrea) incluso tras la cocción; solo joven, bien cocido y como hongo de mezcla en pequeñas cantidades. En caso de intolerancia repetida, evitar la especie.',NULL,'Solo ejemplares jóvenes y firmes, bien cocidos como hongo de mezcla; pies tenaces; escaso valor alimentario; debido a los informes de intolerancia, en la primera comida solo una pequeña cantidad.',NULL,false),
('gymnopus_dryophilus','fr','Chapeau 2-5 cm, lisse, glabre, brun rouge jeune, se décolorant en ocre/jaune miel, souvent hygrophane. Lames blanchâtres à jaune pâle, très serrées. Pied lisse, cartilagineux-coriace, concolore ou plus clair que le chapeau, creux, base souvent garnie d''un feutrage mycélien blanc. Sporée blanchâtre (collybie des chênes). Pousse en groupe dans la litière et sur les feuilles mortes.','Immangeable/mal toléré cru. Les collybies de ce groupe sont réputées mal tolérées : chez les personnes sensibles, troubles gastro-intestinaux (nausées, diarrhée) possibles même après cuisson ; seulement jeune, bien cuit et en mélange, en faible quantité. En cas d''intolérance répétée, éviter l''espèce.',NULL,'Seulement des exemplaires jeunes et fermes, bien cuits en mélange ; pieds coriaces ; faible valeur gustative ; en raison des cas d''intolérance, ne prendre qu''une petite quantité au premier repas.',NULL,false),
('gymnopus_dryophilus','it','Cappello 2-5 cm, liscio, glabro, da giovane rosso-bruno, sbiadente in ocra/giallo miele, spesso igrofano. Lamelle da biancastre a giallo pallido, molto fitte. Gambo liscio, cartilagineo-tenace, concolore o più chiaro del cappello, cavo, base spesso con feltro miceliare bianco. Polvere sporale biancastra (collibia delle querce). Cresce gregario nella lettiera e sulle foglie cadute.','Crudo immangiabile/mal tollerato. Le collibie di questo gruppo sono ritenute mal tollerate: in persone sensibili possibili disturbi gastrointestinali (nausea, diarrea) anche dopo cottura; solo giovane, ben cotto e come fungo da mescolanza in piccole quantità. In caso di intolleranza ripetuta evitare la specie.',NULL,'Solo esemplari giovani e sodi, ben cotti in mescolanza; gambi tenaci; scarso valore alimentare; a causa delle segnalazioni di intolleranza, al primo pasto solo piccola quantità.',NULL,false),
('gymnopus_peronatus','en','Cap up to 8-10 cm, yellow to red-brown, wrinkled, hygrophanous. Diagnostic is the burning-acrid/peppery taste after brief chewing (warning feature — taste test only by chewing and spitting out). Stem base conspicuously bristly-felted (the name peronatus = ''booted''). Gills distant, yellowish when young, red-brown when old. Current name Collybiopsis peronata (Petersen 2021), in CH/D field guides mostly still listed as Gymnopus peronatus.','Gastrointestinal irritation from acrid irritant substances (nausea, vomiting, diarrhoea). Indications of toxic hydrocyanic (prussic) acid compounds, therefore to be treated as toxic; inedible raw and cooked due to the burning acridity.','No consumption. In case of accidental intake and symptoms: call Tox Info Suisse 145 (24h), keep mushroom remains/photo. In case of persistent vomiting/diarrhoea, take fluids and seek medical evaluation.',NULL,NULL,false),
('gymnopus_peronatus','es','Sombrero hasta 8-10 cm, de amarillo a pardo rojizo, rugoso, higrófano. Diagnóstico es el sabor ardiente-acre/picante tras una breve masticación (señal de alarma — prueba de sabor solo masticando y escupiendo). Base del pie llamativamente híspido-afieltrada (el nombre peronatus = ''calzado con botas''). Láminas separadas, amarillentas de joven, pardo rojizas de viejo. Nombre actual Collybiopsis peronata (Petersen 2021), en las guías CH/D mayormente todavía listado como Gymnopus peronatus.','Irritación gastrointestinal por sustancias irritantes acres (náuseas, vómitos, diarrea). Indicios de compuestos cianhídricos tóxicos, por lo que debe tratarse como tóxico; incomestible crudo y cocido debido a la acritud ardiente.','Ningún consumo. En caso de ingestión accidental y molestias: llamar a Tox Info Suisse 145 (24h), conservar restos/foto de los hongos. En caso de vómitos/diarrea persistentes, hidratarse y acudir al médico.',NULL,NULL,false),
('gymnopus_peronatus','fr','Chapeau jusqu''à 8-10 cm, jaune à brun rouge, ridé, hygrophane. Diagnostique : le goût brûlant-âcre/poivré après une brève mastication (signe d''alerte — test gustatif seulement en mâchant et recrachant). Base du pied nettement hérissée-feutrée (nom peronatus = ''botté''). Lames espacées, jaunâtres jeunes, brun rouge âgées. Nom actuel Collybiopsis peronata (Petersen 2021), encore le plus souvent listé comme Gymnopus peronatus dans les guides CH/D.','Irritation gastro-intestinale par des substances âcres irritantes (nausées, vomissements, diarrhée). Indices de composés cyanhydriques toxiques, à traiter donc comme toxique ; immangeable cru et cuit en raison de l''âcreté brûlante.','Pas de consommation. En cas d''ingestion accidentelle et de troubles : appeler Tox Info Suisse 145 (24h), conserver les restes/photo de champignons. En cas de vomissements/diarrhée persistants, s''hydrater et consulter un médecin.',NULL,NULL,false),
('gymnopus_peronatus','it','Cappello fino a 8-10 cm, da giallo a rosso-bruno, rugoso, igrofano. Diagnostico il sapore bruciante-acre/pepato dopo breve masticazione (segnale d''allarme — prova di sapore solo masticando e sputando). Base del gambo vistosamente irsuto-feltrata (nome peronatus = ''stivalato''). Lamelle rade, da giovani giallastre, da vecchie rosso-brune. Nome attuale Collybiopsis peronata (Petersen 2021), nelle guide CH/D per lo più ancora elencato come Gymnopus peronatus.','Irritazione gastrointestinale da sostanze irritanti acri (nausea, vomito, diarrea). Indizi di composti cianidrici tossici, quindi da trattare come tossico; immangiabile crudo e cotto a causa dell''acredine bruciante.','Nessun consumo. In caso di assunzione accidentale e disturbi: chiamare Tox Info Suisse 145 (24h), conservare resti/foto dei funghi. In caso di vomito/diarrea persistenti, idratarsi e consultare un medico.',NULL,NULL,false),
('gyromitra_gigas','en','Large, strongly brain-like convoluted false morel, ochre to yellow-brown, with a stout, broad, chambered, whitish stem. Spring mushroom on/at rotting conifer wood in mountainous regions. Hollow and chambered inside. Risk of confusion with the deadly spring false morel (Gyromitra esculenta) — to be avoided in general because of the gyromitrin risk.','Gyromitra syndrome: after 6–12 h nausea, vomiting, diarrhoea, abdominal pain, later liver damage, haemolysis, convulsions, in severe cases liver failure. MMH is carcinogenic and cumulative; cooking vapours are also toxic.','Call Tox Info Suisse 145 immediately. If consumption is suspected, do not wait — Gyromitra syndrome has a long latency. Do not pick, do not eat; also avoid inhaling the cooking vapours.',NULL,NULL,false),
('gyromitra_gigas','es','Bonete grande, fuertemente circunvolucionado como un cerebro, de ocre a pardo amarillo, con pie robusto, ancho, camerado y blanquecino. Hongo primaveral sobre madera de conífera en descomposición en zonas de montaña. Interior hueco y camerado. Riesgo de confusión con el bonete mortal (Gyromitra esculenta) — a evitar en general por el riesgo de giromitrina.','Síndrome giromítrico: tras 6–12 h náuseas, vómitos, diarrea, dolores abdominales, después daño hepático, hemólisis, convulsiones, en casos graves insuficiencia hepática. La MMH es cancerígena y acumulativa; los vapores de cocción también son tóxicos.','Llamar inmediatamente a Tox Info Suisse 145. Ante sospecha de consumo, no esperar — el síndrome giromítrico tiene una latencia larga. No recolectar, no comer; evitar también la inhalación de los vapores de cocción.',NULL,NULL,false),
('gyromitra_gigas','fr','Grande gyromitre fortement circonvolutionnée comme un cerveau, ocre à brun jaune, à pied robuste, large, chambré et blanchâtre. Champignon printanier sur bois de conifère pourrissant en montagne. Intérieur creux et chambré. Risque de confusion avec la gyromitre comestible mortelle (Gyromitra esculenta) — à éviter en général en raison du risque de gyromitrine.','Syndrome gyromitrien : après 6–12 h nausées, vomissements, diarrhée, douleurs abdominales, puis atteinte hépatique, hémolyse, convulsions, dans les cas graves insuffisance hépatique. La MMH est cancérogène et cumulative ; les vapeurs de cuisson sont également toxiques.','Appeler immédiatement Tox Info Suisse 145. En cas de suspicion de consommation, ne pas attendre — le syndrome gyromitrien a une longue latence. Ne pas cueillir, ne pas manger ; éviter aussi d''inhaler les vapeurs de cuisson.',NULL,NULL,false),
('gyromitra_gigas','it','Grande giromitra fortemente circonvoluta come un cervello, da ocra a bruno giallo, con gambo robusto, largo, camerato e biancastro. Fungo primaverile su legno di conifera marcescente in montagna. Interno cavo e camerato. Rischio di confusione con la giromitra mortale (Gyromitra esculenta) — da evitare in generale per il rischio di giromitrina.','Sindrome giromitrica: dopo 6–12 h nausea, vomito, diarrea, dolori addominali, poi danno epatico, emolisi, convulsioni, nei casi gravi insufficienza epatica. La MMH è cancerogena e cumulativa; anche i vapori di cottura sono tossici.','Chiamare immediatamente Tox Info Suisse 145. In caso di sospetto consumo non attendere — la sindrome giromitrica ha una lunga latenza. Non raccogliere, non mangiare; evitare anche l''inalazione dei vapori di cottura.',NULL,NULL,false),
('gyroporus_cyanescens','en','Cap straw-yellow to ochre-yellow, dry, rough-felty to coarsely scaly. Stem hollow/chambered (genus character of Gyroporus). Extremely rapid, intense cornflower-blue staining of flesh and tubes when bruised/cut (reliable feature). Spore print pale yellow (not olive). Rare and protected in Switzerland.',NULL,NULL,'Good edible with a nutty, porcini-like flavour; for braising, drying or freezing. The blue staining disappears on cooking. Owing to its rarity, collect only very sparingly or not at all.',NULL,false),
('gyroporus_cyanescens','es','Sombrero amarillo pajizo a amarillo ocre, seco, áspero-afieltrado a groseramente escamoso. Pie hueco/tabicado (carácter del género Gyroporus). Viraje al azul aciano extremadamente rápido e intenso de la carne y los tubos al herirse/cortarse (carácter seguro). Esporada amarillo pálido (no oliva). Raro y protegido en Suiza.',NULL,NULL,'Buen comestible con sabor a nuez parecido al boletus; para guisar, secar o congelar. El viraje azul desaparece al cocinar. Por su rareza, recolectar solo con gran moderación o no recolectar.',NULL,false),
('gyroporus_cyanescens','fr','Chapeau jaune paille à jaune ocre, sec, rugueux-feutré à grossièrement écailleux. Pied creux/cloisonné (caractère du genre Gyporus). Coloration bleu bleuet extrêmement rapide et intense de la chair et des tubes à la blessure/coupure (caractère sûr). Sporée jaune pâle (non olive). Rare et à protéger en Suisse.',NULL,NULL,'Bon comestible au goût noisette rappelant le cèpe; à braiser, sécher ou congeler. Le bleuissement disparaît à la cuisson. En raison de sa rareté, ne récolter qu''avec grande modération, voire pas du tout.',NULL,false),
('gyroporus_cyanescens','it','Cappello giallo paglierino-ocra, asciutto, rugoso-feltrato fino a grossolanamente squamoso. Gambo cavo/concamerato (carattere del genere Gyroporus). Viraggio al blu fiordaliso estremamente rapido e intenso della carne e dei tubuli alla rottura/taglio (carattere sicuro). Sporata giallo pallido (non oliva). In Svizzera raro e da proteggere.',NULL,NULL,'Buon commestibile dal sapore di nocciola simile al porcino; da brasare, essiccare o congelare. Il viraggio blu scompare con la cottura. Data la rarità, raccogliere solo con grande moderazione o per nulla.',NULL,false),
('helvella_acetabulum','en','Brown cup- to goblet-shaped fruit body whose strong whitish ribs run up from the short stem far onto the cup''s outer wall (''high-ribbed''). Inner surface brown, outer surface paler. Spring mushroom on calcareous soil. As a Helvella, a possible gyromitrin carrier — not a recommended edible.','Raw or insufficiently cooked, gastrointestinal upset possible; as a Helvella, not recommended for consumption.','If symptoms occur after ingestion, call Tox Info Suisse 145. As a precaution, do not eat.',NULL,NULL,false),
('helvella_acetabulum','es','Cuerpo fructífero pardo en forma de copa o cáliz, cuyas robustas costillas blanquecinas ascienden desde el pie corto hasta bien arriba en la pared externa de la copa (''de costillas altas''). Cara interna parda, cara externa más clara. Hongo primaveral en suelo calcáreo. Como Helvella, posible portador de giromitrina — no recomendado como comestible.','Crudo o insuficientemente cocido, posibles trastornos gastrointestinales; como Helvella, no recomendado para el consumo.','En caso de trastornos tras la ingestión, llamar a Tox Info Suisse 145. Por precaución, no consumir.',NULL,NULL,false),
('helvella_acetabulum','fr','Carpophore brun en forme de coupe ou de calice, dont les fortes côtes blanchâtres remontent depuis le pied court loin sur la paroi externe de la coupe (''côtes hautes''). Face interne brune, face externe plus claire. Champignon printanier sur sol calcaire. En tant que Helvella, possible porteur de gyromitrine — non recommandé comme comestible.','Crus ou insuffisamment cuits, troubles gastro-intestinaux possibles; en tant que Helvella, non recommandé pour la consommation.','En cas de troubles après ingestion, appeler Tox Info Suisse 145. Par précaution, ne pas consommer.',NULL,NULL,false),
('helvella_acetabulum','it','Corpo fruttifero bruno a forma di coppa o calice, le cui robuste costole biancastre risalgono dal gambo corto fin sulla parete esterna della coppa (''a costole alte''). Interno bruno, esterno più chiaro. Fungo primaverile su terreno calcareo. In quanto Helvella, possibile portatore di giromitrina — non consigliato come commestibile.','Crudo o cotto in modo insufficiente, possibili disturbi gastrointestinali; in quanto Helvella, non consigliato per il consumo.','In caso di disturbi dopo l''ingestione chiamare Tox Info Suisse 145. Per precauzione non consumare.',NULL,NULL,false),
('helvella_crispa','en','Cream-white to ivory cap, irregularly saddle-shaped and lobed, on a whitish stem conspicuously deeply furrowed/chambered. Autumn mushroom at forest and path edges. Inside hollow-chambered. Toxic raw, contains traces of gyromitrin.','Raw or insufficiently cooked, gastrointestinal upset (nausea, vomiting, diarrhoea); owing to the gyromitrin content, consumption is in principle to be discouraged.','If symptoms occur after ingestion, call Tox Info Suisse 145. By modern assessment, do not eat (gyromitrin risk).',NULL,NULL,false),
('helvella_crispa','es','Sombrero blanco crema a marfil, irregularmente lobulado en forma de silla de montar, sobre un pie blanquecino marcadamente surcado/acanalado en profundidad. Hongo otoñal en bordes de bosques y caminos. Interior hueco-acanalado. Tóxico en crudo, contiene trazas de giromitrina.','Crudo o insuficientemente cocido, trastornos gastrointestinales (náuseas, vómitos, diarrea); debido al contenido de giromitrina, en principio se desaconseja su consumo.','En caso de trastornos tras la ingestión, llamar a Tox Info Suisse 145. Según la valoración moderna, no consumir (riesgo de giromitrina).',NULL,NULL,false),
('helvella_crispa','fr','Chapeau blanc crème à ivoire, irrégulièrement lobé en forme de selle, sur un pied blanchâtre nettement sillonné/alvéolé en profondeur. Champignon d''automne en bordure de forêts et de chemins. Intérieur creux-alvéolé. Toxique cru, contient des traces de gyromitrine.','Cru ou insuffisamment cuit, troubles gastro-intestinaux (nausées, vomissements, diarrhée); en raison de la teneur en gyromitrine, sa consommation est en principe déconseillée.','En cas de troubles après ingestion, appeler Tox Info Suisse 145. Selon l''évaluation moderne, ne pas consommer (risque de gyromitrine).',NULL,NULL,false),
('helvella_crispa','it','Cappello bianco crema-avorio, lobato irregolarmente a forma di sella, su un gambo biancastro vistosamente solcato/concamerato in profondità. Fungo autunnale ai margini di boschi e sentieri. Internamente cavo-concamerato. Tossico da crudo, contiene tracce di giromitrina.','Crudo o cotto in modo insufficiente, disturbi gastrointestinali (nausea, vomito, diarrea); a causa del contenuto di giromitrina se ne sconsiglia in linea di principio il consumo.','In caso di disturbi dopo l''ingestione chiamare Tox Info Suisse 145. Secondo la valutazione moderna non consumare (rischio giromitrina).',NULL,NULL,false),
('hydnellum_ferrugineum','en','Top-shaped fruit bodies, 3-10 cm, velvety surface white-pink when young and occasionally with red guttation droplets, rust-brown with age. Underside with spines. Very similar to H. peckii, but flesh not acrid, rather mild-mealy; often on sandy pine soil, frequently fusing with embedded needles/twigs. The corky-tough flesh makes it inedible. Non-toxic.',NULL,NULL,NULL,NULL,false),
('hydnellum_ferrugineum','es','Cuerpos fructíferos en forma de peonza, 3-10 cm, superficie aterciopelada blanco-rosa de joven y ocasionalmente con gotas de gutación rojas, pardo herrumbre con la edad. Cara inferior con aguijones. Muy similar a H. peckii, pero carne no picante, más bien suave-harinosa; a menudo en suelo arenoso de pinos, fusionándose con frecuencia con acículas/ramitas englobadas. La carne correosa-corchosa lo hace incomestible. No tóxico.',NULL,NULL,NULL,NULL,false),
('hydnellum_ferrugineum','fr','Carpophores en forme de toupie, 3-10 cm, surface veloutée blanc-rose jeune et parfois avec des gouttes de guttation rouges, brun rouille avec l''âge. Face inférieure à aiguillons. Très semblable à H. peckii, mais chair non âcre, plutôt douce-farineuse; souvent sur sol sableux de pins, fusionne fréquemment avec des aiguilles/brindilles incrustées. La chair coriace-liégeuse le rend immangeable. Non toxique.',NULL,NULL,NULL,NULL,false),
('hydnellum_ferrugineum','it','Corpi fruttiferi a forma di trottola, 3-10 cm, superficie vellutata bianco-rosa da giovane e talvolta con gocce di guttazione rosse, bruno ruggine con l''età. Faccia inferiore con aculei. Molto simile a H. peckii, ma carne non piccante, piuttosto dolce-farinosa; spesso su terreno sabbioso di pini, si fonde frequentemente con aghi/rametti inglobati. La carne coriacea-sugherosa lo rende immangiabile. Non tossico.',NULL,NULL,NULL,NULL,false),
('hydnellum_peckii','en','Striking for its fruit bodies that are white when young and, in moist weather, exude bright blood-red guttation droplets (nickname ''Bleeding Tooth''). Cap underside with spines instead of gills. Corky-tough, fibrous flesh. Non-toxic, but completely inedible due to an intense, persistent acridity/bitterness. Confusable with other Hydnellum tooth fungi (all inedible).',NULL,NULL,NULL,NULL,false),
('hydnellum_peckii','es','Llamativo por sus cuerpos fructíferos blancos cuando son jóvenes, que con tiempo húmedo exudan vivas gotas de gutación rojo sangre (apodo ''Bleeding Tooth''). Cara inferior del sombrero con aguijones en lugar de láminas. Carne corchosa-correosa, fibrosa. No tóxico, pero totalmente incomestible debido a un picor/amargor intenso y persistente. Confundible con otros Hydnellum (todos incomestibles).',NULL,NULL,NULL,NULL,false),
('hydnellum_peckii','fr','Remarquable par ses carpophores blancs lorsqu''ils sont jeunes, qui exsudent par temps humide des gouttes de guttation rouge sang éclatantes (surnom ''Bleeding Tooth''). Face inférieure du chapeau à aiguillons au lieu de lamelles. Chair liégeuse-coriace, fibreuse. Non toxique, mais totalement immangeable en raison d''une âcreté/amertume intense et persistante. Confusion possible avec d''autres Hydnellum (tous immangeables).',NULL,NULL,NULL,NULL,false),
('hydnellum_peckii','it','Notevole per i corpi fruttiferi bianchi da giovani, che con tempo umido essudano vivaci gocce di guttazione rosso sangue (soprannome ''Bleeding Tooth''). Faccia inferiore del cappello con aculei invece di lamelle. Carne sugherosa-coriacea, fibrosa. Non tossico, ma del tutto immangiabile per un''intensa e persistente piccantezza/amarezza. Confondibile con altri Hydnellum (tutti immangiabili).',NULL,NULL,NULL,NULL,false),
('hydnum_albidum','en','The genus Hydnum (hedgehog mushrooms) is unmistakably distinguished from dangerous gilled mushrooms by the soft, easily breaking spines on the cap underside. H. albidum is pure white to cream, distinctly paler and usually smaller than the wood hedgehog (H. repandum), yellows when pressed/bruised and has smaller spores. The spines run a short way down the stem and rub off easily. Within the hedgehog group there are no deadly or toxic lookalikes.',NULL,NULL,'Use only young, firm specimens; older ones turn bitter. Hedgehog mushrooms are hard to digest raw/slightly scratchy and should always be well cooked (at least 15 min frying/braising). A slight bitterness can be reduced by brief blanching. Good for mixing with other mushrooms, keeps a firm, biteable texture.',NULL,false),
('hydnum_albidum','es','El género Hydnum (gamuzas/lenguas de vaca) se distingue inequívocamente de los peligrosos hongos laminados por los aguijones blandos y fácilmente quebradizos en la cara inferior del sombrero. H. albidum es blanco puro a crema, claramente más claro y normalmente más pequeño que la lengua de vaca (H. repandum), amarillea a la presión/herida y tiene esporas más pequeñas. Los aguijones descienden brevemente por el pie y se desprenden fácilmente al frotar. Dentro del grupo de las gamuzas no existe ningún sosia mortal o tóxico.',NULL,NULL,'Usar solo ejemplares jóvenes y firmes; los más viejos se vuelven amargos. Las gamuzas son crudas difíciles de digerir/algo ásperas y deben cocinarse siempre bien (al menos 15 min a la sartén/guisadas). Un ligero amargor puede reducirse con un breve escaldado. Buenas para mezclar con otros hongos, mantiene una consistencia firme al morder.',NULL,false),
('hydnum_albidum','fr','Le genre Hydnum (hydnes) se distingue sans équivoque des dangereux champignons à lamelles par ses aiguillons mous et facilement cassants sur le dessous du chapeau. H. albidum est blanc pur à crème, nettement plus clair et généralement plus petit que le pied-de-mouton (H. repandum), jaunit à la pression/blessure et a des spores plus petites. Les aiguillons descendent brièvement sur le pied et se laissent facilement frotter. Au sein du groupe des hydnes, il n''existe aucun sosie mortel ou toxique.',NULL,NULL,'N''utiliser que des exemplaires jeunes et fermes; les plus âgés deviennent amers. Les hydnes sont difficiles à digérer crus/légèrement râpeux et doivent toujours être bien cuits (au moins 15 min de cuisson à la poêle/braisés). Une légère amertume peut être réduite par un bref blanchiment. Bons à mélanger avec d''autres champignons, garde une consistance ferme sous la dent.',NULL,false),
('hydnum_albidum','it','Il genere Hydnum (idni) si distingue inequivocabilmente dai pericolosi funghi a lamelle per gli aculei molli e facilmente fragili sulla faccia inferiore del cappello. H. albidum è bianco puro a crema, decisamente più chiaro e di solito più piccolo dello steccherino dorato (H. repandum), ingiallisce alla pressione/rottura e ha spore più piccole. Gli aculei scendono brevemente sul gambo e si lasciano facilmente strofinare via. All''interno del gruppo degli idni non esiste alcun sosia mortale o tossico.',NULL,NULL,'Utilizzare solo esemplari giovani e sodi; quelli più vecchi diventano amari. Gli idni sono crudi difficili da digerire/leggermente raspanti e vanno sempre cotti bene (almeno 15 min in padella/brasati). Una leggera amarezza può essere ridotta con una breve sbollentatura. Buoni da mescolare con altri funghi, mantiene una consistenza soda al morso.',NULL,false),
('hygrocybe_coccinea','en','Bright cherry- to scarlet-red convex cap (2-5 cm), broadly attached gills red with yellowish edges, red stem. Does NOT turn black (difference from Hygrocybe conica). Confused mainly with the crimson waxcap (H. punicea). Grows in nutrient-poor meadows.',NULL,NULL,NULL,NULL,false),
('hygrocybe_coccinea','es','Sombrero convexo rojo cereza a escarlata brillante (2-5 cm), láminas anchamente adheridas rojas con borde amarillento, pie rojo. NO ennegrece (diferencia con Hygrocybe conica). Confusión sobre todo con el higróforo escarlata (H. punicea). Crece en prados pobres.',NULL,NULL,NULL,NULL,false),
('hygrocybe_coccinea','fr','Chapeau convexe rouge cerise à écarlate brillant (2-5 cm), lamelles largement adnées rouges à liserées de jaunâtre, pied rouge. Ne noircit PAS (différence avec Hygrocybe conica). Confusion surtout avec l''hygrophore ponceau (H. punicea). Pousse dans les prairies maigres.',NULL,NULL,NULL,NULL,false),
('hygrocybe_coccinea','it','Cappello convesso rosso ciliegia-scarlatto brillante (2-5 cm), lamelle largamente adnate rosse a bordo giallastro, gambo rosso. NON annerisce (differenza con Hygrocybe conica). Confusione soprattutto con l''igroforo rosso sangue (H. punicea). Cresce nei prati magri.',NULL,NULL,NULL,NULL,false),
('hygrocybe_conica','en','Conical, pointed-umbonate cap, red-orange to yellow (2-6 cm), which rapidly and completely blackens on touch and with age (the whole fruit body – cap, gills, stem). The rapid blackening is the decisive feature. Grows in nutrient-poor meadows.','Gastrointestinal upset (nausea, vomiting, diarrhoea), especially in larger quantities; listed in the literature as mildly toxic/suspect.','Avoid consumption. If symptoms occur after eating: call Tox Info Suisse 145 (from abroad +41 44 251 51 51), keep mushroom remains/vomit for identification, drink plenty.',NULL,NULL,false),
('hygrocybe_conica','es','Sombrero cónico, puntiagudo-mamelonado, rojo-anaranjado a amarillo (2-6 cm), que ennegrece rápida y completamente al tacto y con la edad (todo el carpóforo – sombrero, láminas, pie). El ennegrecimiento rápido es el carácter decisivo. Crece en prados pobres.','Trastornos gastrointestinales (náuseas, vómitos, diarrea), sobre todo en grandes cantidades; en la literatura figura como débilmente tóxico/sospechoso.','Evitar el consumo. En caso de trastornos tras la ingestión: llamar a Tox Info Suisse 145 (desde el extranjero +41 44 251 51 51), conservar los restos de hongos/vómito para la identificación, beber abundantemente.',NULL,NULL,false),
('hygrocybe_conica','fr','Chapeau conique pointu-mamelonné rouge-orange à jaune (2-6 cm), qui noircit rapidement et complètement au toucher et avec l''âge (tout le carpophore – chapeau, lamelles, pied). Le noircissement rapide est le caractère décisif. Pousse dans les prairies maigres.','Troubles gastro-intestinaux (nausées, vomissements, diarrhée), surtout en grandes quantités; mentionné dans la littérature comme faiblement toxique/suspect.','Éviter la consommation. En cas de troubles après ingestion: appeler Tox Info Suisse 145 (depuis l''étranger +41 44 251 51 51), conserver les restes de champignons/vomissures pour identification, boire abondamment.',NULL,NULL,false),
('hygrocybe_conica','it','Cappello conico, appuntito-umbonato, rosso-arancio a giallo (2-6 cm), che annerisce rapidamente e completamente al tatto e con l''età (tutto il carpoforo – cappello, lamelle, gambo). L''annerimento rapido è il carattere decisivo. Cresce nei prati magri.','Disturbi gastrointestinali (nausea, vomito, diarrea), soprattutto in grandi quantità; in letteratura indicato come debolmente tossico/sospetto.','Evitare il consumo. In caso di disturbi dopo l''ingestione: chiamare Tox Info Suisse 145 (dall''estero +41 44 251 51 51), conservare i resti dei funghi/vomito per l''identificazione, bere molto.',NULL,NULL,false),
('hygrophorus_eburneus','en','Pure white, strongly slimy-sticky cap (2-6 cm), thick broadly decurrent white gills and a slimy white stem. Grows exclusively under beeches on limestone in late autumn. The slimy surface and beech association are important features.',NULL,NULL,'Use only when young; because of the slime layer, briefly parboil/de-slime before cooking, then fry or use in a mixed dish. Avoid raw.',NULL,false),
('hygrophorus_eburneus','es','Sombrero blanco puro, fuertemente viscoso-pegajoso (2-6 cm), gruesas láminas blancas ampliamente decurrentes y pie blanco viscoso. Crece exclusivamente bajo hayas sobre caliza a finales de otoño. La superficie viscosa y la asociación con el haya son caracteres importantes.',NULL,NULL,'Usar solo joven; debido a la capa viscosa, escaldar brevemente/desmucilaginar antes de cocinar, luego saltear o en mezcla. Evitar crudo.',NULL,false),
('hygrophorus_eburneus','fr','Chapeau blanc pur, fortement visqueux-collant (2-6 cm), épaisses lamelles blanches largement décurrentes et pied blanc visqueux. Pousse exclusivement sous les hêtres sur calcaire en fin d''automne. Surface gluante et lien avec le hêtre sont des caractères importants.',NULL,NULL,'N''utiliser que jeune; en raison de la couche visqueuse, ébouillanter brièvement/démuciler avant cuisson, puis poêler ou en mélange. Éviter cru.',NULL,false),
('hygrophorus_eburneus','it','Cappello bianco puro, fortemente vischioso-appiccicoso (2-6 cm), spesse lamelle bianche largamente decorrenti e gambo bianco vischioso. Cresce esclusivamente sotto i faggi su calcare in tardo autunno. Superficie viscida e legame con il faggio sono caratteri importanti.',NULL,NULL,'Utilizzare solo da giovane; a causa dello strato vischioso, sbollentare brevemente/de-mucillaginare prima della cottura, poi rosolare o in misto. Evitare crudo.',NULL,false),
('hygrophorus_hypothejus','en','Slimy olive-grey-brown cap (3-6 cm) with a yellowish margin, yellow to saffron-yellow decurrent gills, yellowish slimy stem. Appears very late, only after the first night frosts, under pines. The late season and pine association are diagnostic.',NULL,NULL,'Good edible; remove the cap slime before frying or parboil briefly. Good for mixed mushroom dishes; only young firm specimens.',NULL,false),
('hygrophorus_hypothejus','es','Sombrero viscoso pardo-gris oliváceo (3-6 cm) con margen amarillento, láminas decurrentes amarillas a amarillo azafrán, pie amarillento viscoso. Aparece muy tarde, solo tras las primeras heladas nocturnas, bajo los pinos. La estación tardía y la asociación con los pinos son diagnósticas.',NULL,NULL,'Buen comestible; retirar el moco del sombrero antes de saltear o escaldar brevemente. Bueno para platos de hongos mixtos; solo ejemplares jóvenes firmes.',NULL,false),
('hygrophorus_hypothejus','fr','Chapeau visqueux brun-gris olivâtre (3-6 cm) à marge jaunâtre, lamelles décurrentes jaunes à jaune safran, pied jaunâtre visqueux. Apparaît très tard, seulement après les premières gelées nocturnes, sous les pins. Saison tardive et lien avec les pins sont diagnostiques.',NULL,NULL,'Bon comestible; retirer le mucus du chapeau avant de poêler ou ébouillanter brièvement. Bon pour les plats de champignons mélangés; seulement de jeunes exemplaires fermes.',NULL,false),
('hygrophorus_hypothejus','it','Cappello vischioso bruno-grigio olivastro (3-6 cm) con margine giallastro, lamelle decorrenti gialle a giallo zafferano, gambo giallastro vischioso. Compare molto tardi, solo dopo le prime gelate notturne, sotto i pini. La stagione tardiva e il legame con i pini sono diagnostici.',NULL,NULL,'Buon commestibile; togliere il muco del cappello prima di rosolare o sbollentare brevemente. Buono per piatti di funghi misti; solo giovani esemplari sodi.',NULL,false),
('hypholoma_capnoides','en','In clusters on coniferous wood, ochre-yellow to honey-brown cap. Gills whitish/pale when young, then ASH-GREY to grey-violet — NEVER greenish (distinction from the toxic sulphur tuft H. fasciculare) and NEVER rust-brown with a membranous ring (distinction from the DEADLY funeral bell Galerina marginata). Mild-tasting. CAUTION: only for the very experienced — confusion with Galerina marginata (amanitin) has already been fatal. Toxic raw, edible only when cooked through.','Raw or insufficiently cooked: gastrointestinal complaints due to traces of cyanide. If confused with Galerina marginata: amatoxin-induced liver failure (life-threatening) — when in doubt, NEVER eat.','If confusion with the funeral bell (Galerina marginata) or persistent complaints are suspected, call Tox Info Suisse 145 IMMEDIATELY. Keep mushroom remains/spore print for emergency mycologists. If latency >6h, consider death-cap/Galerina syndrome.','Use only young and with certain identification. Toxic raw (traces of cyanide) — cook through for at least 15-20 min. Stems tough, use only the caps. Good for frying/braising, mild nutty aroma.',NULL,false),
('hypholoma_capnoides','es','En grupos sobre madera de coníferas, sombrero de amarillo ocre a pardo miel. Láminas blanquecinas/pálidas de joven, luego GRIS CENIZA a gris violáceo — NUNCA verdosas (distinción del tóxico hifoloma de penacho H. fasciculare) y NUNCA pardo herrumbre con anillo membranoso (distinción de la MORTAL Galerina marginata). De sabor suave. ATENCIÓN: solo para muy expertos — la confusión con Galerina marginata (amanitina) ya ha sido mortal. Tóxico crudo, comestible solo bien cocinado.','Crudo o cocinado insuficientemente: molestias gastrointestinales por trazas de cianuro. En caso de confusión con Galerina marginata: insuficiencia hepática por amatoxinas (peligro de muerte) — en caso de duda, NUNCA comer.','Si se sospecha confusión con la Galerina marginata o molestias persistentes, llamar INMEDIATAMENTE a Tox Info Suisse 145. Conservar los restos de setas/la esporada para los micólogos de emergencia. Con latencia >6h, pensar en el síndrome faloidiano/de Galerina.','Usar solo joven y con identificación segura. Tóxico crudo (trazas de cianuro) — cocinar bien al menos 15-20 min. Pies correosos, usar solo los sombreros. Bueno para freír/estofar, aroma suave a nuez.',NULL,false),
('hypholoma_capnoides','fr','En touffes sur bois de conifères, chapeau jaune ocre à brun miel. Lamelles blanchâtres/pâles jeunes, puis GRIS CENDRÉ à gris violacé — JAMAIS verdâtres (distinction de l''hypholome en touffe toxique H. fasciculare) et JAMAIS brun rouille avec anneau membraneux (distinction de la galère marginée MORTELLE Galerina marginata). Saveur douce. ATTENTION: réservé aux personnes très expérimentées — la confusion avec Galerina marginata (amanitine) a déjà été mortelle. Toxique cru, comestible seulement bien cuit.','Cru ou insuffisamment cuit: troubles gastro-intestinaux dus à des traces de cyanure. En cas de confusion avec Galerina marginata: insuffisance hépatique due aux amatoxines (danger de mort) — en cas de doute, NE JAMAIS manger.','En cas de suspicion de confusion avec la galère marginée (Galerina marginata) ou de troubles persistants, appeler IMMÉDIATEMENT Tox Info Suisse 145. Conserver les restes de champignons/la sporée pour les mycologues d''urgence. En cas de latence >6h, penser au syndrome phalloïdien/Galerina.','Utiliser uniquement jeune et avec une identification sûre. Toxique cru (traces de cyanure) — bien cuire au moins 15-20 min. Pieds coriaces, n''utiliser que les chapeaux. Bon à rôtir/braiser, arôme doux et noisette.',NULL,false),
('hypholoma_capnoides','it','A ciuffi su legno di conifere, cappello dal giallo ocra al bruno miele. Lamelle biancastre/pallide da giovani, poi GRIGIO CENERE fino a grigio-violaceo — MAI verdastre (distinzione dal tossico falso chiodino H. fasciculare) e MAI bruno ruggine con anello membranoso (distinzione dalla MORTALE Galerina marginata). Sapore mite. ATTENZIONE: solo per persone molto esperte — la confusione con Galerina marginata (amanitina) è già stata mortale. Tossico da crudo, commestibile solo ben cotto.','Crudo o cotto insufficientemente: disturbi gastrointestinali dovuti a tracce di cianuro. In caso di confusione con Galerina marginata: insufficienza epatica dovuta alle amatossine (pericolo di vita) — in caso di incertezza, NON mangiare MAI.','In caso di sospetta confusione con la Galerina marginata o di disturbi persistenti chiamare IMMEDIATAMENTE Tox Info Suisse 145. Conservare i resti dei funghi/la sporata per i micologi d''emergenza. In caso di latenza >6h, pensare alla sindrome falloidea/da Galerina.','Usare solo da giovane e con identificazione sicura. Tossico da crudo (tracce di cianuro) — cuocere bene per almeno 15-20 min. Gambi coriacei, usare solo i cappelli. Buono da arrostire/brasare, aroma mite e nocciolato.',NULL,false),
('hypholoma_lateritium','en','In clusters on hardwood, vivid brick-red to reddish-brown cap with a paler yellowish margin and whitish veil flecks. Gills yellowish when young, then olive-grey-brown. Stem yellow at top, reddish-brown downwards. In Central Europe avoided due to its bitter taste and gastrointestinal toxic effect. Confusable with the edible H. capnoides (mild, coniferous wood) and the toxic H. fasciculare (greenish, very bitter).','Gastrointestinal syndrome with nausea, vomiting and diarrhoea; irritation of the gastrointestinal mucous membranes. Haemolysins break down red blood cells.','In case of complaints, call Tox Info Suisse 145, keep mushroom remains. Provide fluids; in case of persistent vomiting/diarrhoea, seek medical clarification.',NULL,NULL,false),
('hypholoma_lateritium','es','En grupos sobre madera de frondosas, sombrero rojo ladrillo intenso a pardo rojizo con margen más claro amarillento y escamillas blanquecinas del velo. Láminas amarillentas de joven, luego pardo oliva-grisáceo. Pie amarillo arriba, pardo rojizo hacia abajo. En Europa Central se evita debido a su sabor amargo y su efecto tóxico gastrointestinal. Confundible con el comestible H. capnoides (suave, madera de coníferas) y el tóxico H. fasciculare (verdoso, muy amargo).','Síndrome gastrointestinal con náuseas, vómitos y diarrea; irritación de las mucosas gastrointestinales. Las hemolisinas destruyen los glóbulos rojos.','En caso de molestias, llamar a Tox Info Suisse 145, conservar los restos de setas. Aportar líquidos; en caso de vómitos/diarrea persistentes, consultar a un médico.',NULL,NULL,false),
('hypholoma_lateritium','fr','En touffes sur bois de feuillus, chapeau rouge brique vif à brun rougeâtre avec marge plus claire jaunâtre et flocons de voile blanchâtres. Lamelles jaunâtres jeunes, puis brun olive-grisâtre. Pied jaune en haut, brun rougeâtre vers le bas. En Europe centrale, évité en raison de son goût amer et de son effet toxique gastro-intestinal. Confusion possible avec le comestible H. capnoides (doux, bois de conifères) et le toxique H. fasciculare (verdâtre, très amer).','Syndrome gastro-intestinal avec nausées, vomissements et diarrhée; irritation des muqueuses gastro-intestinales. Les hémolysines détruisent les globules rouges.','En cas de troubles, appeler Tox Info Suisse 145, conserver les restes de champignons. Apporter des liquides, en cas de vomissements/diarrhée persistants, consulter un médecin.',NULL,NULL,false),
('hypholoma_lateritium','it','A ciuffi su legno di latifoglie, cappello rosso mattone vivo fino al bruno rossastro con margine più chiaro giallastro e fioccosità del velo biancastre. Lamelle giallastre da giovani, poi bruno-grigio olivastro. Gambo giallo in alto, bruno rossastro verso il basso. In Europa centrale è evitato a causa del sapore amaro e dell''effetto tossico gastrointestinale. Confondibile con il commestibile H. capnoides (mite, legno di conifere) e il tossico H. fasciculare (verdastro, molto amaro).','Sindrome gastrointestinale con nausea, vomito e diarrea; irritazione delle mucose gastrointestinali. Le emolisine distruggono i globuli rossi.','In caso di disturbi chiamare Tox Info Suisse 145, conservare i resti dei funghi. Reintegrare i liquidi, in caso di vomito/diarrea persistenti consultare un medico.',NULL,NULL,false),
('infundibulicybe_gibba','en','Funnel-shaped, thin-fleshed cap with a small umbo in the centre, ochre-brown to flesh-brown. Gills white and distinctly decurrent. Stem pale, often with a whitish basal felt. CAUTION: can be confused with small white muscarine-containing Clitocybe species (C. rivulosa, C. dealbata) — but these are pure white and smaller. Edible only when cooked through.',NULL,NULL,'Use only young and well cooked through (min. 15-20 min). Remove the tough stem, use only the caps. Inedible raw. Good for drying and as a seasoning mushroom.',NULL,false),
('infundibulicybe_gibba','es','Sombrero en forma de embudo, de carne fina, con un pequeño mamelón en el centro, de pardo ocre a pardo carne. Láminas blancas y claramente decurrentes. Pie claro, a menudo con fieltro blanquecino en la base. ATENCIÓN: puede confundirse con pequeñas especies blancas de Clitocybe que contienen muscarina (C. rivulosa, C. dealbata) — pero estas son de un blanco puro y más pequeñas. Comestible solo bien cocinado.',NULL,NULL,'Usar solo joven y bien cocinado (mín. 15-20 min). Retirar el pie correoso, usar solo los sombreros. No comestible crudo. Bueno para secar y como seta condimentaria.',NULL,false),
('infundibulicybe_gibba','fr','Chapeau en forme d''entonnoir, à chair mince, avec un petit mamelon au centre, ocre-brun à brun chair. Lamelles blanches et nettement décurrentes. Pied clair, souvent avec un feutrage blanchâtre à la base. ATTENTION: peut être confondu avec de petites espèces de Clitocybe blanches contenant de la muscarine (C. rivulosa, C. dealbata) — mais celles-ci sont d''un blanc pur et plus petites. Comestible seulement bien cuit.',NULL,NULL,'Utiliser uniquement jeune et bien cuit (min. 15-20 min). Retirer le pied coriace, n''utiliser que les chapeaux. Non comestible cru. Bon à sécher et comme champignon d''assaisonnement.',NULL,false),
('infundibulicybe_gibba','it','Cappello a forma di imbuto, a carne sottile, con un piccolo umbone al centro, dall''ocra-bruno al bruno carne. Lamelle bianche e nettamente decorrenti. Gambo chiaro, spesso con feltro biancastro alla base. ATTENZIONE: può essere confuso con piccole specie di Clitocybe bianche contenenti muscarina (C. rivulosa, C. dealbata) — ma queste sono di un bianco puro e più piccole. Commestibile solo ben cotto.',NULL,NULL,'Usare solo da giovane e ben cotto (min. 15-20 min). Rimuovere il gambo coriaceo, usare solo i cappelli. Non commestibile da crudo. Buono da essiccare e come fungo aromatizzante.',NULL,false),
('inonotus_obliquus','en','Black, cracked-charred-looking, hard growths (sclerotium/conk) on the trunk of living birches; interior rust-brown and corky. Not a classic capped mushroom. Stone-hard, woody — is NOT eaten as an edible mushroom, used only as a medicinal mushroom for tea/infusion/extract. Caution: contains plenty of oxalate (risk of oxalate nephropathy with excessive tea consumption). Confusion possible with tree cancer/burls or charred wood.','Not edible raw or as a table mushroom (stone-hard, woody). With excessive or long-term consumption of chaga-containing teas/extracts: risk of oxalate nephropathy (kidney damage), especially with pre-existing kidney disease; possible interaction with blood thinners and blood-sugar-lowering medication.','If kidney-related complaints are suspected after excessive chaga consumption (flank pain, reduced urine output), seek medical evaluation. In case of poisoning/emergency Tox Info Suisse: 145 (24 h, free). Do not eat chaga as a food mushroom.',NULL,NULL,false),
('inonotus_obliquus','es','Excrecencias negras, de aspecto agrietado-carbonizado, duras (esclerocio/conk) en el tronco de abedules vivos; interior pardo herrumbre y corchoso. No es una seta clásica con sombrero. Dura como la piedra, leñosa — NO se come como seta comestible, se usa solo como hongo medicinal para té/infusión/extracto. Atención: contiene mucho oxalato (riesgo de nefropatía por oxalatos con consumo excesivo de té). Posible confusión con cáncer del árbol/nudos o madera carbonizada.','No comestible crudo ni como seta de mesa (dura como la piedra, leñosa). Con un consumo excesivo o prolongado de tés/extractos con chaga: riesgo de nefropatía por oxalatos (daño renal), sobre todo con enfermedad renal preexistente; posible interacción con anticoagulantes e hipoglucemiantes.','Si se sospechan molestias renales tras un consumo excesivo de chaga (dolor en el costado, reducción de la cantidad de orina), consultar a un médico. En caso de intoxicación/emergencia Tox Info Suisse: 145 (24 h, gratuito). No comer el chaga como seta alimentaria.',NULL,NULL,false),
('inonotus_obliquus','fr','Excroissances noires, d''aspect craquelé-carbonisé, dures (sclérote/conk) sur le tronc de bouleaux vivants; intérieur brun-rouille liégeux. Pas un champignon à chapeau classique. Dur comme la pierre, ligneux — N''EST PAS consommé comme champignon comestible, utilisé uniquement comme champignon médicinal pour tisane/infusion/extrait. Attention: contient beaucoup d''oxalate (risque de néphropathie oxalique en cas de consommation excessive de tisane). Confusion possible avec un cancer de l''arbre/loupes ou du bois carbonisé.','Non comestible cru ou comme champignon de table (dur comme la pierre, ligneux). En cas de consommation excessive ou prolongée de tisanes/extraits contenant du chaga: risque de néphropathie oxalique (atteinte rénale), surtout en cas de maladie rénale préexistante; interaction possible avec les anticoagulants et les hypoglycémiants.','En cas de suspicion de troubles rénaux après une consommation excessive de chaga (douleur au flanc, diminution de la quantité d''urine), consulter un médecin. En cas d''intoxication/urgence Tox Info Suisse: 145 (24 h, gratuit). Ne pas manger le chaga comme champignon alimentaire.',NULL,NULL,false),
('inonotus_obliquus','it','Escrescenze nere, dall''aspetto screpolato-carbonizzato, dure (sclerozio/conk) sul tronco di betulle vive; interno bruno-ruggine sugheroso. Non è un classico fungo a cappello. Duro come la pietra, legnoso — NON viene mangiato come fungo commestibile, usato solo come fungo medicinale per tè/infuso/estratto. Attenzione: contiene molto ossalato (rischio di nefropatia da ossalati in caso di consumo eccessivo di tè). Possibile confusione con cancro dell''albero/nodi o legno carbonizzato.','Non commestibile da crudo o come fungo da tavola (duro come la pietra, legnoso). In caso di consumo eccessivo o prolungato di tè/estratti a base di chaga: rischio di nefropatia da ossalati (danno renale), soprattutto in caso di malattia renale preesistente; possibile interazione con anticoagulanti e ipoglicemizzanti.','In caso di sospetti disturbi renali dopo un consumo eccessivo di chaga (dolore al fianco, riduzione della quantità di urina) consultare un medico. In caso di avvelenamento/emergenza Tox Info Suisse: 145 (24 h, gratuito). Non mangiare il chaga come fungo alimentare.',NULL,NULL,false),
('lactarius_blennius','en','Cap greasy-slimy, grey-green to olive-grey, often with concentrically arranged darker droplet-like spots. Under beech. Milk white, drying grey-green to grey in air, very acrid. The acridity and the grey-drying latex are diagnostic.','Raw or insufficiently cooked, gastrointestinal complaints: nausea, vomiting, diarrhoea (gastrointestinal irritant syndrome due to acrid milk).','If symptoms occur after consumption: call Tox Info Suisse 145. Keep mushroom remains/vomit for identification. No self-induced measure without medical advice.',NULL,NULL,false),
('lactarius_blennius','es','Sombrero grasiento-viscoso, de verde grisáceo a gris oliva, a menudo con manchas más oscuras en forma de gotas dispuestas concéntricamente. Bajo el haya. Leche blanca, que al aire se seca de verde grisáceo a gris, muy picante. El sabor picante y el látex que se seca gris son diagnósticos.','Crudo o cocinado insuficientemente, molestias gastrointestinales: náuseas, vómitos, diarrea (síndrome irritativo gastrointestinal por la leche picante).','En caso de molestias tras el consumo: llamar a Tox Info Suisse 145. Conservar los restos de setas/el vómito para la identificación. Ninguna medida autoinducida sin consejo médico.',NULL,NULL,false),
('lactarius_blennius','fr','Chapeau gras-visqueux, gris-vert à gris olive, souvent avec des taches en gouttelettes plus foncées disposées concentriquement. Sous le hêtre. Lait blanc, séchant à l''air en gris-vert à gris, très âcre. L''âcreté et le latex séchant en gris sont diagnostiques.','Cru ou insuffisamment cuit, troubles gastro-intestinaux: nausées, vomissements, diarrhée (syndrome d''irritation gastro-intestinale dû au lait âcre).','En cas de troubles après consommation: appeler Tox Info Suisse 145. Conserver les restes de champignons/vomissures pour identification. Aucune mesure auto-induite sans avis médical.',NULL,NULL,false),
('lactarius_blennius','it','Cappello viscido-mucillaginoso, dal grigio-verde al grigio oliva, spesso con macchie a gocce più scure disposte concentricamente. Sotto il faggio. Latte bianco, che essiccando all''aria diventa dal grigio-verde al grigio, molto piccante. La piccantezza e il latice che essicca grigio sono diagnostici.','Crudo o cotto insufficientemente, disturbi gastrointestinali: nausea, vomito, diarrea (sindrome irritativa gastrointestinale dovuta al latte piccante).','In caso di disturbi dopo il consumo: chiamare Tox Info Suisse 145. Conservare i resti dei funghi/il vomito per l''identificazione. Nessuna misura auto-indotta senza parere medico.',NULL,NULL,false),
('lactarius_camphoratus','en','Small milkcap, cap wine-red to dark chestnut-brown, often with an umbo and crenate margin. Milk watery-white, mild, unchanging. Characteristic intense lovage/Maggi smell, especially when drying. Closely related to the toxic L. helvus.','In larger quantities, intolerance/gastrointestinal irritation possible; not suitable as an edible mushroom, mentioned only as a seasoning-mushroom powder in tiny amounts.',NULL,'Not an edible mushroom in its own right. Possibly dried and ground in tiny amounts as a seasoning (Maggi substitute); due to intolerance in quantity, not recommended as an edible mushroom.',NULL,false),
('lactarius_camphoratus','es','Pequeño níscalo, sombrero de rojo vinoso a pardo castaño oscuro, a menudo con mamelón y margen crenado. Leche acuosa-blanca, suave, inmutable. Olor intenso característico a apio de monte/Maggi, sobre todo al secarse. Pariente cercano del tóxico L. helvus.','En grandes cantidades es posible intolerancia/irritación gastrointestinal; no apto como seta comestible, mencionado solo como polvo condimentario en cantidades mínimas.',NULL,'No es una seta comestible por sí sola. Eventualmente seca y molida en cantidades mínimas como condimento (sustituto del Maggi); debido a la intolerancia en cantidad, no recomendada como seta comestible.',NULL,false),
('lactarius_camphoratus','fr','Petit lactaire, chapeau rouge vineux à brun châtain foncé, souvent avec mamelon et marge crénelée. Lait aqueux-blanc, doux, immuable. Odeur intense caractéristique de livèche/Maggi, surtout au séchage. Proche parent du toxique L. helvus.','En grandes quantités, intolérance/irritation gastro-intestinale possible; non adapté comme champignon comestible, mentionné uniquement en poudre d''assaisonnement à très petites doses.',NULL,'Pas un champignon comestible en soi. Éventuellement séché et moulu en très petites quantités comme assaisonnement (substitut de Maggi); en raison de l''intolérance à dose élevée, non recommandé comme champignon comestible.',NULL,false),
('lactarius_camphoratus','it','Piccolo lattario, cappello dal rosso vinoso al bruno castano scuro, spesso con umbone e margine crenato. Latte acquoso-bianco, mite, immutabile. Odore intenso caratteristico di levistico/Maggi, soprattutto durante l''essiccazione. Parente stretto del tossico L. helvus.','In grandi quantità è possibile intolleranza/irritazione gastrointestinale; non adatto come fungo commestibile, citato solo come polvere aromatizzante in dosi minime.',NULL,'Non è un fungo commestibile a sé. Eventualmente essiccato e macinato in quantità minime come aroma (sostituto del Maggi); a causa dell''intolleranza in quantità, non raccomandato come fungo commestibile.',NULL,false),
('lactarius_helvus','en','Medium-sized milkcap on moist, acidic soils and near bogs by conifers. Cap dry, finely felty-velvety, grey-brown to leather-yellow. Milk watery, colourless and very sparse, mild. Very strong Maggi/lovage smell. Caution: despite the seasoning-like smell it is toxic (gastrointestinal poison), do NOT use as an edible mushroom.','15 min to about 1 h after consumption: vomiting, abdominal pain, salivation, watery diarrhoea, dizziness, chills, signs of collapse (gastrointestinal syndrome, dose-dependent). The poison is heat-stable – cooking does not protect.','If consumption is suspected, call Tox Info Suisse 145 immediately (24h). Keep mushroom remains/vomit for identification. Do not induce vomiting yourself without medical instruction; in case of severe symptoms, emergency number 144.',NULL,NULL,false),
('lactarius_helvus','es','Níscalo de tamaño mediano en suelos húmedos y ácidos y cerca de turberas, junto a coníferas. Sombrero seco, finamente afieltrado-aterciopelado, de pardo grisáceo a amarillo cuero. Leche acuosa, incolora y muy escasa, suave. Olor muy fuerte a Maggi/apio de monte. Atención: a pesar del olor condimentario es tóxico (veneno gastrointestinal), NO usar como seta comestible.','De 15 min a aproximadamente 1 h tras el consumo: vómitos, dolor abdominal, salivación, diarrea acuosa, mareo, escalofríos, signos de colapso (síndrome gastrointestinal, dependiente de la dosis). El veneno es termoestable – la cocción no protege.','Si se sospecha el consumo, llamar inmediatamente a Tox Info Suisse 145 (24h). Conservar los restos de setas/el vómito para la identificación. No inducir el vómito por cuenta propia sin indicación médica; en caso de síntomas graves, número de emergencia 144.',NULL,NULL,false),
('lactarius_helvus','fr','Lactaire de taille moyenne sur sols humides et acides et près des marais, sous les conifères. Chapeau sec, finement feutré-velouté, gris-brun à jaune cuir. Lait aqueux, incolore et très peu abondant, doux. Très forte odeur de Maggi/livèche. Attention: malgré l''odeur d''assaisonnement, toxique (poison gastro-intestinal), NE PAS utiliser comme champignon comestible.','15 min à env. 1 h après consommation: vomissements, douleurs abdominales, salivation, diarrhée aqueuse, vertiges, frissons, signes de collapsus (syndrome gastro-intestinal, dose-dépendant). Le poison est thermostable – la cuisson ne protège pas.','En cas de suspicion de consommation, appeler immédiatement Tox Info Suisse 145 (24h). Conserver les restes de champignons/vomissures pour l''identification. Ne pas provoquer soi-même de vomissements sans instruction médicale; en cas de symptômes sévères, appeler le 144.',NULL,NULL,false),
('lactarius_helvus','it','Lattario di media grandezza su terreni umidi e acidi e in prossimità di torbiere, presso conifere. Cappello asciutto, finemente feltrato-vellutato, dal grigio-bruno al giallo cuoio. Latte acquoso, incolore e molto scarso, mite. Odore molto forte di Maggi/levistico. Attenzione: nonostante l''odore aromatico è tossico (veleno gastrointestinale), NON usare come fungo commestibile.','Da 15 min a circa 1 ora dopo il consumo: vomito, dolori addominali, salivazione, diarrea acquosa, vertigini, brividi, segni di collasso (sindrome gastrointestinale, dose-dipendente). Il veleno è termostabile – la cottura non protegge.','In caso di sospetto consumo chiamare immediatamente Tox Info Suisse 145 (24h). Conservare i resti dei funghi/il vomito per l''identificazione. Non indurre il vomito da soli senza indicazione medica; in caso di sintomi gravi, numero d''emergenza 144.',NULL,NULL,false),
('lactarius_pallidus','en','Uniformly pale flesh- to leather-coloured, unzoned, smooth and moist-greasy cap, often with an inrolled margin. Under beech. Milk white, mild to slightly unpleasant, unchanging. Tasteless to poor in quality, therefore not an edible mushroom.',NULL,NULL,NULL,NULL,false),
('lactarius_pallidus','es','Sombrero uniformemente pálido, del color de la carne al del cuero, no zonado, liso y húmedo-grasiento, a menudo con el margen enrollado. Bajo el haya. Leche blanca, suave o ligeramente desagradable, inmutable. Insípido o de baja calidad, por lo que no es una seta comestible.',NULL,NULL,NULL,NULL,false),
('lactarius_pallidus','fr','Chapeau uniformément pâle, couleur chair à cuir, non zoné, lisse et humide-visqueux, souvent à marge enroulée. Sous le hêtre. Lait blanc, doux à légèrement désagréable, immuable. Insipide à médiocre, donc pas un champignon comestible.',NULL,NULL,NULL,NULL,false),
('lactarius_pallidus','it','Cappello uniformemente pallido, dal color carne al color cuoio, non zonato, liscio e umido-viscido, spesso con margine arrotolato. Sotto il faggio. Latte bianco, mite o leggermente sgradevole, immutabile. Insapore o scadente, quindi non è un fungo commestibile.',NULL,NULL,NULL,NULL,false),
('lactarius_quietus','en','Grows strictly associated with oak. Cap with faint concentric zonation, cinnamon to reddish-brown. Milk whitish, unchanging, mild. Distinctive oily bedbug-like smell. Gills pale with reddish spots.',NULL,NULL,NULL,NULL,false),
('lactarius_quietus','es','Crece estrictamente asociado al roble. Sombrero con zonación concéntrica difuminada, de color canela a pardo rojizo. Leche blanquecina, inmutable, suave. Olor oleoso característico a chinche. Láminas pálidas con manchas rojizas.',NULL,NULL,NULL,NULL,false),
('lactarius_quietus','fr','Pousse strictement lié au chêne. Chapeau à zonage concentrique délavé, brun cannelle à brun rougeâtre. Lait blanchâtre, immuable, doux. Odeur huileuse caractéristique de punaise. Lamelles pâles à taches rougeâtres.',NULL,NULL,NULL,NULL,false),
('lactarius_quietus','it','Cresce strettamente legato alla quercia. Cappello con zonatura concentrica sbiadita, dal bruno cannella al bruno rossastro. Latte biancastro, immutabile, mite. Odore oleoso caratteristico di cimice. Lamelle pallide con macchie rossastre.',NULL,NULL,NULL,NULL,false),
('lactarius_semisanguifluus','en','Saffron milkcap by pine on calcareous soil. Milk first orange-red, quickly turning wine-red to blood-red and then changing to verdigris-green. Flesh and cap with distinct verdigris-green discolourations. Concentrically zoned. Belongs to the group of true saffron milkcaps (Lactarius sect. Deliciosi).','Eaten raw, gastrointestinal irritation possible; must be cooked sufficiently.',NULL,'Before consumption, cook through well for at least about 15-20 min (fry/braise); NEVER eat raw. Good edible milkcap, harmonises in mixed dishes. In CH/DE sometimes rare/endangered – collect sparingly.',NULL,false),
('lactarius_semisanguifluus','es','Níscalo fino junto a pinos en suelo calcáreo. Leche primero rojo anaranjado, vira rápidamente a rojo vinoso hasta rojo sangre y luego cambia a verde cardenillo. Carne y sombrero con claras coloraciones verde cardenillo. Zonado concéntricamente. Pertenece al grupo de los verdaderos níscalos (Lactarius sect. Deliciosi).','Consumido crudo es posible una irritación gastrointestinal; debe cocinarse lo suficiente.',NULL,'Antes del consumo, cocinar bien al menos unos 15-20 min (freír/estofar); NUNCA comer crudo. Buen níscalo comestible, armoniza en platos mixtos. En CH/DE a veces raro/amenazado – recolectar con moderación.',NULL,false),
('lactarius_semisanguifluus','fr','Lactaire délicieux des pins sur sol calcaire. Lait d''abord rouge orangé, devient rapidement rouge vineux à rouge sang puis vire au vert-de-gris. Chair et chapeau présentant de nettes colorations vert-de-gris. Zoné concentriquement. Appartient au groupe des vrais lactaires délicieux (Lactarius sect. Deliciosi).','Consommé cru, irritation gastro-intestinale possible; doit être suffisamment cuit.',NULL,'Avant consommation, bien cuire au moins env. 15-20 min (rôtir/braiser); NE JAMAIS manger cru. Bon lactaire comestible, s''harmonise dans les plats mixtes. En CH/DE parfois rare/menacé – cueillir avec ménagement.',NULL,false),
('lactarius_semisanguifluus','it','Lattario delizioso presso pini su suolo calcareo. Latte dapprima rosso-arancio, diventa rapidamente rosso vinoso fino a rosso sangue e poi vira al verde-rame. Carne e cappello con evidenti colorazioni verde-rame. Zonato concentricamente. Appartiene al gruppo dei veri lattari deliziosi (Lactarius sect. Deliciosi).','Consumato crudo è possibile un''irritazione gastrointestinale; deve essere cotto a sufficienza.',NULL,'Prima del consumo cuocere bene per almeno circa 15-20 min (arrostire/brasare); MAI mangiare crudo. Buon lattario commestibile, si armonizza nei piatti misti. In CH/DE talvolta raro/minacciato – raccogliere con moderazione.',NULL,false),
('lactarius_subdulcis','en','Cap unzoned, smooth, cinnamon to red-brown, often with a small umbo. Under beech. Milk white, abundant, unchanging; taste at first sweetish, then bitterish. Low culinary value, classed as inedible by many sources.','Raw or in quantity, possible mild gastrointestinal irritation; poor culinary value, therefore only very limited use.',NULL,'Only when well cooked through and at most as a flavour-secondary mixed mushroom; because of the bitter note and low value, generally not recommended.',NULL,false),
('lactarius_subdulcis','es','Sombrero no zonado, liso, de pardo canela a pardo-rojizo, a menudo con un pequeño mamelón. Bajo las hayas. Leche blanca, abundante, inmutable; sabor primero dulzón, luego amargo. Escaso valor culinario, clasificado como no comestible por muchas fuentes.','Crudo o en cantidad, posible leve irritación gastrointestinal; valor culinario pobre, por lo que su uso es muy limitado.',NULL,'Solo bien cocinado y a lo sumo como hongo de mezcla de sabor secundario; debido a la nota amarga y al escaso valor, generalmente no recomendado.',NULL,false),
('lactarius_subdulcis','fr','Chapeau non zoné, lisse, brun cannelle à brun-rouge, souvent avec un petit mamelon. Sous les hêtres. Lait blanc, abondant, immuable ; saveur d''abord douceâtre, puis amère. Faible valeur culinaire, classé comme non comestible par de nombreuses sources.','Cru ou en quantité, possible légère irritation gastro-intestinale ; valeur culinaire médiocre, donc utilisable de manière très limitée.',NULL,'Seulement bien cuit et tout au plus comme champignon d''accompagnement de saveur secondaire ; en raison de l''amertume et de la faible valeur, généralement déconseillé.',NULL,false),
('lactarius_subdulcis','it','Cappello non zonato, liscio, da bruno cannella a bruno-rosso, spesso con un piccolo umbone. Sotto i faggi. Latte bianco, abbondante, immutabile; sapore dapprima dolciastro, poi amarognolo. Scarso valore culinario, classificato come non commestibile da molte fonti.','Crudo o in quantità, possibile lieve irritazione gastrointestinale; scarso valore culinario, quindi utilizzabile in modo molto limitato.',NULL,'Solo ben cotto e al massimo come fungo da miscela di sapore secondario; a causa della nota amara e dello scarso valore, generalmente sconsigliato.',NULL,false),
('lepista_glaucocana','en','Fleshy mushroom with a pale lavender to whitish-violet cap, paler than the wood blewit (Lepista nuda). Gills pale lilac, spore print pink. When young, a good edible. IMPORTANT: like all blewits, poisonous raw (heat-labile, gastrointestinal-irritant and blood-dissolving substances) — eat only well cooked through.','Raw or insufficiently cooked: nausea, vomiting, gastrointestinal complaints. Rarely intolerance even after cooking.','If complaints occur after eating raw or in case of intolerance: call Tox Info Suisse 145.','Poisonous raw! Eat only young and well cooked through (at least 15-20 min frying/cooking). Test a small amount before first consumption. Prepared well like Lepista nuda (risotto, fried).',NULL,false),
('lepista_glaucocana','es','Hongo carnoso con sombrero de color lavanda pálido a blanquecino-violáceo, más pálido que la seta de pie azul (Lepista nuda). Láminas lila pálido, esporada rosa. De joven es un buen comestible. IMPORTANTE: como todas las Lepista, es tóxico crudo (sustancias termolábiles, irritantes gastrointestinales y hemolíticas) — consumir solo bien cocinado.','Crudo o insuficientemente cocinado: náuseas, vómitos, molestias gastrointestinales. Rara vez intolerancia incluso tras la cocción.','En caso de molestias tras consumo en crudo o de intolerancia: llamar a Tox Info Suisse 145.','¡Tóxico crudo! Comer solo joven y bien cocinado (al menos 15-20 min de fritura/cocción). Antes del primer consumo, probar una pequeña cantidad. Se prepara bien como el Lepista nuda (risotto, frito).',NULL,false),
('lepista_glaucocana','fr','Champignon charnu au chapeau lavande pâle à blanchâtre-violacé, plus pâle que le pied bleu (Lepista nuda). Lames lilas pâle, sporée rose. Jeune, c''est un bon comestible. IMPORTANT : comme tous les pieds bleus, toxique cru (substances thermolabiles, irritantes pour le tube digestif et hémolytiques) — à ne consommer que bien cuit.','Cru ou insuffisamment cuit : nausées, vomissements, troubles gastro-intestinaux. Rarement intolérance même après cuisson.','En cas de troubles après consommation crue ou d''intolérance : appeler Tox Info Suisse 145.','Toxique cru ! À manger seulement jeune et bien cuit (au moins 15-20 min de cuisson/sauté). Avant la première consommation, tester une petite quantité. Bien préparé comme Lepista nuda (risotto, sauté).',NULL,false),
('lepista_glaucocana','it','Fungo carnoso con cappello da lavanda pallido a biancastro-violaceo, più pallido del Lepista nuda. Lamelle lilla pallido, sporata rosa. Da giovane è un buon commestibile. IMPORTANTE: come tutti i Lepista, tossico da crudo (sostanze termolabili, irritanti per l''apparato gastrointestinale ed emolitiche) — consumare solo ben cotto.','Crudo o cotto insufficientemente: nausea, vomito, disturbi gastrointestinali. Raramente intolleranza anche dopo la cottura.','In caso di disturbi dopo consumo da crudo o di intolleranza: chiamare Tox Info Suisse 145.','Tossico da crudo! Mangiare solo da giovane e ben cotto (almeno 15-20 min di cottura/saltato). Prima del primo consumo, provare una piccola quantità. Si prepara bene come il Lepista nuda (risotto, saltato).',NULL,false),
('lycoperdon_echinatum','en','Strikingly densely covered with long (up to ~6 mm) brown spines, often converging at the tips; after the spines fall off a net-like scar pattern remains. Grows singly/gregariously on humus in deciduous forests. Edible only while the inner gleba is PURE WHITE; turns young→yellow→brown, becoming inedible. Risk of confusion with the toxic common earthball (Scleroderma): this has a thick, hard outer skin and an early black-violet/marbled gleba — cross-section mandatory. Likewise, check every white spherical mushroom to rule out an Amanita egg (inner gill rudiment).',NULL,NULL,'Only young specimens with a pure-white inner gleba; low culinary value (connoisseur''s mushroom). Remove spines/outer skin, cut lengthwise (Scleroderma and Amanita exclusion), fry in butter.',NULL,false),
('lycoperdon_echinatum','es','Cubierto de forma notablemente densa de largas espinas pardas (hasta ~6 mm), a menudo unidas por las puntas; tras la caída de las espinas queda un patrón reticulado de cicatrices. Crece solitario/gregario sobre el humus en bosques de frondosas. Comestible solo mientras la gleba interna sea BLANCO PURO; vira de joven→amarillo→pardo, volviéndose no comestible. Riesgo de confusión con el Scleroderma tóxico: este tiene una piel externa gruesa y dura y una gleba pronto negro-violácea/marmoleada — sección transversal obligatoria. Asimismo, revisar todo hongo globoso blanco para descartar un huevo de Amanita (esbozo interno de las láminas).',NULL,NULL,'Solo ejemplares jóvenes con gleba interna blanco puro; escaso valor culinario (hongo para aficionados). Retirar las espinas/la piel externa, cortar a lo largo (exclusión de Scleroderma y Amanita), saltear en mantequilla.',NULL,false),
('lycoperdon_echinatum','fr','Couvert de façon remarquablement dense de longues épines brunes (jusqu''à ~6 mm), souvent réunies par les pointes ; après la chute des épines subsiste un motif de cicatrices réticulé. Pousse isolé/grégaire sur l''humus des forêts de feuillus. Comestible seulement tant que la gléba interne est BLANC PUR ; vire jeune→jaune→brun, devient non comestible. Risque de confusion avec la scléroderme vulgaire toxique (Scleroderma) : celle-ci a une peau externe épaisse et dure et une gléba précocement noir-violacé/marbrée — coupe transversale obligatoire. De même, vérifier tout champignon globuleux blanc pour exclure un œuf d''Amanita (ébauche interne des lames).',NULL,NULL,'Seulement les jeunes exemplaires à gléba interne blanc pur ; faible valeur culinaire (champignon d''amateur). Retirer les épines/la peau externe, couper dans la longueur (exclusion de Scleroderma et d''Amanita), faire revenir au beurre.',NULL,false),
('lycoperdon_echinatum','it','Ricoperto in modo notevolmente fitto di lunghi aculei bruni (fino a ~6 mm), spesso convergenti alle punte; dopo la caduta degli aculei rimane un disegno reticolato di cicatrici. Cresce isolato/gregario sull''humus nei boschi di latifoglie. Commestibile solo finché la gleba interna è BIANCO PURO; vira da giovane→giallo→bruno, diventa non commestibile. Rischio di confusione con lo Scleroderma tossico: questo ha una scorza esterna spessa e dura e una gleba precocemente nero-violacea/marmorizzata — sezione trasversale obbligatoria. Allo stesso modo, controllare ogni fungo globoso bianco per escludere un uovo di Amanita (abbozzo interno delle lamelle).',NULL,NULL,'Solo esemplari giovani con gleba interna bianco puro; scarso valore culinario (fungo da intenditori). Rimuovere aculei/scorza esterna, tagliare per il lungo (esclusione di Scleroderma e Amanita), rosolare nel burro.',NULL,false),
('marasmius_rotula','en','Tiny cap of only 0.5-1.5 cm, whitish, parachute-like with deep radial grooves and an umbilicate centre. Diagnostic: the few gills are not attached to the stem but converge into a free collar (collarium) around the stem. Stem thin, wiry, glossy black-brown, horn-tough. Saprobic on rotten twigs, often in troops. Dries out and revives with moisture (collared parachute).',NULL,NULL,NULL,NULL,false),
('marasmius_rotula','es','Sombrero diminuto de solo 0,5-1,5 cm, blanquecino, en forma de paracaídas con profundos surcos radiales y centro umbilicado. Diagnóstico: las escasas láminas no están unidas al pie sino que convergen en un collar libre alrededor del pie. Pie delgado, filiforme, pardo-negro brillante, coriáceo como el cuerno. Saprófito sobre ramas en descomposición, a menudo en grupo. Se deseca y revive con la humedad (marasmio).',NULL,NULL,NULL,NULL,false),
('marasmius_rotula','fr','Chapeau minuscule de seulement 0,5-1,5 cm, blanchâtre, en parachute avec de profonds sillons radiaux et un centre ombiliqué. Diagnostique : les rares lames ne sont pas attachées au pied mais convergent en un collier (collerette) libre autour du pied. Pied mince, filiforme, brun-noir brillant, coriace comme de la corne. Saprophyte sur les branches pourries, souvent en troupe. Se dessèche et reprend vie avec l''humidité (marasme).',NULL,NULL,NULL,NULL,false),
('marasmius_rotula','it','Cappello minuscolo di soli 0,5-1,5 cm, biancastro, a paracadute con profonde scanalature radiali e centro ombelicato. Diagnostico: le poche lamelle non sono attaccate al gambo ma convergono in un collare libero attorno al gambo. Gambo sottile, filiforme, bruno-nero lucido, coriaceo come il corno. Saprofita su rami marcescenti, spesso in gruppo. Si dissecca e rivive con l''umidità (marasmio).',NULL,NULL,NULL,NULL,false),
('megacollybia_platyphylla','en','Cap 5-15 cm, grey-brown to soot-grey, radially fibrillose-streaked, often with a split margin. Diagnostic: the strikingly broad, widely spaced white gills. Stem stout, longitudinally fibrous, whitish, at the base with thick white rhizomorphs (root-like strands) to the wood — a very typical feature. Grows on buried wood and rotten stumps. Spore print white.','Gastrointestinal complaints (nausea, vomiting, abdominal pain, diarrhoea) in some consumers, highly individual; old specimens are bitter and indigestible. Recent assessment: weakly poisonous / indigestible, formerly wrongly listed as edible. Related Megacollybia species (e.g. M. virosa) are proven poisonous.','Consumption not recommended. If eaten and gastrointestinal symptoms occur: call Tox Info Suisse 145 (24h), keep mushroom remains, ensure fluid intake, in case of severe/persistent vomiting or diarrhoea seek medical evaluation.',NULL,NULL,false),
('megacollybia_platyphylla','es','Sombrero 5-15 cm, de pardo-gris a gris hollín, radialmente fibriloso-estriado, con margen a menudo agrietado. Diagnósticas: las láminas blancas notablemente anchas y separadas. Pie robusto, fibroso longitudinalmente, blanquecino, en la base con gruesos rizomorfos blancos (cordones radiciformes) hacia la madera — carácter muy típico. Crece sobre madera enterrada y tocones en descomposición. Esporada blanca.','Molestias gastrointestinales (náuseas, vómitos, dolores abdominales, diarrea) en una parte de los consumidores, muy variables según el individuo; los ejemplares viejos son amargos e indigestos. Evaluación reciente: levemente tóxico / indigesto, antiguamente considerado erróneamente comestible. Las especies afines de Megacollybia (p. ej. M. virosa) son comprobadamente tóxicas.','Consumo no recomendado. En caso de consumo y síntomas gastrointestinales: llamar a Tox Info Suisse 145 (24h), conservar los restos de hongos, cuidar la hidratación, en caso de vómitos o diarrea fuertes/persistentes acudir al médico.',NULL,NULL,false),
('megacollybia_platyphylla','fr','Chapeau 5-15 cm, gris-brun à gris suie, à fibrilles-stries radiales, à marge souvent fendillée. Diagnostiques : les lames blanches remarquablement larges et espacées. Pied robuste, fibreux longitudinalement, blanchâtre, à la base avec d''épais rhizomorphes blancs (cordons radiciformes) vers le bois — caractère très typique. Pousse sur du bois enterré et des souches pourries. Sporée blanche.','Troubles gastro-intestinaux (nausées, vomissements, douleurs abdominales, diarrhée) chez une partie des consommateurs, très variables selon les individus ; les vieux exemplaires sont amers et indigestes. Évaluation récente : légèrement toxique / indigeste, autrefois faussement considéré comme comestible. Les espèces apparentées de Megacollybia (p. ex. M. virosa) sont avérées toxiques.','Consommation déconseillée. En cas de consommation et de symptômes gastro-intestinaux : appeler Tox Info Suisse 145 (24h), conserver les restes de champignons, veiller à l''hydratation, en cas de vomissements ou de diarrhée forts/persistants, consulter un médecin.',NULL,NULL,false),
('megacollybia_platyphylla','it','Cappello 5-15 cm, da grigio-bruno a grigio fuliggine, radialmente fibrilloso-striato, con margine spesso lacerato. Diagnostiche: le lamelle bianche notevolmente larghe e distanziate. Gambo robusto, fibroso longitudinalmente, biancastro, alla base con spessi rizomorfi bianchi (cordoni radiciformi) verso il legno — carattere molto tipico. Cresce su legno interrato e ceppi marcescenti. Sporata bianca.','Disturbi gastrointestinali (nausea, vomito, dolori addominali, diarrea) in una parte dei consumatori, molto variabili da individuo a individuo; gli esemplari vecchi sono amari e indigesti. Valutazione recente: debolmente tossico / indigesto, un tempo erroneamente considerato commestibile. Le specie affini di Megacollybia (es. M. virosa) sono comprovatamente tossiche.','Consumo sconsigliato. In caso di consumo e di sintomi gastrointestinali: chiamare Tox Info Suisse 145 (24h), conservare i resti dei funghi, curare l''idratazione, in caso di vomito o diarrea forti/persistenti consultare un medico.',NULL,NULL,false),
('mitrophora_semilibera','en','Small bell-conical, honeycombed cap that stands clearly free of the strikingly long, whitish, hollow stem in its lower third (''half-free''). The entire fruit body is hollow inside. Honeycomb ridges longitudinally oriented, olive- to dark brown. Stem often longer than the cap, whitish, mealy-granular.','Raw or insufficiently cooked: Morchella syndrome with dizziness, balance disturbances, trembling, an intoxicated state and possible disturbances of consciousness; additionally gastrointestinal complaints.','If complaints occur after eating, call Tox Info Suisse 145. Never eat raw or insufficiently cooked.','Like all morels, eat only well cooked through: cook thoroughly for at least 15 minutes or dry for several months beforehand. Discard the cooking water, do not use raw.',NULL,false),
('mitrophora_semilibera','es','Pequeño sombrero acampanado-cónico, alveolado, que se separa claramente del pie blanquecino, hueco y notablemente largo en su tercio inferior (''semilibre''). Todo el cuerpo fructífero es hueco por dentro. Costillas de los alvéolos orientadas longitudinalmente, de pardo oliva a pardo oscuro. Pie a menudo más largo que el sombrero, blanquecino, furfuráceo.','Crudo o insuficientemente cocinado: síndrome morchélico con mareos, trastornos del equilibrio, temblores, estado de embriaguez y posibles trastornos de la consciencia; además molestias gastrointestinales.','En caso de molestias tras el consumo, llamar a Tox Info Suisse 145. Nunca comer crudo o insuficientemente cocinado.','Como todas las colmenillas, comer solo bien cocinado: cocinar a fondo al menos 15 minutos o secar previamente durante varios meses. Desechar el agua de cocción, no usar crudo.',NULL,false),
('mitrophora_semilibera','fr','Petit chapeau campanulé-conique, alvéolé, qui se détache nettement du pied blanchâtre, creux et remarquablement long dans son tiers inférieur (''semi-libre''). Tout le carpophore est creux à l''intérieur. Côtes des alvéoles orientées longitudinalement, brun-olive à brun foncé. Pied souvent plus long que le chapeau, blanchâtre, furfuracé.','Cru ou insuffisamment cuit : syndrome morchellique avec vertiges, troubles de l''équilibre, tremblements, état d''ébriété et possibles troubles de la conscience ; en outre troubles gastro-intestinaux.','En cas de troubles après consommation, appeler Tox Info Suisse 145. Ne jamais manger cru ou insuffisamment cuit.','Comme toutes les morilles, à ne manger que bien cuit : cuire à fond au moins 15 minutes ou faire sécher plusieurs mois auparavant. Jeter l''eau de cuisson, ne pas utiliser cru.',NULL,false),
('mitrophora_semilibera','it','Piccolo cappello campanulato-conico, alveolato, che si stacca nettamente dal gambo biancastro, cavo e notevolmente lungo nel suo terzo inferiore (''semilibero''). L''intero corpo fruttifero è cavo all''interno. Coste degli alveoli orientate longitudinalmente, da bruno-oliva a bruno scuro. Gambo spesso più lungo del cappello, biancastro, furfuraceo.','Crudo o cotto insufficientemente: sindrome morchellica con vertigini, disturbi dell''equilibrio, tremori, stato di ebbrezza e possibili disturbi della coscienza; inoltre disturbi gastrointestinali.','In caso di disturbi dopo il consumo chiamare Tox Info Suisse 145. Non mangiare mai crudo o cotto insufficientemente.','Come tutte le spugnole, mangiare solo ben cotto: cuocere bene almeno 15 minuti o essiccare in anticipo per diversi mesi. Gettare l''acqua di cottura, non utilizzare crudo.',NULL,false),
('mycena_galericulata','en','Grows in clusters on rotten deciduous wood, conical-bell-shaped grooved cap up to 6 cm. Gills whitish, tinged pink with age and connected by distinct cross-veins (an important feature). Stem tough-cartilaginous, hollow, smooth, light above, darker below, often strigose-felted at the base. Mealy smell and taste. Spore print white.',NULL,NULL,NULL,NULL,false),
('mycena_galericulata','es','Crece en grupos sobre madera de frondosas en descomposición, sombrero cónico-acampanado estriado de hasta 6 cm. Láminas blanquecinas, con la edad teñidas de rosa y unidas por nítidas venas transversales (carácter importante). Pie coriáceo-cartilaginoso, hueco, liso, claro arriba, más oscuro abajo, en la base a menudo estriguloso-afieltrado. Olor y sabor harinosos. Esporada blanca.',NULL,NULL,NULL,NULL,false),
('mycena_galericulata','fr','Pousse en touffes sur le bois feuillu pourri, chapeau conique-campanulé strié jusqu''à 6 cm. Lames blanchâtres, teintées de rose avec l''âge et reliées par de nettes veines transversales (caractère important). Pied coriace-cartilagineux, creux, lisse, clair en haut, plus sombre en bas, souvent strigueux-feutré à la base. Odeur et saveur farineuses. Sporée blanche.',NULL,NULL,NULL,NULL,false),
('mycena_galericulata','it','Cresce a ciuffi su legno di latifoglia marcescente, cappello conico-campanulato striato fino a 6 cm. Lamelle biancastre, con l''età sfumate di rosa e collegate da nette venature trasversali (carattere importante). Gambo coriaceo-cartilagineo, cavo, liscio, chiaro in alto, più scuro in basso, alla base spesso strigoso-feltrato. Odore e sapore farinosi. Sporata bianca.',NULL,NULL,NULL,NULL,false),
('panaeolina_foenisecii','en','Small, very common meadow mushroom. Cap strongly hygrophanous, date-brown when moist, fading when dry, often with a darker marginal zone. Unlike Panaeolus, spore print warty, purple-brown (not pure black). On lawns and meadows, often after mowing. Regarded as (slightly) poisonous; psilocybin content regionally variable/disputed.','Raw or in quantity: gastrointestinal complaints (nausea, vomiting, diarrhoea). In isolated cases (especially in children), confusion/intoxication symptoms have been described after consumption. Because of its small size and uncertain constituents, generally to be treated as unsuitable/poisonous.','If consumed by children or in case of confusion/intoxication symptoms, call Tox Info Suisse 145. Otherwise, in case of gastrointestinal complaints, ensure fluid intake.',NULL,NULL,false),
('panaeolina_foenisecii','es','Pequeño hongo de pradera, muy común. Sombrero fuertemente higrófano, pardo dátil en húmedo, palideciendo en seco, a menudo con una zona marginal más oscura. A diferencia de Panaeolus, esporada verrugosa, pardo-purpúrea (no negro puro). En céspedes y praderas, a menudo tras la siega. Considerado (ligeramente) tóxico; contenido de psilocibina variable según la región/controvertido.','Crudo o en cantidad: molestias gastrointestinales (náuseas, vómitos, diarrea). En casos aislados (sobre todo en niños) se han descrito síntomas de confusión/embriaguez tras el consumo. Debido a su pequeño tamaño y a sus componentes inciertos, debe tratarse en general como no apto/tóxico.','En caso de consumo por niños o de síntomas de confusión/embriaguez, llamar a Tox Info Suisse 145. De lo contrario, en caso de molestias gastrointestinales, cuidar la hidratación.',NULL,NULL,false),
('panaeolina_foenisecii','fr','Petit champignon des prés, très commun. Chapeau fortement hygrophane, brun datte humide, pâlissant à sec, souvent avec une zone marginale plus sombre. Contrairement à Panaeolus, sporée verruqueuse, brun-pourpre (et non noir pur). Sur gazons et prairies, souvent après la tonte. Considéré comme (légèrement) toxique ; teneur en psilocybine variable selon les régions/controversée.','Cru ou en quantité : troubles gastro-intestinaux (nausées, vomissements, diarrhée). Dans des cas isolés (surtout chez les enfants), des symptômes de confusion/d''ivresse ont été décrits après consommation. En raison de sa petite taille et de ses composants incertains, à traiter de manière générale comme impropre/toxique.','En cas de consommation par des enfants ou de symptômes de confusion/d''ivresse, appeler Tox Info Suisse 145. Sinon, en cas de troubles gastro-intestinaux, veiller à l''hydratation.',NULL,NULL,false),
('panaeolina_foenisecii','it','Piccolo fungo dei prati, molto comune. Cappello fortemente igrofano, bruno dattero da umido, schiarente da secco, spesso con una zona marginale più scura. A differenza di Panaeolus, sporata verrucosa, bruno-purpurea (non nero puro). Su tappeti erbosi e prati, spesso dopo lo sfalcio. Considerato (lievemente) tossico; contenuto di psilocibina variabile per regione/controverso.','Crudo o in quantità: disturbi gastrointestinali (nausea, vomito, diarrea). In casi isolati (soprattutto nei bambini) sono stati descritti sintomi di confusione/ebbrezza dopo il consumo. A causa delle piccole dimensioni e dei componenti incerti, da trattare in generale come inadatto/tossico.','In caso di consumo da parte di bambini o di sintomi di confusione/ebbrezza, chiamare Tox Info Suisse 145. Altrimenti, in caso di disturbi gastrointestinali, curare l''idratazione.',NULL,NULL,false),
('panaeolus_cinctulus','en','Cap strongly hygrophanous: brown when moist, fading from the centre as it dries, thereby forming a distinct dark marginal band (''dark-rimmed''/''girdled''). Gills mottled black, spore print black. On fertilised soils, compost and dung. Contains psilocybin.','Psilocybin syndrome: after 0.5-1 h hallucinations, perceptual and consciousness disturbances, confusion, anxiety, pupil dilation, racing heart, nausea. Psilocybin is a controlled substance in Switzerland (Narcotics Act, BetmG).','Reassure the affected person and supervise them in a low-stimulus environment. In case of panic, circulatory or cardiac problems, call Tox Info Suisse 145.',NULL,NULL,false),
('panaeolus_cinctulus','es','Sombrero fuertemente higrófano: pardo en húmedo, palideciendo desde el centro al secarse, formando así una nítida banda marginal oscura (''de margen oscuro''/''ceñido''). Láminas moteadas de negro, esporada negra. En suelos abonados, compost y estiércol. Contiene psilocibina.','Síndrome psilocíbico: tras 0,5-1 h alucinaciones, trastornos de la percepción y de la consciencia, confusión, ansiedad, dilatación de las pupilas, taquicardia, náuseas. La psilocibina es una sustancia controlada en Suiza (Ley de Estupefacientes, BetmG).','Tranquilizar a la persona afectada y vigilarla en un entorno de baja estimulación. En caso de pánico, problemas circulatorios o cardíacos, llamar a Tox Info Suisse 145.',NULL,NULL,false),
('panaeolus_cinctulus','fr','Chapeau fortement hygrophane : brun humide, pâlissant depuis le centre en séchant, formant ainsi une nette bande marginale sombre (''à marge sombre''/''ceinturé''). Lames mouchetées de noir, sporée noire. Sur sols fertilisés, compost et fumier. Contient de la psilocybine.','Syndrome psilocybien : après 0,5-1 h, hallucinations, troubles de la perception et de la conscience, confusion, anxiété, dilatation des pupilles, tachycardie, nausées. La psilocybine est une substance contrôlée en Suisse (LStup).','Calmer la personne concernée et la surveiller dans un environnement peu stimulant. En cas de panique, de problèmes circulatoires ou cardiaques, appeler Tox Info Suisse 145.',NULL,NULL,false),
('panaeolus_cinctulus','it','Cappello fortemente igrofano: bruno da umido, che schiarisce dal centro asciugandosi, formando così una netta banda marginale scura (''a margine scuro''/''cinto''). Lamelle screziate di nero, sporata nera. Su terreni concimati, compost e letame. Contiene psilocibina.','Sindrome psilocibinica: dopo 0,5-1 h allucinazioni, disturbi della percezione e della coscienza, confusione, ansia, dilatazione delle pupille, tachicardia, nausea. La psilocibina è una sostanza controllata in Svizzera (LStup).','Tranquillizzare la persona interessata e sorvegliarla in un ambiente poco stimolante. In caso di panico, problemi circolatori o cardiaci, chiamare Tox Info Suisse 145.',NULL,NULL,false),
('paralepista_flaccida','en','Funnel-shaped cap of fox-red to orange-brown colour, often growing in fairy rings or rows. Gills crowded, decurrent, cream-coloured. Spore print slightly pink (transition to Lepista). Poisonous raw — contains heat-labile, gastrointestinal-irritant substances; edible only when well cooked. Confusion possible with white muscarine-containing funnel caps (Clitocybe).','Raw or insufficiently cooked: gastrointestinal complaints (nausea, vomiting, diarrhoea). Intolerance possible even after cooking.','If complaints occur after eating: call Tox Info Suisse 145. Keep mushroom remains/cleaning scraps.','Edible only when well cooked (cook at least 20 min). Raw and insufficiently cooked, poisonous. Not digestible for everyone — test a small amount. Use only young, firm specimens.',NULL,false),
('paralepista_flaccida','es','Sombrero en forma de embudo de color pardo anaranjado-rojizo, que crece a menudo en corros de brujas o en hileras. Láminas apretadas, decurrentes, color crema. Esporada ligeramente rosa (transición hacia Lepista). Tóxico crudo — contiene sustancias termolábiles irritantes gastrointestinales; comestible solo bien cocinado. Posible confusión con los clitocibes blancos con muscarina.','Crudo o insuficientemente cocinado: molestias gastrointestinales (náuseas, vómitos, diarrea). Posible intolerancia incluso tras la cocción.','En caso de molestias tras el consumo: llamar a Tox Info Suisse 145. Conservar los restos de hongos/los desechos de limpieza.','Comestible solo bien cocinado (cocinar al menos 20 min). Crudo e insuficientemente cocinado, tóxico. No digerible para todos — probar una pequeña cantidad. Usar solo ejemplares jóvenes y firmes.',NULL,false),
('paralepista_flaccida','fr','Chapeau en entonnoir de couleur fauve-orangé brun, poussant souvent en ronds de sorcières ou en rangées. Lames serrées, décurrentes, crème. Sporée légèrement rose (transition vers Lepista). Toxique cru — contient des substances thermolabiles irritantes pour le tube digestif ; comestible seulement bien cuit. Confusion possible avec les clitocybes blancs à muscarine.','Cru ou insuffisamment cuit : troubles gastro-intestinaux (nausées, vomissements, diarrhée). Intolérance possible même après cuisson.','En cas de troubles après consommation : appeler Tox Info Suisse 145. Conserver les restes de champignons/déchets de nettoyage.','Comestible seulement bien cuit (cuire au moins 20 min). Cru et insuffisamment cuit, toxique. Ne convient pas à tous — tester une petite quantité. N''utiliser que des exemplaires jeunes et fermes.',NULL,false),
('paralepista_flaccida','it','Cappello a imbuto di colore bruno fulvo-arancio, che cresce spesso in cerchi delle streghe o in file. Lamelle fitte, decorrenti, color crema. Sporata leggermente rosa (transizione verso Lepista). Tossico da crudo — contiene sostanze termolabili irritanti per l''apparato gastrointestinale; commestibile solo ben cotto. Possibile confusione con i clitocybi bianchi muscarinici.','Crudo o cotto insufficientemente: disturbi gastrointestinali (nausea, vomito, diarrea). Possibile intolleranza anche dopo la cottura.','In caso di disturbi dopo il consumo: chiamare Tox Info Suisse 145. Conservare i resti dei funghi/gli scarti di pulizia.','Commestibile solo ben cotto (cuocere almeno 20 min). Crudo e cotto insufficientemente, tossico. Non digeribile da tutti — provare una piccola quantità. Utilizzare solo esemplari giovani e sodi.',NULL,false),
('phaeolus_schweinitzii','en','Annual fruiting body, softly felted to spongy, top-shaped or bracket-like, at the base of conifers. Upper surface yellow-edged when young, velvety-felted, later rust-brown. Pores darkening when pressed. Becomes woody with age, then hard and corky. Classic dyer''s mushroom. Inedible — tough and without food value.',NULL,NULL,NULL,NULL,false),
('phaeolus_schweinitzii','es','Cuerpo fructífero anual, de blandamente afieltrado a esponjoso, en forma de trompo o de ménsula, en la base de las coníferas. Superficie superior con borde amarillo de joven, aterciopelada-afieltrada, más tarde pardo herrumbre. Poros que oscurecen a la presión. Se lignifica con la edad, volviéndose entonces duro y corchoso. Hongo tintóreo clásico. No comestible — coriáceo y sin valor alimentario.',NULL,NULL,NULL,NULL,false),
('phaeolus_schweinitzii','fr','Carpophore annuel, mollement feutré à spongieux, en toupie ou en console, à la base des conifères. Face supérieure jeune bordée de jaune, veloutée-feutrée, plus tard brun rouille. Pores noircissant à la pression. Se lignifie avec l''âge, devenant alors dur et liégeux. Champignon tinctorial classique. Immangeable — coriace et sans valeur alimentaire.',NULL,NULL,NULL,NULL,false),
('phaeolus_schweinitzii','it','Corpo fruttifero annuale, da mollemente feltroso a spugnoso, a trottola o a mensola, alla base delle conifere. Faccia superiore da giovane orlata di giallo, vellutato-feltrosa, più tardi bruno ruggine. Pori che anneriscono alla pressione. Si lignifica con l''età, diventando allora duro e suberoso. Classico fungo tintorio. Non commestibile — coriaceo e senza valore alimentare.',NULL,NULL,NULL,NULL,false),
('phellodon_niger','en','Dark, grey-blue to black tooth fungus with a paler margin and white to grey-blue spines instead of gills. Characteristic is the intense Maggi/fenugreek scent when drying. Flesh in two layers, corky-tough. Inedible due to its tough, woody consistency; not poisonous. Can be confused with other Phellodon species (all inedible).',NULL,NULL,NULL,NULL,false),
('phellodon_niger','es','Hidno oscuro, de gris azulado a negro, con margen más claro y aguijones de blancos a gris azulado en lugar de láminas. Característico es el intenso olor a Maggi/fenogreco al secarse. Carne en dos capas, corchoso-coriácea. No comestible por su consistencia coriácea y leñosa; no tóxico. Posible confusión con otras especies de Phellodon (todas no comestibles).',NULL,NULL,NULL,NULL,false),
('phellodon_niger','fr','Hydne sombre, gris-bleu noir, à marge plus claire et aiguillons blancs à gris-bleu au lieu de lames. Caractéristique est l''intense odeur de Maggi/fenugrec au séchage. Chair en deux couches, liégeuse-coriace. Immangeable en raison de sa consistance coriace et ligneuse ; non toxique. Confusion possible avec d''autres espèces de Phellodon (toutes immangeables).',NULL,NULL,NULL,NULL,false),
('phellodon_niger','it','Idno scuro, da grigio-blu a nero, con margine più chiaro e aculei da bianchi a grigio-blu invece di lamelle. Caratteristico è l''intenso odore di Maggi/fieno greco all''essiccazione. Carne a due strati, suberoso-coriacea. Non commestibile per la consistenza coriacea e legnosa; non tossico. Possibile confusione con altre specie di Phellodon (tutte non commestibili).',NULL,NULL,NULL,NULL,false),
('pholiota_alnicola','en','In clusters on alder stumps/trunks of damp sites, smooth to slightly slimy yellow cap, usually WITHOUT or with only a few scales (smaller and less scaly than P. aurivella). Gills yellow when young, then rust-brown. Bitter taste — inedible, not suitable for consumption.','Bitter and potentially stomach-irritating; if consumed, gastrointestinal upset possible — should not be eaten.',NULL,NULL,NULL,false),
('pholiota_alnicola','es','En grupos sobre tocones/troncos de aliso en estaciones húmedas, sombrero amarillo liso a ligeramente viscoso, normalmente SIN escamas o con solo unas pocas (más pequeño y menos escamoso que P. aurivella). Láminas amarillas de jóvenes, luego pardo herrumbre. Sabor amargo — no comestible, no apto para el consumo.','Amargo y potencialmente irritante para el estómago; en caso de consumo, posibles trastornos gastrointestinales — no debe comerse.',NULL,NULL,NULL,false),
('pholiota_alnicola','fr','En touffes sur souches/troncs d''aulnes de stations humides, chapeau jaune lisse à légèrement visqueux, généralement SANS squamules ou avec seulement quelques-unes (plus petit et moins squameux que P. aurivella). Lames jeunes jaunes, puis brun rouille. Saveur amère — immangeable, impropre à la consommation.','Amer et potentiellement irritant pour l''estomac ; en cas de consommation, troubles gastro-intestinaux possibles — ne doit pas être consommé.',NULL,NULL,NULL,false),
('pholiota_alnicola','it','A ciuffi su ceppi/tronchi di ontano in stazioni umide, cappello giallo liscio o leggermente viscido, di solito SENZA squamette o con solo poche (più piccolo e meno squamoso di P. aurivella). Lamelle da giovani gialle, poi bruno ruggine. Sapore amaro — non commestibile, non adatto al consumo.','Amaro e potenzialmente irritante per lo stomaco; in caso di consumo possibili disturbi gastrointestinali — non deve essere mangiato.',NULL,NULL,NULL,false),
('pholiota_aurivella','en','In clusters or solitary, high on the trunks of deciduous trees; cap a bright golden-yellow, slimy, with appressed darker, rust-brown scales. Gills yellow when young, then rust-brown. Stem with a fleeting ring and scales. Historically listed as edible, but caused stomach upset — today classified as inedible/unsafe.','Stomach upsets/gastrointestinal complaints reported in isolated cases; not suitable for consumption.',NULL,NULL,NULL,false),
('pholiota_aurivella','es','En grupos o solitario, en lo alto de los troncos de árboles caducifolios; sombrero de un amarillo dorado brillante, viscoso, con escamas más oscuras apretadas, de color pardo herrumbre. Láminas amarillas de jóvenes, luego pardo herrumbre. Pie con anillo fugaz y escamas. Históricamente catalogado como comestible, pero causó molestias estomacales — hoy clasificado como no comestible/inseguro.','Trastornos estomacales/gastrointestinales notificados en casos aislados; no apto para el consumo.',NULL,NULL,NULL,false),
('pholiota_aurivella','fr','En touffes ou isolé, haut sur les troncs de feuillus ; chapeau d''un jaune doré éclatant, visqueux, avec des squamules plus foncées appliquées, brun rouille. Lames jeunes jaunes, puis brun rouille. Pied à anneau fugace et squameux. Historiquement répertorié comme comestible, mais a provoqué des troubles gastriques — aujourd''hui classé comme immangeable/incertain.','Indigestions/troubles gastro-intestinaux rapportés isolément ; impropre à la consommation.',NULL,NULL,NULL,false),
('pholiota_aurivella','it','A ciuffi o isolato, in alto sui tronchi di latifoglie; cappello giallo dorato brillante, viscido, con squamette più scure appressate, bruno ruggine. Lamelle da giovani gialle, poi bruno ruggine. Gambo con anello fugace e squamette. Storicamente elencato come commestibile, ma ha causato disturbi gastrici — oggi classificato come non commestibile/incerto.','Riportati isolatamente disturbi gastrici/gastrointestinali; non adatto al consumo.',NULL,NULL,NULL,false),
('pluteus_salicinus','en','Shield fungus with free gills, pink at maturity, and pink spore print. Cap grey to grey-green, often with a characteristic blue-green/blue tint, especially at the centre and on the stem when injured (psilocybin-typical bluing). Grows on rotting deciduous wood. Contains psilocybin.','Psilocybin syndrome: after 0.5-1 h hallucinations, perceptual disturbances, confusion, anxiety/panic, pupil dilation, racing heart, nausea. Psilocybin is a controlled substance in Switzerland (NarcA).','Calm and supervise the affected person in a low-stimulus environment. In case of panic or circulatory problems, call Tox Info Suisse 145.',NULL,NULL,false),
('pluteus_salicinus','es','Pluteo de láminas libres, rosas en la madurez, y esporada rosa. Sombrero de gris a gris verdoso, a menudo con un reflejo azul verdoso/azul característico, sobre todo en el centro y en el pie al lesionarse (azulado típico de la psilocibina). Crece sobre madera de frondosas en descomposición. Contiene psilocibina.','Síndrome por psilocibina: tras 0,5-1 h, alucinaciones, trastornos de la percepción, confusión, ansiedad/pánico, dilatación de las pupilas, taquicardia, náuseas. La psilocibina es en Suiza una sustancia controlada (LEstup).','Tranquilizar y vigilar a la persona afectada en un entorno con pocos estímulos. En caso de pánico o problemas circulatorios, llamar a Tox Info Suisse 145.',NULL,NULL,false),
('pluteus_salicinus','fr','Plutée à lames libres, roses à maturité, et sporée rose. Chapeau gris à gris-vert, souvent avec un reflet bleu-vert/bleu caractéristique, surtout au centre et sur le pied en cas de blessure (bleuissement typique de la psilocybine). Pousse sur bois feuillu pourri. Contient de la psilocybine.','Syndrome psilocybien : après 0,5-1 h, hallucinations, troubles de la perception, confusion, anxiété/panique, dilatation des pupilles, tachycardie, nausées. La psilocybine est en Suisse une substance contrôlée (LStup).','Calmer et surveiller la personne concernée dans un environnement pauvre en stimuli. En cas de panique, de problèmes circulatoires, appeler Tox Info Suisse 145.',NULL,NULL,false),
('pluteus_salicinus','it','Pluteo a lamelle libere, rosa a maturità, e sporata rosa. Cappello da grigio a grigio-verde, spesso con un riflesso blu-verde/blu caratteristico, soprattutto al centro e sul gambo in caso di lesione (viraggio al blu tipico della psilocibina). Cresce su legno di latifoglie marcescente. Contiene psilocibina.','Sindrome da psilocibina: dopo 0,5-1 h allucinazioni, disturbi della percezione, confusione, ansia/panico, dilatazione delle pupille, tachicardia, nausea. La psilocibina è in Svizzera una sostanza controllata (LStup).','Tranquillizzare e sorvegliare la persona interessata in un ambiente povero di stimoli. In caso di panico o problemi circolatori, chiamare Tox Info Suisse 145.',NULL,NULL,false),
('polyporus_umbellatus','en','Large, much-branched fruiting body made up of dozens to hundreds of small (1–4 cm), centrally navelled, light-brown individual caps on a common white stipe. Arises from an underground sclerotium, often somewhat away from the trunk. Flesh white and soft when young. Rare and worthy of protection in Switzerland — do not collect for the kitchen. Only young fruiting bodies are edible.',NULL,NULL,'Use only young, soft caps, cook thoroughly. Because of its rarity in Switzerland, better to leave it standing and only photograph it instead of harvesting.',NULL,false),
('polyporus_umbellatus','es','Gran cuerpo fructífero muy ramificado formado por decenas a cientos de pequeños sombreros individuales (1–4 cm), umbilicados en el centro, de color pardo claro, sobre un tronco común blanco. Surge de un esclerocio subterráneo, a menudo algo alejado del tronco. Carne blanca y blanda de joven. Raro y digno de protección en Suiza — no recolectar para la cocina. Solo los cuerpos fructíferos jóvenes son comestibles.',NULL,NULL,'Usar solo los sombreritos jóvenes y tiernos, cocinar bien. Por su rareza en Suiza, es mejor dejarlo en su sitio y solo fotografiarlo en vez de recolectarlo.',NULL,false),
('polyporus_umbellatus','fr','Grand carpophore très ramifié formé de dizaines à centaines de petits chapeaux individuels (1–4 cm), centralement ombiliqués, brun clair, sur un tronc commun blanc. Naît d''un sclérote souterrain, souvent un peu éloigné du tronc. Chair jeune blanche et molle. Rare et digne de protection en Suisse — ne pas récolter pour la cuisine. Seuls les jeunes carpophores sont comestibles.',NULL,NULL,'N''utiliser que les jeunes chapeaux tendres, bien cuire. En raison de sa rareté en Suisse, mieux vaut le laisser sur place et seulement le photographier au lieu de le récolter.',NULL,false),
('polyporus_umbellatus','it','Grande corpo fruttifero molto ramificato formato da decine a centinaia di piccoli cappelli singoli (1–4 cm), centralmente ombelicati, bruno chiaro, su un tronco comune bianco. Nasce da uno sclerozio sotterraneo, spesso un po'' distante dal tronco. Carne da giovane bianca e molle. Raro e degno di protezione in Svizzera — non raccogliere per la cucina. Solo i giovani corpi fruttiferi sono commestibili.',NULL,NULL,'Usare solo i cappellini giovani e teneri, cuocere bene. Per la sua rarità in Svizzera è meglio lasciarlo sul posto e solo fotografarlo invece di raccoglierlo.',NULL,false),
('psathyrella_candolleana','en','Cap hygrophanous, young honey- to ochre-brown, quickly fading to cream-white, with hanging whitish veil remnants at the cap margin ("fringed"). Gills maturing from pale to purple-/violet-brown. Flesh very thin and brittle. In clusters on buried deciduous wood. Better avoided because of the risk of confusion with small brittlestems/mottlegills.',NULL,NULL,NULL,NULL,false),
('psathyrella_candolleana','es','Sombrero higrófano, de joven pardo miel a ocre, que palidece rápidamente a blanco crema, con restos de velo blanquecinos colgantes en el margen del sombrero (« flecado »). Láminas que maduran de pálido a pardo púrpura/violáceo. Carne muy delgada y frágil. En grupos sobre madera de frondosas enterrada. Mejor evitarlo por el riesgo de confusión con pequeñas psatirelas/paneolos.',NULL,NULL,NULL,NULL,false),
('psathyrella_candolleana','fr','Chapeau hygrophane, jeune brun miel à ocre, pâlissant rapidement en blanc crème, avec des restes de voile blanchâtres pendants à la marge du chapeau (« frangé »). Lames mûrissant du pâle au brun pourpre/violacé. Chair très mince et fragile. En touffes sur bois feuillu enterré. Mieux vaut l''éviter en raison du risque de confusion avec de petits psathyrelles/panéoles.',NULL,NULL,NULL,NULL,false),
('psathyrella_candolleana','it','Cappello igrofano, da giovane bruno miele a ocra, che impallidisce rapidamente a bianco crema, con resti di velo biancastri pendenti al margine del cappello (« frangiato »). Lamelle che maturano da pallide a bruno-porpora/violaceo. Carne molto sottile e fragile. A ciuffi su legno di latifoglie interrato. Meglio evitarlo per il rischio di confusione con piccole psatirelle/panaeoli.',NULL,NULL,NULL,NULL,false),
('pseudoclitocybe_cyathiformis','en','Deeply funnel- to cup-shaped cap, coffee- to grey-brown, hygrophanous (paler when dry). Gills grey, characteristically forked and strongly decurrent, spore print white. Appears late (late autumn to winter). Can be confused with the grey-blue forked funnel cap (P. obbata, bitter-almond/hydrocyanic-acid smell) and the reddening woodwax. Low food value; edible only when thoroughly cooked.','Raw or insufficiently cooked: gastrointestinal upset possible.','If symptoms occur after consumption: call Tox Info Suisse 145.','Edible only when thoroughly cooked, inedible raw. Low culinary value — mostly only as a mixed mushroom. Thin flesh, tough stem; use only the caps.',NULL,false),
('pseudoclitocybe_cyathiformis','es','Sombrero profundamente embudado a acopado, de pardo café a pardo gris, higrófano (más claro en seco). Láminas grises, característicamente bifurcadas y marcadamente decurrentes, esporada blanca. Aparece tarde (finales de otoño a invierno). Posible confusión con el clitocibe embudado gris azulado (P. obbata, olor a almendra amarga/ácido cianhídrico) y con el higróforo enrojecedor. Escaso valor alimentario; comestible solo bien cocinado.','Crudo o insuficientemente cocinado: posibles trastornos gastrointestinales.','En caso de molestias tras la ingesta: llamar a Tox Info Suisse 145.','Comestible solo bien cocinado, no comestible crudo. Escaso valor culinario — sobre todo como hongo de mezcla. Carne delgada, pie coriáceo; usar solo los sombreros.',NULL,false),
('pseudoclitocybe_cyathiformis','fr','Chapeau profondément en entonnoir à cupuliforme, brun café à brun gris, hygrophane (plus clair par temps sec). Lames grises, caractéristiquement fourchues et nettement décurrentes, sporée blanche. Apparaît tardivement (fin de l''automne à l''hiver). Confusion possible avec le clitocybe en entonnoir bleu-gris (P. obbata, odeur d''amande amère/d''acide cyanhydrique) et l''hygrophore rougissant. Faible valeur culinaire ; comestible seulement bien cuit.','Cru ou insuffisamment cuit : troubles gastro-intestinaux possibles.','En cas de troubles après ingestion : appeler Tox Info Suisse au 145.','Comestible seulement bien cuit, immangeable cru. Faible valeur culinaire — surtout comme champignon de mélange. Chair mince, pied coriace ; n''utiliser que les chapeaux.',NULL,false),
('pseudoclitocybe_cyathiformis','it','Cappello profondamente imbutiforme o a coppa, da bruno caffè a bruno grigio, igrofano (più chiaro con tempo asciutto). Lamelle grigie, caratteristicamente forcate e nettamente decorrenti, sporata bianca. Compare tardi (tardo autunno fino all''inverno). Possibile confusione con il clitocibe imbutiforme grigio-azzurro (P. obbata, odore di mandorla amara/acido cianidrico) e con l''igroforo arrossante. Scarso valore alimentare; commestibile solo ben cotto.','Crudo o cotto in modo insufficiente: possibili disturbi gastrointestinali.','In caso di disturbi dopo il consumo: chiamare Tox Info Suisse 145.','Commestibile solo ben cotto, non commestibile crudo. Scarso valore culinario — per lo più solo come fungo da miscela. Carne sottile, gambo coriaceo; usare solo i cappelli.',NULL,false),
('ramaria_formosa','en','Large coral fungus (up to 20 cm), densely and richly branched, with a thick whitish trunk, pale salmon- to orange-pink branches and characteristically yellow branch tips (when young). Bruising/age marks wine-reddish-brown. Flesh bitter when chewed. Spore print OCHRE-YELLOW — an important distinction from the white-spored, edible Clavulina corals.','Acute gastrointestinal syndrome: abdominal pain, nausea, vomiting, often violent diarrhoea, 0.5–3 hours after consumption. In sensitive people more severe courses with fluid/electrolyte loss possible.','If consumption is suspected, call Tox Info Suisse immediately: 145 (24 h, free). Keep mushroom remains/vomit for identification. In case of circulatory weakness, persistent vomiting/diarrhoea or in children, emergency number 144.',NULL,NULL,false),
('ramaria_formosa','es','Gran clavaria (hasta 20 cm), densa y ricamente ramificada, con grueso tronco blanquecino, ramas de rosa salmón pálido a rosa anaranjado y puntas de las ramas característicamente amarillas (de jóvenes). Manchas por presión/envejecimiento de color pardo rojizo vinoso. Carne amarga al masticar. Esporada AMARILLO OCRE — distinción importante respecto a las clavarias Clavulina comestibles de esporas blancas.','Síndrome gastrointestinal agudo: dolores abdominales, náuseas, vómitos, a menudo diarrea violenta, 0,5–3 horas tras el consumo. En personas sensibles, posibles evoluciones más graves con pérdida de líquidos/electrolitos.','En caso de sospecha de consumo, llamar de inmediato a Tox Info Suisse: 145 (24 h, gratuito). Conservar los restos de hongos/el vómito para la identificación. En caso de debilidad circulatoria, vómitos/diarrea persistentes o en niños, número de emergencia 144.',NULL,NULL,false),
('ramaria_formosa','fr','Grande clavaire (jusqu''à 20 cm), densément et richement ramifiée, à épais tronc blanchâtre, rameaux rose saumon pâle à rose orangé et pointes des rameaux caractéristiquement jaunes (jeunes). Taches de pression/d''âge brun-rouge vineux. Chair amère à la mastication. Sporée OCRE JAUNE — distinction importante d''avec les clavaires Clavulina comestibles à spores blanches.','Syndrome gastro-intestinal aigu : douleurs abdominales, nausées, vomissements, souvent diarrhée violente, 0,5 à 3 heures après ingestion. Chez les personnes sensibles, évolutions plus sévères avec pertes hydriques/électrolytiques possibles.','En cas de suspicion d''ingestion, appeler immédiatement Tox Info Suisse : 145 (24 h, gratuit). Conserver les restes de champignons/vomissures pour la détermination. En cas de défaillance circulatoire, de vomissements/diarrhée persistants ou chez les enfants, appeler les secours 144.',NULL,NULL,false),
('ramaria_formosa','it','Grande clavaria (fino a 20 cm), densamente e riccamente ramificata, con tronco spesso biancastro, rami da rosa salmone pallido a rosa arancio e apici dei rami caratteristicamente gialli (da giovani). Macchie da pressione/da invecchiamento bruno-rossastre vinose. Carne amara alla masticazione. Sporata GIALLO OCRA — importante distinzione dalle clavarie Clavulina commestibili a spore bianche.','Sindrome gastrointestinale acuta: dolori addominali, nausea, vomito, spesso diarrea violenta, 0,5–3 ore dopo il consumo. Nelle persone sensibili possibili decorsi più gravi con perdita di liquidi/elettroliti.','In caso di sospetto consumo chiamare subito Tox Info Suisse: 145 (24 h, gratuito). Conservare i resti dei funghi/il vomito per la determinazione. In caso di insufficienza circolatoria, vomito/diarrea persistenti o nei bambini, numero d''emergenza 144.',NULL,NULL,false),
('rhodocollybia_butyracea','en','Cap 3-7 cm, smooth, young chestnut/reddish-brown (var. butyracea) or horn-grey (var. asema), greasy-shiny when moist (hence "buttery cap"), hygrophanous with a paler margin. Stem clavately thickened downwards, longitudinally grooved, cartilaginous-tough, often with whitish felt at the base. Spore print pale pinkish (pink-spored collybia).','Do not eat raw. Low food value; stems tough and floury-bitter, in sensitive people old specimens can cause gastrointestinal upset. Only young caps, thoroughly cooked.',NULL,'Use only young caps (stems tough, discard), cook thoroughly. Low food value, only as a mixed mushroom; the floury taste diminishes the culinary value.',NULL,false),
('rhodocollybia_butyracea','es','Sombrero 3-7 cm, liso, de joven pardo castaño/rojizo (var. butyracea) o gris córneo (var. asema), graso-brillante y untuoso con la humedad (de ahí « colibia mantecosa »), higrófano con margen más claro. Pie engrosado claviforme hacia abajo, estriado longitudinalmente, cartilaginoso-coriáceo, a menudo con fieltro blanquecino en la base. Esporada rosa pálido (colibia de esporas rosas).','No consumir crudo. Escaso valor alimentario; pies coriáceos y harinoso-amargos, en personas sensibles los ejemplares viejos pueden causar trastornos gastrointestinales. Solo los sombreros jóvenes, bien cocinados.',NULL,'Usar solo los sombreros jóvenes (pies coriáceos, desechar), cocinar bien. Escaso valor alimentario, solo como hongo de mezcla; el sabor harinoso reduce el valor culinario.',NULL,false),
('rhodocollybia_butyracea','fr','Chapeau 3-7 cm, lisse, jeune brun châtaigne/rougeâtre (var. butyracea) ou gris corne (var. asema), gras-brillant et graisseux par temps humide (d''où « collybie beurrée »), hygrophane à marge plus claire. Pied claviforme épaissi vers le bas, longitudinalement strié, cartilagineux-coriace, souvent avec un feutrage blanchâtre à la base. Sporée rose pâle (collybie à spores roses).','Ne pas consommer cru. Faible valeur alimentaire ; pieds coriaces et farineux-amers, chez les personnes sensibles de vieux exemplaires peuvent provoquer des troubles gastro-intestinaux. Seulement les jeunes chapeaux, bien cuits.',NULL,'N''utiliser que les jeunes chapeaux (pieds coriaces, à jeter), bien cuire. Faible valeur alimentaire, seulement comme champignon de mélange ; le goût farineux diminue la valeur culinaire.',NULL,false),
('rhodocollybia_butyracea','it','Cappello 3-7 cm, liscio, da giovane bruno castano/rossastro (var. butyracea) o grigio corno (var. asema), untuoso-grasso lucente con l''umidità (da cui « collibia butirrata »), igrofano con margine più chiaro. Gambo clavato ingrossato verso il basso, striato longitudinalmente, cartilagineo-coriaceo, spesso con feltro biancastro alla base. Sporata rosa pallido (collibia a spore rosa).','Non consumare crudo. Scarso valore alimentare; gambi coriacei e farinoso-amarognoli, nelle persone sensibili esemplari vecchi possono causare disturbi gastrointestinali. Solo i cappelli giovani, ben cotti.',NULL,'Usare solo i cappelli giovani (gambi coriacei, da scartare), cuocere bene. Scarso valore alimentare, solo come fungo da miscela; il sapore farinoso riduce il valore culinario.',NULL,false),
('russula_claroflava','en','Medium-sized brittlegill with a brilliant lemon- to chrome-yellow cap (4-10 cm) and a white stem that greys to grey-black with age and when bruised. Flesh mild, smell inconspicuous. Grows typically with birches in damp, acidic bog and swamp woodland. Regarded as a good, mild edible.',NULL,NULL,'Fry or braise young, firm specimens; good in a mixed mushroom dish. Check for maggots.',NULL,false),
('russula_claroflava','es','Rúsula de tamaño medio con sombrero de un amarillo limón a amarillo cromo brillante (4-10 cm) y pie blanco que se vuelve gris a gris negruzco con la edad y al rozarlo. Carne suave, olor poco perceptible. Crece típicamente junto a los abedules en bosques húmedos y ácidos de turbera y de aluvión. Considerada un buen comestible suave.',NULL,NULL,'Saltear o estofar los ejemplares jóvenes y firmes; buena en un salteado de setas variadas. Comprobar la presencia de larvas.',NULL,false),
('russula_claroflava','fr','Russule de taille moyenne au chapeau jaune citron à jaune chrome éclatant (4-10 cm), au pied blanc qui grise jusqu''au gris-noir avec l''âge et au froissement. Chair douce, odeur discrète. Pousse typiquement sous les bouleaux dans les forêts humides et acides de marais et de tourbières. Considérée comme un bon comestible doux.',NULL,NULL,'Faire revenir ou étuver les jeunes exemplaires fermes ; bon dans un mélange de champignons. Vérifier la présence de vers.',NULL,false),
('russula_claroflava','it','Russula di taglia media con cappello giallo limone a giallo cromo brillante (4-10 cm), gambo bianco che ingrigisce fino al grigio-nero con l''età e alla manipolazione. Carne dolce, odore poco evidente. Cresce tipicamente presso le betulle in boschi umidi e acidi di palude e torbiera. Considerata un buon commestibile dolce.',NULL,NULL,'Saltare o stufare gli esemplari giovani e sodi; ottima in un misto di funghi. Controllare la presenza di larve.',NULL,false),
('russula_decolorans','en','Medium-sized brittlegill with an orange-red to brick-red cap (up to 12 cm). Characteristic: the white flesh and the stem grey markedly, to grey-blackish, when bruised and with age. Mild, odourless, a very good edible of damp, acidic conifer forests and bog margins.',NULL,NULL,'Fry or braise young firm specimens; a very good mild edible. The greying of the flesh is normal and harmless.',NULL,false),
('russula_decolorans','es','Rúsula de tamaño medio con sombrero rojo anaranjado a rojo ladrillo (hasta 12 cm). Característica: la carne blanca y el pie se vuelven claramente grises, hasta gris negruzco, al rozarlos y con la edad. Suave, inodora, muy buen comestible de los bosques de coníferas húmedos y ácidos y de los bordes de turbera.',NULL,NULL,'Saltear o estofar los ejemplares jóvenes y firmes; muy buen comestible suave. El agrisamiento de la carne es normal e inofensivo.',NULL,false),
('russula_decolorans','fr','Russule de taille moyenne au chapeau rouge orangé à rouge brique (jusqu''à 12 cm). Caractéristique : la chair blanche et le pied grisent nettement, jusqu''au gris-noirâtre, au froissement et avec l''âge. Douce, inodore, très bon comestible des forêts de conifères humides et acides et des bordures de tourbières.',NULL,NULL,'Faire revenir ou étuver les jeunes exemplaires fermes ; très bon comestible doux. Le grisonnement de la chair est normal et sans danger.',NULL,false),
('russula_decolorans','it','Russula di taglia media con cappello rosso aranciato a rosso mattone (fino a 12 cm). Caratteristica: la carne bianca e il gambo ingrigiscono nettamente, fino al grigio-nerastro, alla manipolazione e con l''età. Dolce, inodore, ottimo commestibile dei boschi di conifere umidi e acidi e dei margini di torbiera.',NULL,NULL,'Saltare o stufare gli esemplari giovani e sodi; ottimo commestibile dolce. L''ingrigimento della carne è normale e innocuo.',NULL,false),
('russula_foetens','en','Large, robust brittlegill with an ochre-brown, slimy cap, strongly grooved at the margin. Striking is the disgusting rancid-oily smell and the acrid, scratchy taste. Gills often with brownish spots and droplets. Inedible - acrid and foul-smelling, irritating to the stomach when raw.','Raw or in quantity: gastrointestinal irritation (nausea, vomiting) from acrid compounds; not life-threatening, but inedible.',NULL,NULL,NULL,false),
('russula_foetens','es','Rúsula grande y robusta con sombrero pardo ocre, viscoso, fuertemente estriado en el margen. Llamativos el olor desagradable rancio y aceitoso y el sabor picante y áspero. Láminas a menudo con manchas pardas y gotitas. No comestible - picante y maloliente, irritante para el estómago en crudo.','Cruda o en cantidad: irritación gastrointestinal (náuseas, vómitos) por las sustancias picantes; no mortal, pero no comestible.',NULL,NULL,NULL,false),
('russula_foetens','fr','Grande russule robuste au chapeau brun ocre, visqueux, fortement cannelé au bord. Odeur désagréable rance et huileuse et saveur âcre et râpeuse marquées. Lames souvent tachées de brun et porteuses de gouttelettes. Non comestible - âcre et nauséabonde, irritante pour l''estomac à l''état cru.','Cru ou en quantité : irritation gastro-intestinale (nausées, vomissements) due aux substances âcres ; non mortel, mais non comestible.',NULL,NULL,NULL,false),
('russula_foetens','it','Grande russula robusta con cappello bruno ocra, viscido, fortemente striato al margine. Spiccati l''odore sgradevole rancido-oleoso e il sapore piccante e raschiante. Lamelle spesso macchiate di bruno e con goccioline. Non commestibile - piccante e maleodorante, irritante per lo stomaco da cruda.','Cruda o in quantità: irritazione gastrointestinale (nausea, vomito) dovuta alle sostanze piccanti; non pericolosa per la vita, ma non commestibile.',NULL,NULL,NULL,false),
('russula_integra','en','Medium-sized to large mountain-forest brittlegill with a brown to red-brown cap, often with purple/olive tones. Stem white, firm. Strong ochre-yellow spore print. Mild and nutty, a prized edible of montane conifer forests. The egg-yellow mature gills are characteristic.',NULL,NULL,'Fry or braise young firm caps; a good mild edible, also for mixed dishes.',NULL,false),
('russula_integra','es','Rúsula de bosque de montaña, de tamaño medio a grande, con sombrero pardo a pardo rojizo, a menudo con tonos purpúreos/oliváceos. Pie blanco, firme. Esporada de un amarillo ocre intenso. Suave y a avellana, comestible apreciado de los bosques montanos de coníferas. Características las láminas maduras de color amarillo yema.',NULL,NULL,'Saltear o estofar los sombreros jóvenes y firmes; buen comestible suave, también para platos variados.',NULL,false),
('russula_integra','fr','Russule de forêt de montagne, de taille moyenne à grande, au chapeau brun à brun-rouge, souvent à tons pourpres/olive. Pied blanc, ferme. Sporée jaune ocre soutenu. Douce et noisetée, comestible apprécié des forêts montagnardes de conifères. Lames mûres jaune d''oeuf caractéristiques.',NULL,NULL,'Faire revenir ou étuver les jeunes chapeaux fermes ; bon comestible doux, aussi pour les plats mélangés.',NULL,false),
('russula_integra','it','Russula dei boschi montani, di taglia media o grande, con cappello bruno a bruno-rossastro, spesso con toni purpurei/olivastri. Gambo bianco, sodo. Sporata giallo ocra carico. Dolce e nocciolata, commestibile apprezzato delle foreste montane di conifere. Caratteristiche le lamelle mature giallo tuorlo.',NULL,NULL,'Saltare o stufare i giovani cappelli sodi; buon commestibile dolce, anche per piatti misti.',NULL,false),
('russula_nigricans','en','Robust brittlegill with strikingly thick, widely spaced, fleshy gills. The flesh reddens when cut and then blackens strongly; the whole mushroom turns coal-black with age. Only very young, firm specimens are conditionally edible - older ones and the entire ''blackening brittlegill'' aggregate must be treated with caution because of poor digestibility and the risk of confusion with R. subnigricans, which is deadly in East Asia (rhabdomyolysis).','Raw or insufficiently cooked / older fruit bodies: gastrointestinal complaints (nausea, diarrhoea). R. nigricans itself contains no known lethal toxins, but the blackening-brittlegill aggregate is classed cautiously across the board because of the risk of confusion with the muscle-damaging R. subnigricans.','For persistent complaints after eating, or suspected confusion with a blackening brittlegill: call Tox Info Suisse 145, keep mushroom remains/a spore print for identification.','Use only very young, firm, pale-fleshed specimens; cook thoroughly. When in doubt, and with all blackening brittlegills, better avoid.',NULL,false),
('russula_nigricans','es','Rúsula robusta con láminas llamativamente gruesas, separadas y carnosas. La carne enrojece al corte y luego ennegrece intensamente; el hongo entero se vuelve negro carbón con la edad. Solo los ejemplares muy jóvenes y firmes son comestibles con reservas - los más viejos y todo el agregado de la « rúsula ennegreciente » deben tratarse con precaución por su mala digestibilidad y el riesgo de confusión con R. subnigricans, mortal en Asia oriental (rabdomiólisis).','Crudos o poco cocinados / carpóforos viejos: molestias gastrointestinales (náuseas, diarrea). R. nigricans en sí no contiene toxinas letales conocidas, pero el agregado de las rúsulas ennegrecientes se clasifica de forma genéricamente prudente por el riesgo de confusión con R. subnigricans, dañina para los músculos.','En caso de molestias persistentes tras el consumo o de sospecha de confusión con una rúsula ennegreciente: llamar a Tox Info Suisse 145, conservar los restos del hongo/la esporada para la identificación.','Usar solo ejemplares muy jóvenes, firmes y de carne clara; cocinar bien a fondo. En caso de duda, y con todas las rúsulas ennegrecientes, mejor evitar.',NULL,false),
('russula_nigricans','fr','Russule robuste aux lames remarquablement épaisses, espacées et charnues. La chair rougit à la coupe puis noircit fortement ; le champignon entier devient noir de charbon avec l''âge. Seuls les très jeunes exemplaires fermes sont comestibles sous conditions - les plus âgés et tout l''agrégat de la « russule noircissante » sont à manipuler avec prudence en raison de leur mauvaise digestibilité et du risque de confusion avec R. subnigricans, mortelle en Asie de l''Est (rhabdomyolyse).','Crus ou insuffisamment cuits / fructifications âgées : troubles gastro-intestinaux (nausées, diarrhée). R. nigricans elle-même ne contient pas de toxine létale connue, mais l''agrégat des russules noircissantes est classé globalement avec prudence en raison du risque de confusion avec R. subnigricans, toxique pour les muscles.','En cas de troubles persistants après ingestion ou de suspicion de confusion avec une russule noircissante : appeler Tox Info Suisse 145, conserver les restes de champignon/la sporée pour la détermination.','N''utiliser que les exemplaires très jeunes, fermes et à chair claire ; bien cuire à coeur. Dans le doute et pour toutes les russules noircissantes, mieux vaut s''abstenir.',NULL,false),
('russula_nigricans','it','Russula robusta con lamelle notevolmente spesse, distanziate e carnose. La carne arrossa al taglio e poi annerisce fortemente; l''intero fungo diventa nero carbone con l''età. Solo gli esemplari molto giovani e sodi sono commestibili con riserva - quelli più vecchi e l''intero aggregato della « russula annerente » vanno trattati con prudenza per la cattiva digeribilità e il rischio di confusione con R. subnigricans, mortale in Asia orientale (rabdomiolisi).','Crudi o poco cotti / corpi fruttiferi vecchi: disturbi gastrointestinali (nausea, diarrea). R. nigricans di per sé non contiene tossine letali note, ma l''aggregato delle russule annerenti è classificato genericamente con prudenza per il rischio di confusione con R. subnigricans, dannosa per i muscoli.','In caso di disturbi persistenti dopo il consumo o di sospetta confusione con una russula annerente: chiamare Tox Info Suisse 145, conservare i resti del fungo/la sporata per l''identificazione.','Usare solo esemplari molto giovani, sodi e a carne chiara; cuocere bene a fondo. Nel dubbio e per tutte le russule annerenti, meglio evitare.',NULL,false),
('russula_ochroleuca','en','Common, inconspicuous ochre- to pale-yellow cap (4-10 cm), stem white and greying with age. Taste variable from almost mild to distinctly acrid. Lies on the edible/inedible borderline - acrid specimens are only usable after pre-treatment. Confusion possible with the similarly coloured ochre brittlegill (gall brittlegill).','Acrid specimens, raw or insufficiently cooked, can cause gastrointestinal irritation with nausea (no systemic toxin).',NULL,'Use only mild specimens; for larger amounts blanch briefly (to drive out the acridity). In small amounts as a mixed mushroom. Sort out acrid fruit bodies.',NULL,false),
('russula_ochroleuca','es','Sombrero amarillo ocre a amarillo pálido, discreto y frecuente (4-10 cm), pie blanco que se vuelve gris con la edad. Sabor variable, de casi suave a claramente picante. Se sitúa en el límite entre comestible y no comestible - los ejemplares picantes solo son aprovechables tras un tratamiento previo. Posible confusión con la rúsula de la hiel, de coloración semejante.','Los ejemplares picantes, crudos o poco cocinados, pueden provocar irritación gastrointestinal con náuseas (sin toxina sistémica).',NULL,'Usar solo los ejemplares suaves; en grandes cantidades, escaldar brevemente (para eliminar el picor). En pequeñas cantidades como seta mixta. Descartar los carpóforos picantes.',NULL,false),
('russula_ochroleuca','fr','Chapeau jaune ocre à jaune pâle, discret et fréquent (4-10 cm), pied blanc grisonnant avec l''âge. Saveur variable, de presque douce à nettement âcre. Se situe à la limite comestible/non comestible - les exemplaires âcres ne sont utilisables qu''après prétraitement. Confusion possible avec la russule de fiel, de coloration semblable.','Les exemplaires âcres, crus ou insuffisamment cuits, peuvent provoquer une irritation gastro-intestinale avec nausées (pas de toxine systémique).',NULL,'N''utiliser que les exemplaires doux ; en grande quantité, blanchir brièvement (pour chasser l''âcreté). En petite quantité dans un mélange. Écarter les fructifications âcres.',NULL,false),
('russula_ochroleuca','it','Cappello giallo ocra a giallo pallido, dimesso e frequente (4-10 cm), gambo bianco che ingrigisce con l''età. Sapore variabile, da quasi dolce a nettamente piccante. Si colloca al limite commestibile/non commestibile - gli esemplari piccanti sono utilizzabili solo dopo pretrattamento. Possibile confusione con la russula della bile, di colorazione simile.','Gli esemplari piccanti, crudi o poco cotti, possono causare irritazione gastrointestinale con nausea (nessuna tossina sistemica).',NULL,'Usare solo gli esemplari dolci; in grandi quantità sbollentare brevemente (per eliminare la piccantezza). In piccola quantità come misto. Scartare i corpi fruttiferi piccanti.',NULL,false),
('russula_rosea','en','Firm brittlegill with an intensely vermilion- to pink-red, matt, non-peeling cap cuticle, often blotchily fading to whitish. Very hard, dense flesh and a characteristic smell/taste of pencil wood (cedar wood). Synonyms: R. lepida, R. linnaei. Not poisonous, but inedible owing to its hardness and woody taste.',NULL,NULL,NULL,NULL,false),
('russula_rosea','es','Rúsula firme con cutícula del sombrero rojo bermellón a rosa intenso, mate, no separable, a menudo desvaída en manchas blanquecinas. Carne muy dura y densa, olor/sabor característico a madera de lápiz (madera de cedro). Sinónimos: R. lepida, R. linnaei. No tóxica, pero no comestible por su dureza y su sabor leñoso.',NULL,NULL,NULL,NULL,false),
('russula_rosea','fr','Russule ferme à la cuticule rouge vermillon à rose vif, mate, non séparable, souvent décolorée en taches blanchâtres. Chair très dure et dense, odeur/saveur caractéristique de bois de crayon (bois de cèdre). Synonymes : R. lepida, R. linnaei. Non toxique, mais non comestible en raison de sa dureté et de son goût boisé.',NULL,NULL,NULL,NULL,false),
('russula_rosea','it','Russula soda con cuticola rosso vermiglio a rosa vivo, opaca, non separabile, spesso sbiadita a chiazze biancastre. Carne molto dura e densa, odore/sapore caratteristico di legno di matita (legno di cedro). Sinonimi: R. lepida, R. linnaei. Non tossica, ma non commestibile per la durezza e il sapore legnoso.',NULL,NULL,NULL,NULL,false),
('sarcodon_squamosus','en','Brown-scaled tooth fungus under pines on sandy soil, with large erect cap scales and brown spines instead of gills. Hard to separate from Sarcodon imbricatus (shingled hedgehog), which grows under spruce. Inconsistently/controversially rated as an edible (heterogeneous culinary value per the DGfM list): only very young fruit bodies are mild, older ones bitter; Sarcodon species tend to accumulate heavy metals (including cadmium). It is therefore conservatively listed here as inedible.','No classic mushroom toxin; eating older/bitter specimens or larger amounts may cause gastrointestinal complaints (nausea, diarrhoea). Because of heavy-metal accumulation, regular/large consumption is not recommended.','For persistent gastrointestinal complaints after eating, call Tox Info Suisse: 145 (24h, free). Keep a mushroom remnant for identification.',NULL,NULL,false),
('sarcodon_squamosus','es','Hidno de escamas pardas bajo los pinos en suelo arenoso, con grandes escamas erectas en el sombrero y aguijones pardos en lugar de láminas. Difícil de separar de Sarcodon imbricatus (lengua de vaca escamosa de los abetos rojos), que crece bajo los abetos rojos. Valorado de forma dispar/controvertida como comestible (valor culinario heterogéneo según la lista DGfM): solo los carpóforos muy jóvenes son suaves, los más viejos amargos; las especies de Sarcodon tienden a acumular metales pesados (entre ellos cadmio). Por ello se clasifica aquí de forma conservadora como no comestible.','Sin toxina fúngica clásica; el consumo de ejemplares viejos/amargos o de grandes cantidades puede causar molestias gastrointestinales (náuseas, diarrea). Por la acumulación de metales pesados no se recomienda un consumo regular/abundante.','En caso de molestias gastrointestinales persistentes tras el consumo, llamar a Tox Info Suisse: 145 (24h, gratuito). Conservar un resto del hongo para la identificación.',NULL,NULL,false),
('sarcodon_squamosus','fr','Hydne à écailles brunes sous les pins sur sol sableux, à grandes écailles dressées sur le chapeau et à aiguillons bruns au lieu de lames. Difficile à séparer de Sarcodon imbricatus (hydne imbriqué des épicéas), qui pousse sous les épicéas. Évalué de façon inégale/controversée comme comestible (valeur culinaire hétérogène selon la liste DGfM) : seules les très jeunes fructifications sont douces, les plus âgées amères ; les espèces de Sarcodon tendent à accumuler des métaux lourds (notamment du cadmium). De ce fait, classé ici de manière conservatrice comme non comestible.','Pas de toxine fongique classique ; la consommation d''exemplaires âgés/amers ou de grandes quantités peut entraîner des troubles gastro-intestinaux (nausées, diarrhée). En raison de l''accumulation de métaux lourds, une consommation régulière/importante n''est pas recommandée.','En cas de troubles gastro-intestinaux persistants après ingestion, appeler Tox Info Suisse : 145 (24h, gratuit). Conserver un reste de champignon pour la détermination.',NULL,NULL,false),
('sarcodon_squamosus','it','Idno a squame brune sotto i pini su suolo sabbioso, con grandi squame erette sul cappello e aculei bruni al posto delle lamelle. Difficile da separare da Sarcodon imbricatus (idno embricato degli abeti rossi), che cresce sotto gli abeti rossi. Valutato in modo disomogeneo/controverso come commestibile (valore culinario eterogeneo secondo la lista DGfM): solo i corpi fruttiferi molto giovani sono dolci, quelli più vecchi amari; le specie di Sarcodon tendono ad accumulare metalli pesanti (tra cui cadmio). Per questo qui è classificato in modo conservativo come non commestibile.','Nessuna tossina fungina classica; il consumo di esemplari vecchi/amari o di grandi quantità può causare disturbi gastrointestinali (nausea, diarrea). A causa dell''accumulo di metalli pesanti non è raccomandato un consumo regolare/abbondante.','In caso di disturbi gastrointestinali persistenti dopo il consumo, chiamare Tox Info Suisse: 145 (24h, gratuito). Conservare un resto del fungo per l''identificazione.',NULL,NULL,false),
('sarcoscypha_austriaca','en','Brilliant scarlet, cup- to bowl-shaped fruit bodies in winter/early spring on rotting hardwood lying on the ground. Inner surface intensely red, outer surface whitish and felty-hairy. Separated from S. coccinea microscopically by hair shape and spore features. Shortly stalked or sessile.',NULL,NULL,NULL,NULL,false),
('sarcoscypha_austriaca','es','Carpóforos de un rojo escarlata brillante, en forma de copa a cuenco, en invierno/principios de primavera sobre madera de frondosa en descomposición tumbada en el suelo. Cara interna de un rojo intenso, cara externa blanquecina y afieltrada-pelosa. Se separa de S. coccinea al microscopio por la forma de los pelos y los caracteres esporales. Brevemente estipitada o sésil.',NULL,NULL,NULL,NULL,false),
('sarcoscypha_austriaca','fr','Fructifications d''un rouge écarlate éclatant, en forme de coupe à bol, en hiver/début de printemps sur du bois feuillu pourrissant gisant au sol. Face interne d''un rouge intense, face externe blanchâtre et feutrée-poilue. Se distingue de S. coccinea au microscope par la forme des poils et les caractères sporaux. Courtement stipitée ou sessile.',NULL,NULL,NULL,NULL,false),
('sarcoscypha_austriaca','it','Corpi fruttiferi di un rosso scarlatto brillante, a forma di coppa o scodella, in inverno/inizio primavera su legno di latifoglia marcescente adagiato al suolo. Faccia interna di un rosso intenso, faccia esterna biancastra e feltrata-pelosa. Si distingue da S. coccinea al microscopio per la forma dei peli e i caratteri sporali. Brevemente stipitata o sessile.',NULL,NULL,NULL,NULL,false),
('strobilomyces_strobilaceus','en','Unmistakable through coarse, protruding, grey-black, cone-like (fir-cone/pine-cone-like) scales on the cap and a fringed cap margin. When young with a thick, grey, woolly veil whose remnants persist as a ring on the stem. Flesh whitish, reddening when cut, then blackening. Spore print black. In Europe practically unmistakable.',NULL,NULL,'Use only very young, soft-fleshed specimens; culinary value disputed/low, older ones tough and partly bitter. Cook thoroughly. Overall an inferior edible, often only as a mixed mushroom.',NULL,false),
('strobilomyces_strobilaceus','es','Inconfundible por las escamas gruesas, sobresalientes, gris-negras, en forma de cono (semejantes a piñas de abeto/de pino) sobre el sombrero y por el margen flecoso del sombrero. De joven con un velo grueso, gris y lanoso, cuyos restos persisten como anillo en el pie. Carne blanquecina, enrojeciente al corte y luego ennegreciente. Esporada negra. En Europa prácticamente inconfundible.',NULL,NULL,'Usar solo los ejemplares muy jóvenes de carne tierna; valor culinario discutido/escaso, los más viejos son correosos y en parte amargos. Cocinar bien a fondo. En conjunto, comestible de baja calidad, a menudo solo como seta mixta.',NULL,false),
('strobilomyces_strobilaceus','fr','Reconnaissable sans confusion à ses écailles grossières, dressées, gris-noir, en forme de cônes (rappelant les pommes de pin/de sapin) sur le chapeau et à la marge frangée. Jeune, avec un voile épais, gris et laineux, dont les restes subsistent en anneau sur le pied. Chair blanchâtre, rougissant à la coupe puis noircissant. Sporée noire. En Europe, pratiquement impossible à confondre.',NULL,NULL,'N''utiliser que les très jeunes exemplaires à chair tendre ; valeur culinaire discutée/faible, les plus âgés sont coriaces et en partie amers. Bien cuire à coeur. Dans l''ensemble, comestible médiocre, souvent seulement en mélange.',NULL,false),
('strobilomyces_strobilaceus','it','Inconfondibile per le grosse squame ispide, sporgenti, grigio-nere, a forma di cono (simili a pigne di pino/abete) sul cappello e per il margine frangiato. Da giovane con velo spesso, grigio e lanoso, i cui resti rimangono ad anello sul gambo. Carne biancastra, arrossante al taglio e poi annerente. Sporata nera. In Europa praticamente inconfondibile.',NULL,NULL,'Usare solo gli esemplari molto giovani a carne tenera; valore culinario discusso/scarso, quelli più vecchi sono coriacei e in parte amari. Cuocere bene a fondo. Nel complesso commestibile scadente, spesso solo come misto.',NULL,false),
('suillus_collinitus','en','Cap slimy-glossy (a slippery bolete), chestnut to red-brown, often with dark radial ingrown fibrils. NO ring on the stem (difference from the ringed slippery jack S. luteus). Stem with fine reddish granules/glandular dots; stem base with pink/reddish basal mycelium (important feature). Pores yellow, fine.','Toxic/indigestible raw; in sensitive people the slimy cap skin can cause gastrointestinal complaints and diarrhoea even after cooking.',NULL,'Before cooking, the slimy cap skin must be peeled off (otherwise it causes gastrointestinal complaints and acts as a mild laxative). Never eat raw. Cook thoroughly, enjoy in moderation; sensitive people may react even when prepared.',NULL,false),
('suillus_collinitus','es','Sombrero viscoso-brillante (boleto viscoso), pardo castaño a pardo-rojizo, a menudo con fibrillas radiales oscuras incrustadas. SIN anillo en el pie (diferencia respecto al boleto anillado S. luteus). Pie con finas granulaciones/puntos glandulares rojizos; base del pie con micelio basal rosa/rojizo (carácter importante). Poros amarillos, finos.','Tóxico/indigesto en crudo; la cutícula viscosa puede, incluso tras la cocción, provocar molestias gastrointestinales y diarrea en personas sensibles.',NULL,'Antes de cocinar, retirar imprescindiblemente la cutícula mucosa del sombrero (de lo contrario provoca molestias gastrointestinales y actúa como laxante suave). Nunca consumir crudo. Cocer bien y a fondo, consumir con moderación; las personas sensibles pueden reaccionar incluso preparado.',NULL,false),
('suillus_collinitus','fr','Chapeau visqueux-luisant (bolet à chair molle/visqueux), brun châtain à brun-rouge, souvent à fibrilles radiales sombres incrustées. PAS d''anneau sur le pied (différence avec le bolet jaune annelé S. luteus). Pied couvert de fines granulations/points glanduleux rougeâtres ; base du pied à mycélium basal rose/rougeâtre (caractère important). Pores jaunes, fins.','Toxique/indigeste cru ; la cuticule visqueuse peut, même après cuisson, provoquer des troubles gastro-intestinaux et des diarrhées chez les personnes sensibles.',NULL,'Avant la cuisson, retirer impérativement la cuticule muqueuse du chapeau (sinon troubles gastro-intestinaux, effet légèrement laxatif). Ne jamais consommer cru. Bien cuire entièrement, consommer avec modération ; les personnes sensibles peuvent réagir même après préparation.',NULL,false),
('suillus_collinitus','it','Cappello viscido-lucido (boleto viscido), bruno castano fino a bruno-rosso, spesso con fibrille scure radiali incrostate. NESSUN anello sul gambo (differenza rispetto al boleto giallo anellato S. luteus). Gambo con fini granulazioni/punti ghiandolari rossastri; base del gambo con micelio basale rosa/rossastro (carattere importante). Pori gialli, fini.','Tossico/indigesto crudo; la cuticola viscida può, anche dopo la cottura, causare disturbi gastrointestinali e diarrea nelle persone sensibili.',NULL,'Prima della cottura asportare assolutamente la cuticola mucosa del cappello (altrimenti disturbi gastrointestinali, effetto lievemente lassativo). Mai consumare crudo. Cuocere bene e a fondo, consumare con moderazione; le persone sensibili possono reagire anche dopo la preparazione.',NULL,false),
('trametes_hirsuta','en','Bracket-shaped, zoned grey-whitish fruiting body whose upper surface is strigose-hairy (hirsute) — hence the name. Concentrically furrowed and zoned. Corky-tough, inedible. Confusion possible with the turkey tail (T. versicolor, more vividly coloured) and other Trametes/Daedaleopsis.',NULL,NULL,NULL,NULL,false),
('trametes_hirsuta','es','Cuerpo fructífero en forma de ménsula, zonado gris-blanquecino, cuya superficie superior es estrigosa-hirsuta (hirsuta) — de ahí el nombre. Concéntricamente surcado y zonado. Suberoso-correoso, no comestible. Posible confusión con la cola de pavo (T. versicolor, de colores más vivos) y con otros Trametes/Daedaleopsis.',NULL,NULL,NULL,NULL,false),
('trametes_hirsuta','fr','Carpophore en console, zoné gris-blanchâtre, dont la face supérieure est strigueuse-hérissée (hirsute) — d''où le nom. Concentriquement sillonné et zoné. Subéreux-coriace, non comestible. Confusion possible avec le tramète versicolore (T. versicolor, aux couleurs plus vives) et d''autres tramètes/Daedaleopsis.',NULL,NULL,NULL,NULL,false),
('trametes_hirsuta','it','Corpo fruttifero a mensola, zonato grigio-biancastro, con la superficie superiore strigosa-irsuta (hirsuta) — da cui il nome. Concentricamente solcato e zonato. Suberoso-coriaceo, non commestibile. Possibile confusione con il tramete versicolore (T. versicolor, dai colori più vivaci) e con altri trameti/Daedaleopsis.',NULL,NULL,NULL,NULL,false),
('tricholoma_cingulatum','en','Grey, finely fibrillose cap, mealy smell, distinct membranous ring on the stem (hence the name, unique among the grey earthy knights) and obligate mycorrhiza with willows (more rarely birches) at damp sites. The ring + the willow association are the key distinguishing features. CAUTION: edible only if the ring is unquestionably present and the site is under willow; otherwise confusion with the toxic grey knights (T. terreum complex) and the deadly tiger knight.',NULL,NULL,'Edible, but of low culinary value. Cook thoroughly, in small amounts as a mixed mushroom. Use only after certain identification (ring + willow site). Protected/rare in some regions — preserve rather than collect.',NULL,false),
('tricholoma_cingulatum','es','Sombrero gris, finamente fibriloso, olor harinoso, anillo membranoso neto en el pie (de ahí el nombre, único entre los tricolomas terrosos grises) y micorriza obligada con sauces (más raramente abedules) en estaciones húmedas. El anillo + la asociación con sauces son los principales caracteres distintivos. ATENCIÓN: comestible solo si el anillo está presente sin ninguna duda y la estación es bajo sauce; de lo contrario, confusión con los tricolomas grises tóxicos (complejo T. terreum) y con el tricoloma atigrado mortal.',NULL,NULL,'Comestible, pero de escaso valor gustativo. Cocer bien y a fondo, en pequeñas cantidades como seta de mezcla. Utilizar solo tras determinación segura (anillo + estación bajo sauce). Protegido/raro en algunas regiones — preservar en lugar de recolectar.',NULL,false),
('tricholoma_cingulatum','fr','Chapeau gris, finement fibrilleux, odeur farineuse, anneau membraneux net sur le pied (d''où le nom, unique parmi les tricholomes terreux gris) et mycorhize obligatoire avec les saules (plus rarement bouleaux) en stations humides. L''anneau + le lien aux saules sont les principaux caractères distinctifs. ATTENTION : comestible uniquement si l''anneau est présent sans aucun doute et si la station est sous saule ; sinon confusion avec les tricholomes gris toxiques (complexe T. terreum) et le tricholome tigré mortel.',NULL,NULL,'Comestible, mais de faible valeur gustative. Bien cuire entièrement, en petites quantités comme champignon d''accompagnement. À n''utiliser qu''après détermination certaine (anneau + station sous saule). Protégé/rare dans certaines régions — préserver plutôt que cueillir.',NULL,false),
('tricholoma_cingulatum','it','Cappello grigio, finemente fibrilloso, odore farinoso, anello membranoso netto sul gambo (da cui il nome, unico tra i tricolomi terrosi grigi) e micorriza obbligata con i salici (più raramente betulle) in stazioni umide. L''anello + il legame con i salici sono i principali caratteri distintivi. ATTENZIONE: commestibile solo se l''anello è presente senza alcun dubbio e la stazione è sotto salice; altrimenti confusione con i tricolomi grigi tossici (complesso T. terreum) e con il tricoloma tigrato mortale.',NULL,NULL,'Commestibile, ma di scarso valore gustativo. Cuocere bene e a fondo, in piccole quantità come fungo da misto. Da utilizzare solo dopo determinazione certa (anello + stazione sotto salice). Protetto/raro in alcune regioni — preservare anziché raccogliere.',NULL,false),
('tricholoma_imbricatum','en','Red-brown to hazel-brown cap with a dry, felty-fibrillose surface that breaks up into fine scales (hence the name), cap margin not woolly-bearded (difference from T. vaccinum). White, slightly browning flesh. Under pines/spruces on acidic soil. Hard to digest, many experts advise against it — therefore inedible (no cooking remedies the intolerance).','Not actually toxic, but hard to digest; if eaten, gastrointestinal upset/intolerance possible. Downgraded from ''conditionally edible'', since no cooking removes the intolerance.',NULL,NULL,NULL,false),
('tricholoma_imbricatum','es','Sombrero pardo-rojizo a pardo avellana con superficie seca, afieltrada-fibrilosa, que se resquebraja en finas escamas (de ahí el nombre), margen del sombrero no lanoso-barbado (diferencia respecto a T. vaccinum). Carne blanca, ligeramente pardeante. Bajo pinos/abetos en suelo ácido. Difícil de digerir, muchos expertos lo desaconsejan — por tanto no comestible (ninguna cocción corrige la intolerancia).','No propiamente tóxico, pero difícil de digerir; si se consume, posibles molestias gastrointestinales/intolerancia. Rebajado respecto a «comestible con reservas», ya que ninguna cocción elimina la intolerancia.',NULL,NULL,NULL,false),
('tricholoma_imbricatum','fr','Chapeau brun-rouge à brun noisette, à surface sèche, feutrée-fibrilleuse, se craquelant en fines écailles (d''où le nom), bord du chapeau non laineux-barbu (différence avec T. vaccinum). Chair blanche brunissant légèrement. Sous pins/épicéas sur sol acide. Difficile à digérer, de nombreux experts le déconseillent — donc non comestible (aucune cuisson ne corrige l''intolérance).','Pas réellement toxique, mais difficile à digérer ; consommé, troubles gastro-intestinaux/intolérance possibles. Déclassé par rapport à « comestible sous conditions », car aucune cuisson ne supprime l''intolérance.',NULL,NULL,NULL,false),
('tricholoma_imbricatum','it','Cappello da bruno-rosso a bruno nocciola, con superficie asciutta, feltrosa-fibrillosa, che si screpola in fini squame (da cui il nome), margine del cappello non lanoso-barbato (differenza rispetto a T. vaccinum). Carne bianca leggermente imbrunente. Sotto pini/abeti rossi su suolo acido. Di difficile digestione, molti esperti lo sconsigliano — quindi non commestibile (nessuna cottura corregge l''intolleranza).','Non propriamente tossico, ma di difficile digestione; se consumato, possibili disturbi gastrointestinali/intolleranza. Declassato rispetto a «commestibile con riserva», poiché nessuna cottura elimina l''intolleranza.',NULL,NULL,NULL,false),
('tricholoma_populinum','en','Smooth, red-brown to brown cap, often sticky, mealy smell, white flesh, growing in clusters/rows strictly under poplars (mycorrhiza). Edibility is disputed — most authors classify it as inedible. EXTREME risk of confusion with other brown deciduous-woodland knights, some of which are markedly more toxic; the whole group of brown knights is therefore discouraged.','Itself has no known strong toxin, but rated as inedible/of poor quality and easily confused with more toxic brown knights. If eaten (including through confusion), gastrointestinal complaints possible.',NULL,NULL,NULL,false),
('tricholoma_populinum','es','Sombrero liso, pardo-rojizo a pardo, a menudo pegajoso, olor harinoso, carne blanca, crecimiento en grupos/hileras estrictamente bajo álamos (micorriza). La comestibilidad es controvertida — la mayoría de los autores lo clasifican como no comestible. Riesgo EXTREMO de confusión con otros tricolomas pardos de bosque caducifolio, algunos de ellos claramente más tóxicos; por ello se desaconseja todo el grupo de los tricolomas pardos.','En sí mismo sin toxina fuerte conocida, pero evaluado como no comestible/de escasa calidad y fácilmente confundible con tricolomas pardos más tóxicos. Si se consume (también por confusión), posibles molestias gastrointestinales.',NULL,NULL,NULL,false),
('tricholoma_populinum','fr','Chapeau lisse, brun-rouge à brun, souvent visqueux, odeur farineuse, chair blanche, croissance en touffes/rangées strictement sous les peupliers (mycorhize). La comestibilité est controversée — la plupart des auteurs le classent comme non comestible. Risque EXTRÊME de confusion avec d''autres tricholomes bruns des feuillus, dont certains sont nettement plus toxiques ; tout le groupe des tricholomes bruns est donc déconseillé.','Lui-même sans toxine forte connue, mais évalué comme non comestible/de faible qualité et facilement confondu avec des tricholomes bruns plus toxiques. Consommé (y compris par confusion), troubles gastro-intestinaux possibles.',NULL,NULL,NULL,false),
('tricholoma_populinum','it','Cappello liscio, da bruno-rosso a bruno, spesso vischioso, odore farinoso, carne bianca, crescita in ciuffi/file strettamente sotto i pioppi (micorriza). La commestibilità è controversa — la maggior parte degli autori lo classifica come non commestibile. Rischio ESTREMO di confusione con altri tricolomi bruni di latifoglie, alcuni dei quali nettamente più tossici; l''intero gruppo dei tricolomi bruni è perciò sconsigliato.','Di per sé senza alcuna tossina forte nota, ma valutato come non commestibile/di scarsa qualità e facilmente confondibile con tricolomi bruni più tossici. Se consumato (anche per confusione), possibili disturbi gastrointestinali.',NULL,NULL,NULL,false),
('tricholoma_scalpturatum','en','Silvery-grey to grey-brown, finely fibrillose to scaly cap, mealy smell, flesh and gills yellowing with age/on injury (hence the name). Belongs to the group of grey earthy knights (T. terreum complex), now regarded as toxic. Dangerous confusion with the deadly tiger knight (Tricholoma pardinum).','Grey earthy knights of the T. terreum complex are now linked to rhabdomyolysis toxins (saponaceolides); in addition, gastrointestinal complaints. Owing to the toxicological reassessment and the extreme risk of confusion with the deadly tiger knight, classified as toxic (more cautious default).','If suspected, call Tox Info Suisse 145 immediately (24h). Keep mushroom remains. In case of muscle pain/dark urine (sign of rhabdomyolysis) or persistent vomiting/diarrhoea, go to the emergency department without delay.',NULL,NULL,false),
('tricholoma_scalpturatum','es','Sombrero gris plateado a gris-pardo, finamente fibriloso a escamoso, olor harinoso, carne y láminas amarillean con la edad/al herirse (de ahí el nombre). Pertenece al grupo de los tricolomas terrosos grises (complejo T. terreum), hoy considerado tóxico. Peligrosa confusión con el tricoloma atigrado mortal (Tricholoma pardinum).','Los tricolomas terrosos grises del complejo T. terreum se asocian ahora con toxinas causantes de rabdomiólisis (saponaceólidos); además, molestias gastrointestinales. Debido a la reevaluación toxicológica y al extremo riesgo de confusión con el tricoloma atigrado mortal, clasificado como tóxico (criterio más prudente).','En caso de sospecha, llamar de inmediato a Tox Info Suisse 145 (24h). Conservar los restos de setas. En caso de dolores musculares/orina oscura (indicio de rabdomiólisis) o de vómitos/diarrea persistentes, acudir a urgencias sin demora.',NULL,NULL,false),
('tricholoma_scalpturatum','fr','Chapeau gris argenté à gris-brun, finement fibrilleux à squameux, odeur farineuse, chair et lamelles jaunissant avec l''âge/à la blessure (d''où le nom). Appartient au groupe des tricholomes terreux gris (complexe T. terreum), aujourd''hui considéré comme toxique. Confusion dangereuse avec le tricholome tigré mortel (Tricholoma pardinum).','Les tricholomes terreux gris du complexe T. terreum sont désormais associés à des toxines provoquant une rhabdomyolyse (saponacéolides) ; en outre, troubles gastro-intestinaux. En raison de la réévaluation toxicologique et de l''extrême risque de confusion avec le tricholome tigré mortel, classé comme toxique (défaut prudent).','En cas de suspicion, appeler immédiatement Tox Info Suisse 145 (24h). Conserver les restes de champignons. En cas de douleurs musculaires/urine foncée (signe de rhabdomyolyse) ou de vomissements/diarrhées persistants, urgences sans délai.',NULL,NULL,false),
('tricholoma_scalpturatum','it','Cappello da grigio argenteo a grigio-bruno, finemente fibrilloso fino a squamoso, odore farinoso, carne e lamelle ingialliscono con l''età/alla lesione (da cui il nome). Appartiene al gruppo dei tricolomi terrosi grigi (complesso T. terreum), oggi considerato tossico. Pericolosa confusione con il tricoloma tigrato mortale (Tricholoma pardinum).','I tricolomi terrosi grigi del complesso T. terreum vengono ora associati a tossine che provocano rabdomiolisi (saponaceolidi); inoltre disturbi gastrointestinali. A causa della rivalutazione tossicologica e dell''estremo rischio di confusione con il tricoloma tigrato mortale, classificato come tossico (default prudenziale).','In caso di sospetto chiamare immediatamente Tox Info Suisse 145 (24h). Conservare i resti dei funghi. In caso di dolori muscolari/urina scura (segno di rabdomiolisi) o di vomito/diarrea persistenti, pronto soccorso senza indugio.',NULL,NULL,false),
('tricholoma_ustale','en','Cap surface sticky-slimy when moist, red-brown to chestnut-brown, often with a darker ''burnt'' centre. Gills whitish, spotting rust-brown with age. Under beeches and oaks on acidic soil. Confusion with edible brown knights is the main route of poisoning.','Gastrointestinal symptoms (nausea, vomiting, diarrhoea) 1-6 hours after eating, through inhibition of the Na+/K+-ATPase in the intestinal epithelium (osmotic diarrhoea). Self-limiting, usually subsiding within 24-48 hours; no fatalities documented to date.','If suspected, call Tox Info Suisse 145 immediately (24h). Keep mushroom remains/cleaning waste for identification. In case of vomiting/diarrhoea, ensure adequate fluid intake. For children, the elderly or weakened persons, seek medical evaluation.',NULL,NULL,false),
('tricholoma_ustale','es','Superficie del sombrero pegajosa-viscosa con humedad, pardo-rojiza a pardo castaña, a menudo con el centro más oscuro «quemado». Láminas blanquecinas, manchándose de pardo herrumbroso con la edad. Bajo hayas y robles en suelo ácido. La confusión con tricolomas pardos comestibles es la principal vía de intoxicación.','Síntomas gastrointestinales (náuseas, vómitos, diarrea) 1-6 horas tras la ingesta, por inhibición de la Na+/K+-ATPasa del epitelio intestinal (diarrea osmótica). Autolimitado, normalmente remite en 24-48 horas; hasta la fecha ningún fallecimiento documentado.','En caso de sospecha, llamar de inmediato a Tox Info Suisse 145 (24h). Conservar los restos/desechos de limpieza para la determinación. En caso de vómitos/diarrea, asegurar un aporte suficiente de líquidos. En niños, personas mayores o debilitadas, evaluación médica.',NULL,NULL,false),
('tricholoma_ustale','fr','Surface du chapeau collante-visqueuse par temps humide, brun-rouge à brun châtain, souvent à centre plus sombre « brûlé ». Lamelles blanchâtres, se tachant de brun rouille avec l''âge. Sous hêtres et chênes sur sol acide. La confusion avec des tricholomes bruns comestibles est la principale voie d''intoxication.','Symptômes gastro-intestinaux (nausées, vomissements, diarrhées) 1 à 6 heures après ingestion, par inhibition de la Na+/K+-ATPase de l''épithélium intestinal (diarrhée osmotique). Spontanément résolutif, disparition généralement en 24 à 48 heures ; aucun décès documenté à ce jour.','En cas de suspicion, appeler immédiatement Tox Info Suisse 145 (24h). Conserver les restes/déchets de nettoyage pour la détermination. En cas de vomissements/diarrhées, veiller à un apport hydrique suffisant. Chez les enfants, les personnes âgées ou affaiblies, évaluation médicale.',NULL,NULL,false),
('tricholoma_ustale','it','Superficie del cappello collosa-viscida con tempo umido, da bruno-rosso a bruno castano, spesso con centro più scuro «bruciato». Lamelle biancastre, macchiate di bruno ruggine con l''età. Sotto faggi e querce su suolo acido. La confusione con tricolomi bruni commestibili è la principale via di avvelenamento.','Sintomi gastrointestinali (nausea, vomito, diarrea) 1-6 ore dopo l''ingestione, per inibizione della Na+/K+-ATPasi dell''epitelio intestinale (diarrea osmotica). Autolimitante, di solito si risolve entro 24-48 ore; finora nessun decesso documentato.','In caso di sospetto chiamare immediatamente Tox Info Suisse 145 (24h). Conservare i resti/scarti di pulitura per la determinazione. In caso di vomito/diarrea garantire un sufficiente apporto di liquidi. In bambini, anziani o persone debilitate, valutazione medica.',NULL,NULL,false),
('tricholoma_vaccinum','en','Red-brown cap with a strongly inrolled, woolly-bearded margin, fibrillose-scaly surface. Gills whitish, spotting rust-brown. Under spruces on acidic soil. The bitter taste and the felty-bearded cap margin are characteristic. Inedible because of bitterness and poor digestibility.','Not toxic in the strict sense, but bitter and hard to digest; eating larger amounts may cause gastrointestinal complaints.',NULL,NULL,NULL,false),
('tricholoma_vaccinum','es','Sombrero pardo-rojizo, con margen fuertemente enrollado, lanoso-barbado, superficie fibrilosa-escamosa. Láminas blanquecinas, manchándose de pardo herrumbroso. Bajo abetos rojos en suelo ácido. El sabor amargo y el margen del sombrero afieltrado-barbado son característicos. No comestible por su amargor y mala digestibilidad.','No tóxico en sentido estricto, pero amargo y difícil de digerir; al consumir grandes cantidades, posibles molestias gastrointestinales.',NULL,NULL,NULL,false),
('tricholoma_vaccinum','fr','Chapeau brun-rouge, à marge fortement enroulée, laineuse-barbue, surface fibrilleuse-squameuse. Lamelles blanchâtres, se tachant de brun rouille. Sous épicéas sur sol acide. Le goût amer et le bord du chapeau feutré-barbu sont caractéristiques. Non comestible en raison de l''amertume et de la mauvaise digestibilité.','Pas toxique au sens strict, mais amer et difficile à digérer ; en cas de consommation de grandes quantités, troubles gastro-intestinaux possibles.',NULL,NULL,NULL,false),
('tricholoma_vaccinum','it','Cappello bruno-rosso, con margine fortemente arrotolato, lanoso-barbato, superficie fibrilloso-squamosa. Lamelle biancastre, macchiate di bruno ruggine. Sotto abeti rossi su suolo acido. Il sapore amaro e il margine del cappello feltroso-barbato sono caratteristici. Non commestibile a causa dell''amarezza e della cattiva digeribilità.','Non tossico in senso stretto, ma amaro e di difficile digestione; in caso di consumo di grandi quantità, possibili disturbi gastrointestinali.',NULL,NULL,NULL,false),
('vascellum_pratense','en','Top-shaped to pear-shaped, when young white and finely spiny (spines fleeting), later dirty yellowish-olive. Diagnostic: in longitudinal section a distinct membranous DIAPHRAGM separates the spore-forming gleba (above) from the sterile subgleba (below) — a distinguishing feature versus true Bovista/Lycoperdon. Edible only while the gleba is PURE WHITE. Cut every round meadow find lengthwise — white, round young Amanita ''eggs'' (deadly) show embryonic gill/cap rudiments in section.',NULL,NULL,'Only young specimens that are pure white inside. Cut lengthwise (diaphragm visible, Amanita-egg exclusion). Peel off the outer skin, fry in slices. Discard discoloured (yellow/brown) mushrooms.',NULL,false),
('vascellum_pratense','es','En forma de peonza-piriforme, de joven blanco y finamente espinoso (aguijones fugaces), luego amarillento-oliváceo sucio. Diagnóstico: en sección longitudinal un DIAFRAGMA membranoso neto separa la gleba esporífera (arriba) de la subgleba estéril (abajo) — carácter distintivo frente a los verdaderos Bovista/Lycoperdon. Comestible solo mientras la gleba sea BLANCA PURA. Cortar longitudinalmente cada hallazgo globoso de pradera — los «huevos» de Amanita jóvenes, blancos y globosos (mortales) muestran en sección el esbozo de láminas/sombrero.',NULL,NULL,'Solo ejemplares jóvenes, de un blanco puro en el interior. Cortar longitudinalmente (diafragma visible, exclusión del huevo de Amanita). Retirar la piel externa, freír en rodajas. Desechar las setas descoloridas (amarillas/pardas).',NULL,false),
('vascellum_pratense','fr','En forme de toupie-piriforme, jeune blanc et finement épineux (aiguillons fugaces), puis jaunâtre-olive sale. Diagnostique : en coupe longitudinale, un DIAPHRAGME membraneux net sépare la gléba sporifère (en haut) de la subgléba stérile (en bas) — caractère distinctif vis-à-vis des vrais Bovista/Lycoperdon. Comestible uniquement tant que la gléba est PARFAITEMENT BLANCHE. Couper longitudinalement chaque trouvaille globuleuse de prairie — les jeunes « œufs » d''Amanita blancs et globuleux (mortels) montrent en coupe l''ébauche de lamelles/chapeau.',NULL,NULL,'Uniquement les jeunes exemplaires d''un blanc pur à l''intérieur. Couper longitudinalement (diaphragme visible, exclusion de l''œuf d''Amanita). Retirer la peau externe, faire revenir en tranches. Jeter les champignons décolorés (jaunes/bruns).',NULL,false),
('vascellum_pratense','it','A forma di trottola-piriforme, da giovane bianco e finemente spinoso (aculei caduchi), poi giallastro-olivastro sporco. Diagnostico: in sezione longitudinale un netto DIAFRAMMA membranoso separa la gleba sporifera (in alto) dalla subgleba sterile (in basso) — carattere distintivo rispetto ai veri Bovista/Lycoperdon. Commestibile solo finché la gleba è PERFETTAMENTE BIANCA. Tagliare longitudinalmente ogni ritrovamento globoso di prato — le giovani «uova» di Amanita bianche e globose (mortali) mostrano in sezione l''abbozzo di lamelle/cappello.',NULL,NULL,'Solo esemplari giovani, di un bianco puro all''interno. Tagliare longitudinalmente (diaframma visibile, esclusione dell''uovo di Amanita). Asportare la pelle esterna, rosolare a fette. Gettare i funghi scoloriti (gialli/bruni).',NULL,false),
('volvariella_bombycina','en','WARNING: white mushroom with a membranous sheath (volva) at the stem base and a silky-woolly white cap. Gills free, pink when old, spore print pink. Grows high up on deciduous trees/in branch holes. Because of the volva + white cap, high risk of confusion with the deadly white death caps (Amanita phalloides var. alba, A. verna, A. virosa) — these, however, have a WHITE spore print, a ring and grow on the ground. Also rare and worthy of protection.','The species itself is not toxic, but because of the risk of confusion with deadly white death caps (amanitin) it is NOT recommended for consumption. In case of accidental ingestion of a confused Amanita: amanitin syndrome (delayed symptoms after 6-24h, liver failure).','At any suspicion of confusion with a white death cap, call Tox Info Suisse 145 IMMEDIATELY — even if there are (as yet) no symptoms. Amanitin poisonings have a deceptive symptom-free latent phase.',NULL,NULL,false),
('volvariella_bombycina','es','ADVERTENCIA: seta blanca con vaina membranosa (volva) en la base del pie y sombrero blanco sedoso-lanoso. Láminas libres, rosadas al envejecer, esporada rosa. Crece en lo alto de árboles caducifolios/en huecos de ramas. Debido a la volva + sombrero blanco, alto riesgo de confusión con las amanitas blancas mortales (Amanita phalloides var. alba, A. verna, A. virosa) — estas, sin embargo, tienen esporada BLANCA, un anillo y crecen en el suelo. Además rara y digna de protección.','La especie en sí no es tóxica, pero por el riesgo de confusión con las amanitas blancas mortales (amanitina) NO se recomienda para el consumo. En caso de ingestión accidental de una amanita confundida: síndrome amanitínico (síntomas tardíos tras 6-24h, insuficiencia hepática).','Ante cualquier sospecha de confusión con una amanita blanca, llamar INMEDIATAMENTE a Tox Info Suisse 145 — aunque (todavía) no haya síntomas. Las intoxicaciones por amanitina tienen una fase de latencia engañosa, sin síntomas.',NULL,NULL,false),
('volvariella_bombycina','fr','AVERTISSEMENT : champignon blanc à volve membraneuse à la base du pied et chapeau blanc soyeux-laineux. Lamelles libres, roses à maturité, sporée rose. Pousse haut sur les feuillus/dans les cavités de branches. En raison de la volve + du chapeau blanc, fort risque de confusion avec les amanites blanches mortelles (Amanita phalloides var. alba, A. verna, A. virosa) — celles-ci ont toutefois une sporée BLANCHE, un anneau et poussent au sol. De plus rare et digne de protection.','L''espèce elle-même n''est pas toxique, mais en raison du risque de confusion avec les amanites blanches mortelles (amanitine), elle n''est PAS recommandée à la consommation. En cas d''ingestion accidentelle d''une amanite confondue : syndrome amanitien (symptômes retardés après 6-24h, insuffisance hépatique).','À tout soupçon de confusion avec une amanite blanche, appeler IMMÉDIATEMENT Tox Info Suisse 145 — même en l''absence (encore) de symptômes. Les intoxications à l''amanitine ont une phase de latence trompeuse, sans symptôme.',NULL,NULL,false),
('volvariella_bombycina','it','AVVERTENZA: fungo bianco con volva membranosa alla base del gambo e cappello bianco serico-lanoso. Lamelle libere, rosa a maturità, sporata rosa. Cresce in alto sulle latifoglie/nelle cavità dei rami. A causa della volva + cappello bianco, alto rischio di confusione con le amanite bianche mortali (Amanita phalloides var. alba, A. verna, A. virosa) — queste hanno però sporata BIANCA, un anello e crescono al suolo. Inoltre rara e meritevole di protezione.','La specie in sé non è tossica, ma a causa del rischio di confusione con le amanite bianche mortali (amanitina) NON è raccomandata per il consumo. In caso di ingestione accidentale di un''amanita confusa: sindrome amanitina (sintomi ritardati dopo 6-24h, insufficienza epatica).','A qualsiasi sospetto di confusione con un''amanita bianca chiamare IMMEDIATAMENTE Tox Info Suisse 145 — anche in assenza (ancora) di sintomi. Le intossicazioni da amanitina hanno una fase di latenza ingannevole, priva di sintomi.',NULL,NULL,false),
('xerocomellus_chrysenteron','en','Cap velvety-felted, cracking into areolae when dry, revealing a reddish coloration in the cracks (hence the name). Stem with red longitudinal fibres/dots. Flesh weakly bluing above the tubes. Young, firm specimens are edible; older ones are often maggoty and infested by the toxic gold mould (Hypomyces chrysospermus, whitish to yellow coatings) — do not collect infested mushrooms.',NULL,NULL,'Use only young, firm, mould-free specimens. Suitable for mixed dishes, watery and soft on its own. Cook thoroughly. Discard if there is a whitish/grey/blackish mouldy coating (Hypomyces).',NULL,false),
('xerocomellus_chrysenteron','es','Sombrero aterciopelado-afieltrado, agrietado en areolas con tiempo seco, con una coloración rojiza en las grietas (de ahí su nombre). Pie con fibras/puntos rojos longitudinales. Carne que azulea débilmente sobre los tubos. Los ejemplares jóvenes y firmes son comestibles; los más viejos suelen estar agusanados e infestados por el moho dorado tóxico (Hypomyces chrysospermus, recubrimientos blanquecinos a amarillos) — no recolectar los hongos infestados.',NULL,NULL,'Utilizar solo ejemplares jóvenes, firmes y libres de moho. Apto para platos mixtos, acuoso y blando por sí solo. Cocinar bien a fondo. Desechar si hay un recubrimiento mohoso blanquecino/gris/negruzco (Hypomyces).',NULL,false),
('xerocomellus_chrysenteron','fr','Chapeau velouté-feutré, se craquelant en aréoles par temps sec, laissant apparaître une coloration rougeâtre dans les fissures (à l''origine du nom). Pied à fibres/points rouges longitudinaux. Chair bleuissant faiblement au-dessus des tubes. Les jeunes exemplaires fermes sont comestibles, les plus âgés sont souvent véreux et attaqués par la moisissure dorée toxique (Hypomyces chrysospermus, revêtements blanchâtres à jaunes) — ne pas récolter les champignons atteints.',NULL,NULL,'N''utiliser que des exemplaires jeunes, fermes et exempts de moisissure. Convient aux plats mélangés, aqueux et mou par lui-même. Bien cuire à cœur. Jeter en cas de revêtement moisi blanchâtre/gris/noirâtre (Hypomyces).',NULL,false),
('xerocomellus_chrysenteron','it','Cappello vellutato-feltrato, screpolato in areole con tempo secco, con colorazione rossastra nelle screpolature (da cui il nome). Gambo con fibre/punti rossi longitudinali. Carne debolmente virante all''azzurro sopra i tubuli. Gli esemplari giovani e sodi sono commestibili, quelli più vecchi spesso bacati e attaccati dalla muffa dorata tossica (Hypomyces chrysospermus, rivestimenti biancastro-gialli) — non raccogliere i funghi infestati.',NULL,NULL,'Utilizzare solo esemplari giovani, sodi e privi di muffa. Adatto a piatti misti, acquoso e molle da solo. Cuocere bene a fondo. Scartare in caso di rivestimento ammuffito biancastro/grigio/nerastro (Hypomyces).',NULL,false),
('xerocomellus_pruinatus','en','Very similar to the common red-cracking bolete, but cap darker when young (purple-brown to black-brown) and finely pruinose-whitish (young), not as strongly cracked into areolae. Cap flesh beneath the cuticle pink/carmine-red. Flesh blues. Use only young, firm specimens; susceptible to the gold mould (Hypomyces).',NULL,NULL,'Only young, firm specimens; for mixed dishes, cook thoroughly. Discard if affected by mould (Hypomyces, whitish to yellow).',NULL,false),
('xerocomellus_pruinatus','es','Muy similar al boleto de pie rojo común, pero con el sombrero más oscuro de joven (pardo púrpura a pardo negro) y finamente pruinoso-blanquecino (de joven), no tan fuertemente agrietado en areolas. Carne del sombrero bajo la cutícula rosa/rojo carmín. Carne que azulea. Utilizar solo ejemplares jóvenes y firmes; susceptible al moho dorado (Hypomyces).',NULL,NULL,'Solo ejemplares jóvenes y firmes; para platos mixtos, cocinar bien a fondo. Desechar si está afectado por moho (Hypomyces, blanquecino a amarillo).',NULL,false),
('xerocomellus_pruinatus','fr','Très semblable au bolet à pied rouge commun, mais chapeau plus foncé étant jeune (brun pourpre à brun noir) et finement pruineux-blanchâtre (jeune), moins fortement craquelé en aréoles. Chair du chapeau sous la cuticule rose/rouge carmin. Chair bleuissante. N''utiliser que des exemplaires jeunes et fermes ; sensible à la moisissure dorée (Hypomyces).',NULL,NULL,'Uniquement des exemplaires jeunes et fermes ; pour plats mélangés, bien cuire à cœur. Jeter en cas d''attaque de moisissure (Hypomyces, blanchâtre à jaune).',NULL,false),
('xerocomellus_pruinatus','it','Molto simile al boleto dal piede rosso comune, ma cappello più scuro da giovane (bruno-purpureo a bruno-nero) e finemente pruinoso-biancastro (da giovane), meno fortemente screpolato in areole. Carne del cappello sotto la cuticola rosa/rosso carminio. Carne virante all''azzurro. Utilizzare solo esemplari giovani e sodi; soggetto alla muffa dorata (Hypomyces).',NULL,NULL,'Solo esemplari giovani e sodi; per piatti misti, cuocere bene a fondo. Scartare in caso di attacco di muffa (Hypomyces, biancastro-giallo).',NULL,false)
